const TEXTS = [{"topic":"Gezondheid","title":"Bewegen is goed voor je, maar hoeveel is genoeg?","paragraphs":["Veel mensen weten dat bewegen gezond is, maar ze vragen zich af hoeveel beweging ze eigenlijk nodig hebben. Volgens de Nederlandse gezondheidsnormen is het aanbevolen om elke week minstens 150 minuten matig intensief te bewegen. Dat betekent iets doen waarbij je hartslag stijgt en je licht buiten adem raakt, zoals stevig wandelen of fietsen.","Toch halen veel Nederlanders deze norm niet. Uit onderzoek blijkt dat ruim de helft van de bevolking te weinig beweegt. Mensen zeggen vaak dat ze geen tijd hebben, maar ook een korte wandeling van tien minuten telt mee. Bovendien is het bewezen dat regelmatig bewegen stress vermindert en de slaap verbetert.","Sporten in een sportschool is niet de enige manier om actief te zijn. Trap lopen in plaats van de lift nemen, de fiets pakken naar het werk, of in de tuin werken zijn ook goede manieren om meer te bewegen. Het gaat erom dat je minder lang stilzit en vaker je lichaam gebruikt.","Mensen die op latere leeftijd beginnen met bewegen, merken al snel verbeteringen in hun gezondheid. Het is dus nooit te laat om te starten. Zelfs kleine veranderingen in je dagelijkse routine kunnen een groot verschil maken voor je gezondheid op de lange termijn."],"questions":[{"text":"Hoeveel minuten per week moeten Nederlanders minimaal bewegen?","type":"Detail","options":["100 minuten","150 minuten","200 minuten","250 minuten"],"correct":1,"highlight":"minstens 150 minuten matig intensief te bewegen","feedback":{"ok":"Goed! De norm is 150 minuten per week.","nee":"Niet juist. Alinea 1 noemt 150 minuten als aanbevolen norm."}},{"text":"Waarom bewegen veel Nederlanders te weinig?","type":"Detail","options":["Ze vinden bewegen saai.","Ze zeggen dat ze geen tijd hebben.","Ze wonen te ver van een sportschool.","Ze zijn bang voor blessures."],"correct":1,"highlight":"Mensen zeggen vaak dat ze geen tijd hebben","feedback":{"ok":"Correct! Mensen zeggen dat ze geen tijd hebben.","nee":"Niet correct. Alinea 2 zegt dat mensen zeggen geen tijd te hebben."}},{"text":"Wat suggereert de tekst als alternatief voor de sportschool?","type":"Inferentie","options":["Elke dag zwemmen.","Altijd de auto nemen.","Trap lopen in plaats van de lift.","Een personal trainer inhuren."],"correct":2,"highlight":"Trap lopen in plaats van de lift nemen","feedback":{"ok":"Goed! Alinea 3 noemt de trap als voorbeeld.","nee":"Niet juist. Zie alinea 3: trap lopen, fietsen, tuinieren."}},{"text":"Wat betekent 'matig intensief bewegen'?","type":"Woordbetekenis","options":["Heel zwaar sporten.","Rustig wandelen zonder inspanning.","Je hartslag stijgt en je raakt licht buiten adem.","Zwemmen in een wedstrijd."],"correct":2,"highlight":"je hartslag stijgt en je licht buiten adem raakt","feedback":{"ok":"Juist! Matig intensief = hartslag omhoog, licht buiten adem.","nee":"Niet juist. Alinea 1 legt 'matig intensief' zo uit."}},{"text":"Wat is de hoofdboodschap van deze tekst?","type":"Hoofdgedachte","options":["Ga elke dag naar de sportschool.","Bewegen helpt alleen jonge mensen.","Kleine veranderingen kunnen al een groot verschil maken.","Alleen intensief sporten telt mee."],"correct":2,"highlight":"Zelfs kleine veranderingen in je dagelijkse routine kunnen een groot verschil maken","feedback":{"ok":"Prima! Kleine veranderingen maken al een groot verschil.","nee":"Niet helemaal. De kern is dat kleine veranderingen al een groot verschil kunnen maken."}}]},{"topic":"Wonen","title":"Tiny houses: klein wonen als grote trend","paragraphs":["In Nederland groeit de interesse in tiny houses. Dit zijn kleine, compacte woningen van meestal tussen de vijftien en vijftig vierkante meter. Ze zijn populair bij mensen die bewust minder willen consumeren, goedkoper willen wonen, of dicht bij de natuur willen leven.","Een tiny house kopen is goedkoper dan een gewone woning, maar het vinden van een geschikte plek is vaak moeilijk. Niet alle gemeenten staan toe dat je een tiny house op een perceel plaatst. Er zijn speciale tiny house parken in opkomst, maar die hebben lange wachtlijsten.","Leven in een tiny house vraagt om aanpassing. Je hebt minder ruimte voor spullen, dus je moet goed nadenken over wat je echt nodig hebt. Veel bewoners zeggen dat ze na een tijdje merken dat ze zich vrijer voelen omdat ze minder bezittingen hebben.","Critici wijzen erop dat tiny houses niet voor iedereen geschikt zijn. Gezinnen met kinderen hebben meer ruimte nodig, en in de winter kan een kleine ruimte snel koud aanvoelen. Toch zien steeds meer mensen het als een aantrekkelijke manier om de woonlasten te verlagen en duurzamer te leven."],"questions":[{"text":"Hoe groot is een tiny house meestal?","type":"Detail","options":["5-15 m²","Meer dan 100 m²","15-50 m²","50-80 m²"],"correct":2,"highlight":"tussen de vijftien en vijftig vierkante meter","feedback":{"ok":"Goed! Tussen 15 en 50 m².","nee":"Niet juist. Alinea 1: tussen 15 en 50 vierkante meter."}},{"text":"Wat is een van de grootste problemen bij het kopen van een tiny house?","type":"Detail","options":["Ze zijn te duur.","De bouw duurt erg lang.","Er zijn te weinig modellen.","Het is moeilijk een geschikte plek te vinden."],"correct":3,"highlight":"het vinden van een geschikte plek is vaak moeilijk","feedback":{"ok":"Correct! Een geschikte locatie vinden is het probleem.","nee":"Niet correct. Alinea 2 noemt het vinden van een plek als groot probleem."}},{"text":"Wat zeggen veel bewoners over hun ervaring?","type":"Detail","options":["Ze missen hun oude huis.","Ze willen snel weer verhuizen.","Ze voelen zich vrijer door minder bezittingen.","Ze vinden de ruimte te koud."],"correct":2,"highlight":"ze zich vrijer voelen omdat ze minder bezittingen hebben","feedback":{"ok":"Juist! Bewoners voelen zich vrijer met minder bezittingen.","nee":"Niet juist. Alinea 3: bewoners voelen zich vrijer."}},{"text":"Wat betekent 'woonlasten' (alinea 4)?","type":"Woordbetekenis","options":["De grootte van je huis","De afstand tot je werk","De kwaliteit van je buurt","De kosten van je woning"],"correct":3,"highlight":"woonlasten te verlagen en duurzamer te leven","feedback":{"ok":"Goed! Woonlasten = kosten voor je woning.","nee":"Niet juist. 'Woonlasten' zijn de kosten die je voor je woning betaalt."}},{"text":"Welke groep vindt tiny houses minder geschikt?","type":"Inferentie","options":["Mensen die dicht bij natuur willen wonen","Bewuste consumenten","Gezinnen met kinderen","Mensen die goedkoper willen wonen"],"correct":2,"highlight":"Gezinnen met kinderen hebben meer ruimte nodig","feedback":{"ok":"Correct! Gezinnen met kinderen hebben meer ruimte nodig.","nee":"Niet correct. Alinea 4 noemt gezinnen met kinderen."}}]},{"topic":"Werk","title":"Thuiswerken: voordeel of nadeel?","paragraphs":["Tijdens de coronapandemie moesten veel mensen thuis gaan werken. Sindsdien is thuiswerken in Nederland heel gewoon geworden. Veel bedrijven bieden nu een hybride werkmodel aan, waarbij werknemers een deel van de week thuis werken en een deel op kantoor.","Thuiswerken heeft duidelijke voordelen. Je bespaart reistijd en reiskosten, en je kunt je werkdag flexibeler indelen. Veel mensen geven aan dat ze thuis beter kunnen concentreren omdat er minder afleidingen zijn dan op kantoor.","Maar thuiswerken kent ook nadelen. Sommige mensen missen het sociale contact met collega's. De grens tussen werk en privé kan vervagen, waardoor mensen moeilijker kunnen stoppen met werken. Daarnaast heeft niet iedereen thuis een fijne werkplek met een goede stoel en voldoende licht.","Bedrijven merken dat het hybride model populair is, maar ze vinden het soms moeilijk om de samenwerking tussen collega's goed te houden. Er wordt steeds meer nagedacht over hoe kantoren ingericht moeten worden om samenwerken te bevorderen op de dagen dat mensen wel op kantoor komen."],"questions":[{"text":"Wat is een hybride werkmodel?","type":"Woordbetekenis","options":["Altijd thuis werken","Werken in het buitenland","Altijd op kantoor werken","Deels thuis en deels op kantoor werken"],"correct":3,"highlight":"werknemers een deel van de week thuis werken en een deel op kantoor","feedback":{"ok":"Goed! Hybride = deels thuis, deels op kantoor.","nee":"Niet juist. Alinea 1: deels thuis én deels op kantoor."}},{"text":"Waarom kunnen mensen thuis beter concentreren?","type":"Detail","options":["Ze beginnen thuis eerder.","Ze hebben een betere computer thuis.","Er zijn thuis minder afleidingen dan op kantoor.","Ze hebben meer collega's om te helpen."],"correct":2,"highlight":"ze thuis beter kunnen concentreren omdat er minder afleidingen zijn","feedback":{"ok":"Correct! Minder afleidingen thuis.","nee":"Niet correct. Alinea 2: minder afleidingen dan op kantoor."}},{"text":"Wat is een nadeel van thuiswerken?","type":"Detail","options":["Je verdient minder.","Je moet elke dag reizen.","Je hebt geen toegang tot software.","Je mist contact met collega's."],"correct":3,"highlight":"Sommige mensen missen het sociale contact met collegaâs","feedback":{"ok":"Goed! Missen van sociaal contact is een nadeel.","nee":"Niet juist. Alinea 3 noemt het missen van contact met collega's."}},{"text":"Wat betekent 'de grens tussen werk en privé kan vervagen'?","type":"Woordbetekenis","options":["Je werkt op meerdere plekken.","Je collega's weten niet waar je woont.","Je privéleven wordt gecontroleerd.","Het wordt moeilijk te scheiden wanneer je werkt en wanneer niet."],"correct":3,"highlight":"De grens tussen werk en privé kan vervagen, waardoor mensen moeilijker kunnen stoppen met werken","feedback":{"ok":"Juist! Vervagen = het onderscheid wordt onduidelijk.","nee":"Niet juist. Vervagen betekent dat het onderscheid wazig wordt."}},{"text":"Waarom denken bedrijven na over kantoorinrichting?","type":"Inferentie","options":["Omdat huurprijzen te hoog zijn.","Kantoren zijn te groot geworden.","Om meer mensen thuis te laten werken.","Om samenwerken te bevorderen op kantoordagen."],"correct":3,"highlight":"hoe kantoren ingericht moeten worden om samenwerken te bevorderen","feedback":{"ok":"Prima! Kantoren worden ingericht voor betere samenwerking.","nee":"Niet correct. Alinea 4: kantoren worden heringericht voor samenwerking."}}]},{"topic":"Natuur","title":"Het Nederlandse landschap: van veen tot delta","paragraphs":["Nederland is een van de laagstgelegen landen ter wereld. Grote delen van het land liggen onder zeeniveau. Dit is mogelijk dankzij een uitgebreid systeem van dijken, gemalen en sluizen dat het water op afstand houdt. Zonder dit systeem zou een groot deel van het westen en noorden van het land regelmatig overstromen.","Het landschap van Nederland is door eeuwen van menselijk ingrijpen sterk veranderd. Vroeger bestond een groot deel van het land uit moeras en veen. Door het droogleggen van polders en het afgraven van veen ontstonden de vlakke, open weilanden die nu zo kenmerkend zijn voor het Nederlandse landschap.","De rivieren Rijn, Maas en Waal spelen een belangrijke rol in het landschap. Ze voeren water af vanuit het bergachtige binnenland van Europa naar de Noordzee. In de delta waar ze in zee uitstromen, hebben ze een rijke natuur gecreëerd met rietlanden, zandbanken en getijdengebieden.","Het Nederlandse landschap staat vandaag de dag onder druk door klimaatverandering. De zeespiegel stijgt en extreme regenval komt vaker voor. De overheid en waterschappen werken samen om het land ook in de toekomst droog en veilig te houden, maar dit vraagt om steeds grotere investeringen."],"questions":[{"text":"Waardoor is het mogelijk dat grote delen van Nederland onder zeeniveau liggen?","type":"Detail","options":["Het land ligt op een hoog plateau.","Dankzij speciale bouwmaterialen.","De zee is in Nederland minder hoog.","Dankzij dijken, gemalen en sluizen."],"correct":3,"highlight":"een uitgebreid systeem van dijken, gemalen en sluizen dat het water op afstand houdt","feedback":{"ok":"Goed! Dijken, gemalen en sluizen houden het water op afstand.","nee":"Niet juist. Alinea 1: het systeem van dijken, gemalen en sluizen."}},{"text":"Hoe zag het Nederlandse landschap er vroeger uit?","type":"Detail","options":["Een uitgestrekt strand.","Bergachtig met bossen.","Een droge, zandige vlakte.","Een groot moeras- en veengebied."],"correct":3,"highlight":"Vroeger bestond een groot deel van het land uit moeras en veen","feedback":{"ok":"Correct! Vroeger bestond het land grotendeels uit moeras en veen.","nee":"Niet correct. Alinea 2: vroeger moeras en veen."}},{"text":"Waar stromen de Rijn, Maas en Waal naartoe?","type":"Detail","options":["Middellandse Zee.","IJsselmeer.","Atlantische Oceaan.","Noordzee."],"correct":3,"highlight":"Ze voeren water af vanuit het bergachtige binnenland van Europa naar de Noordzee","feedback":{"ok":"Juist! De rivieren stromen naar de Noordzee.","nee":"Niet juist. Alinea 3: de rivieren voeren water af naar de Noordzee."}},{"text":"Wat betekent 'getijdengebied' (alinea 3)?","type":"Woordbetekenis","options":["Een gebied met veel bomen.","Een gebied waar rivieren samenkomen.","Een gebied met alleen zandduinen.","Een gebied dat afwisselend droogvalt en onderloopt door het getij."],"correct":3,"highlight":"rietlanden, zandbanken en getijdengebieden","feedback":{"ok":"Goed! Een getijdengebied staat onder invloed van eb en vloed.","nee":"Niet juist. Een getijdengebied wordt bepaald door eb en vloed."}},{"text":"Welke uitdaging noemt de tekst voor de toekomst?","type":"Hoofdgedachte","options":["Te veel mensen in het westen.","Tekort aan rivierwater.","Te weinig natuur door landbouw.","Klimaatverandering en stijgende zeespiegel."],"correct":3,"highlight":"De zeespiegel stijgt en extreme regenval komt vaker voor","feedback":{"ok":"Prima! Klimaatverandering en stijgende zeespiegel zijn de grote uitdagingen.","nee":"Niet correct. Alinea 4: klimaatverandering en stijgende zeespiegel."}}]},{"topic":"Onderwijs","title":"Leren met je telefoon: kans of afleiding?","paragraphs":["Smartphones zijn niet meer weg te denken uit het dagelijks leven van jongeren. Steeds meer scholen experimenteren met apps en digitale hulpmiddelen in de les. Voorstanders zeggen dat technologie het leren interessanter en persoonlijker kan maken. Leerlingen kunnen in hun eigen tempo werken en direct feedback krijgen.","Tegelijkertijd zijn er zorgen over de keerzijde van smartphones in de klas. Onderzoek toont aan dat leerlingen die hun telefoon naast zich hebben liggen, moeilijker kunnen focussen — zelfs als de telefoon uitstaat. De verleiding om te scrollen of berichten te checken is voor veel jongeren te groot.","Sommige scholen hebben daarom gekozen voor een telefoonverbod. Leerlingen moeten hun telefoon bij binnenkomst inleveren in een kluisje. Voorstanders van dit beleid melden betere concentratie en meer sociale interactie op het schoolplein. Tegenstanders vinden dat jongeren moeten leren omgaan met digitale verleidingen.","Het debat over telefoons op school is niet snel opgelost. Veel hangt af van de manier waarop een school technologie inzet. Wordt de telefoon ingezet als leermiddel met duidelijke regels, of is het een vrij beschikbaar apparaat zonder begeleiding? Het antwoord bepaalt grotendeels of technologie helpt of schaadt in het onderwijs."],"questions":[{"text":"Wat zeggen voorstanders over smartphones in de les?","type":"Detail","options":["Ze zijn goedkoper dan boeken.","Ze vervangen de leraar volledig.","Ze zijn noodzakelijk voor huiswerk.","Ze maken leren interessanter en persoonlijker."],"correct":3,"highlight":"technologie het leren interessanter en persoonlijker kan maken","feedback":{"ok":"Goed! Interessanter en persoonlijker leren.","nee":"Niet juist. Alinea 1: technologie maakt leren interessanter en persoonlijker."}},{"text":"Wat toont onderzoek aan over telefoons naast leerlingen?","type":"Detail","options":["Oudere leerlingen worden niet gestoord.","Leerlingen leren sneller.","Leerlingen focussen moeilijker, zelfs als de telefoon uitstaat.","Telefoons storen alleen als ze aanstaan."],"correct":2,"highlight":"leerlingen die hun telefoon naast zich hebben liggen, moeilijker kunnen focussen","feedback":{"ok":"Correct! Zelfs een uitgestaande telefoon naast je vermindert focus.","nee":"Niet correct. Alinea 2: zelfs een uitgestaande telefoon is al storend."}},{"text":"Wat is een argument tegen een telefoonverbod?","type":"Inferentie","options":["Leraren weten niet hoe ze apps moeten gebruiken.","Telefoons zijn te duur om in kluisjes te bewaren.","Jongeren moeten leren omgaan met digitale verleidingen.","Telefoons zijn nodig voor noodgevallen."],"correct":2,"highlight":"Tegenstanders vinden dat jongeren moeten leren omgaan met digitale verleidingen","feedback":{"ok":"Juist! Jongeren moeten digitale verleidingen leren weerstaan.","nee":"Niet juist. Alinea 3: tegenstanders vinden dat jongeren dit moeten leren."}},{"text":"Wat betekent 'leermiddel' (alinea 4)?","type":"Woordbetekenis","options":["Een systeem om leerlingen te controleren","Een website voor leraren","Een apparaat om games te spelen","Een hulpmiddel om iets te leren"],"correct":3,"highlight":"Wordt de telefoon ingezet als leermiddel met duidelijke regels","feedback":{"ok":"Goed! Een leermiddel is een hulpmiddel bij het leren.","nee":"Niet juist. Een leermiddel is iets wat je helpt bij het leren."}},{"text":"Wat bepaalt of technologie helpt in het onderwijs?","type":"Hoofdgedachte","options":["Het merk van de telefoon.","Het aantal lessen per dag.","De leeftijd van de leerlingen.","De manier waarop een school technologie inzet."],"correct":3,"highlight":"Veel hangt af van de manier waarop een school technologie inzet","feedback":{"ok":"Prima! De manier van inzet bepaalt het effect.","nee":"Niet correct. Alinea 4: het hangt af van hoe de school technologie inzet."}}]},{"topic":"Vervoer","title":"De trein in Nederland: populair maar vol","paragraphs":["De NS, de Nederlandse Spoorwegen, vervoert elke dag ruim een miljoen reizigers. Het treinnetwerk verbindt vrijwel alle grote steden en veel kleinere plaatsen met elkaar. Voor veel mensen is de trein de snelste en gemakkelijkste manier om van A naar B te reizen, zeker tijdens de spits.","Toch kampt het treinverkeer in Nederland met problemen. Treinen rijden regelmatig te laat door storingen, werkzaamheden aan het spoor of problemen met de bovenleidingen. Reizigers klagen al jaren over overvolle coupés en onbetrouwbare verbindingen, vooral op drukke trajecten zoals Amsterdam-Utrecht.","De NS en de overheid werken aan verbeteringen. Er worden nieuwe treinen aangeschaft die meer capaciteit bieden. Ook wordt er geïnvesteerd in het verdubbelen van spoorlijnen, zodat er meer treinen kunnen rijden op populaire routes. Maar dit soort grote projecten kost jaren en veel geld.","Een alternatief dat steeds populairder wordt, is de combinatie van fiets en trein. Reizigers pakken de fiets naar het station en stappen dan in de trein. Op veel stations zijn grote fietsenstallingen gebouwd om hieraan tegemoet te komen. Deze combinatie wordt gezien als een duurzame oplossing voor de drukte op de wegen en in de treinen."],"questions":[{"text":"Hoeveel reizigers vervoert de NS per dag?","type":"Detail","options":["Meer dan twee miljoen","Ruim honderdduizend","Ruim een half miljoen","Ruim een miljoen"],"correct":3,"highlight":"vervoert elke dag ruim een miljoen reizigers","feedback":{"ok":"Goed! Ruim een miljoen reizigers per dag.","nee":"Niet juist. Alinea 1: ruim een miljoen reizigers per dag."}},{"text":"Wat is een veelgenoemde klacht van treinreizigers?","type":"Detail","options":["Er zijn te weinig stations.","Treinen zijn te duur.","De treinen zijn te oud.","Overvolle coupés en onbetrouwbare verbindingen."],"correct":3,"highlight":"Reizigers klagen al jaren over overvolle coupés en onbetrouwbare verbindingen","feedback":{"ok":"Correct! Overvolle coupés en onbetrouwbare verbindingen.","nee":"Niet correct. Alinea 2: overvolle coupés en onbetrouwbare verbindingen."}},{"text":"Wat is een oplossing die de NS en overheid nemen?","type":"Detail","options":["Treinprijzen verlagen.","Minder treinen laten rijden.","Het treinnet inkrimpen.","Nieuwe treinen aanschaffen met meer capaciteit."],"correct":3,"highlight":"Er worden nieuwe treinen aangeschaft die meer capaciteit bieden","feedback":{"ok":"Juist! Nieuwe treinen met meer capaciteit.","nee":"Niet juist. Alinea 3: nieuwe treinen aanschaffen die meer capaciteit bieden."}},{"text":"Wat betekent 'capaciteit' (alinea 3)?","type":"Woordbetekenis","options":["De staat van het spoor","De snelheid van een trein","De prijs van een treinkaartje","Het aantal mensen of dingen dat iets kan bevatten"],"correct":3,"highlight":"nieuwe treinen aangeschaft die meer capaciteit bieden","feedback":{"ok":"Goed! Capaciteit = hoeveel iets kan bevatten of vervoeren.","nee":"Niet juist. Capaciteit verwijst naar het aantal mensen dat iets kan vervoeren."}},{"text":"Waarom wordt de combinatie fiets en trein als duurzame oplossing gezien?","type":"Inferentie","options":["Fietsenstallingen zijn goedkoop te bouwen.","Het is goedkoper dan alleen de trein.","Fietsen is sneller dan treinrijden.","Het vermindert de drukte op wegen en in treinen."],"correct":3,"highlight":"Deze combinatie wordt gezien als een duurzame oplossing voor de drukte op de wegen en in de treinen","feedback":{"ok":"Prima! Minder drukte op wegen én in treinen.","nee":"Niet correct. Alinea 4: de combinatie vermindert drukte op wegen en in treinen."}}]},{"topic":"Milieu","title":"Plastic soep: het probleem in onze oceanen","paragraphs":["Elk jaar belandt er miljoenen ton plastic afval in de oceanen. Dit plastic breekt niet af, maar valt uiteen in steeds kleinere deeltjes, zogenaamde microplastics. Vissen en andere zeedieren eten deze deeltjes, waardoor ze in de voedselketen terechtkomen — en uiteindelijk ook op ons bord.","De term 'plastic soep' werd populair nadat onderzoekers grote concentraties plastic ontdekten in de Stille Oceaan. Het plastic komt uit rivieren, van stranden en uit het riool. Vooral wegwerpplastic zoals flesjes, rietjes en tasjes zijn grote boosdoeners.","Overheden en organisaties proberen het probleem aan te pakken. De Europese Unie heeft wegwerpplastic zoals plastic rietjes en roerstaafjes verboden. Supermarkten vragen een vergoeding voor plastic tassen om het gebruik te verminderen. Maar experts zeggen dat deze maatregelen niet genoeg zijn.","Consumenten kunnen ook zelf bijdragen. Minder plastic gebruiken, afval goed scheiden en kiezen voor herbruikbare producten zijn kleine stappen die samen een groot verschil kunnen maken. Maar een echte oplossing vraagt om samenwerking tussen bedrijven, overheden en burgers wereldwijd."],"questions":[{"text":"Wat zijn microplastics?","type":"Woordbetekenis","options":["Een soort kunststof voor verpakkingen","Grote stukken plastic in zee","Plastic tasjes in winkels","Zeer kleine plastic deeltjes"],"correct":3,"highlight":"valt uiteen in steeds kleinere deeltjes, zogenaamde microplastics","feedback":{"ok":"Goed! Microplastics zijn zeer kleine plastic deeltjes.","nee":"Niet juist. Alinea 1: microplastics zijn kleine deeltjes die ontstaan als plastic uiteenvalt."}},{"text":"Waar komt het plastic in de oceanen vandaan?","type":"Detail","options":["Alleen van schepen.","Van onderwaterpijplijnen.","Alleen van de visindustrie.","Uit rivieren, stranden en het riool."],"correct":3,"highlight":"Het plastic komt uit rivieren, van stranden en uit het riool","feedback":{"ok":"Correct! Rivieren, stranden en riool.","nee":"Niet correct. Alinea 2: rivieren, stranden en riool."}},{"text":"Welke maatregel heeft de EU genomen?","type":"Detail","options":["Plastic auto-onderdelen verboden.","Alle plastic verpakkingen verboden.","Plastic speelgoed verboden.","Wegwerpplastic zoals rietjes en roerstaafjes verboden."],"correct":3,"highlight":"De Europese Unie heeft wegwerpplastic zoals plastic rietjes en roerstaafjes verboden","feedback":{"ok":"Juist! Plastic rietjes en roerstaafjes zijn verboden door de EU.","nee":"Niet juist. Alinea 3: de EU verbood plastic rietjes en roerstaafjes."}},{"text":"Wat kunnen consumenten zelf doen?","type":"Inferentie","options":["Naar de overheid schrijven.","Alleen biologisch voedsel kopen.","Plastic afval in zee gooien.","Minder plastic gebruiken en kiezen voor herbruikbare producten."],"correct":3,"highlight":"Minder plastic gebruiken, afval goed scheiden en kiezen voor herbruikbare producten","feedback":{"ok":"Goed! Minder plastic en herbruikbare producten.","nee":"Niet juist. Alinea 4: minder plastic, goed scheiden en herbruikbare producten."}},{"text":"Wat is de hoofdboodschap van de tekst?","type":"Hoofdgedachte","options":["Plastic in oceanen is al volledig opgelost.","Microplastics zijn onschadelijk voor mensen.","Alleen overheden kunnen plastic soep oplossen.","Het plastic probleem vraagt om samenwerking en actie van consumenten."],"correct":3,"highlight":"een echte oplossing vraagt om samenwerking tussen bedrijven, overheden en burgers wereldwijd","feedback":{"ok":"Prima! Samenwerking op alle niveaus is nodig.","nee":"Niet helemaal. De tekst benadrukt dat samenwerking op alle niveaus nodig is."}}]},{"topic":"Taal & cultuur","title":"Nederlands leren als volwassene: uitdaging en kans","paragraphs":["Elk jaar beginnen tienduizenden mensen in Nederland aan een cursus Nederlands als tweede taal, ook wel NT2 genoemd. Het gaat om nieuwkomers, expats en mensen die al jaren in Nederland wonen maar de taal nog niet goed spreken. De motivaties zijn divers: werk vinden, beter communiceren met buren, of inburgeren.","Nederlands wordt door veel leerders als een moeilijke taal beschouwd. De uitspraak is lastig, met klanken die in andere talen niet voorkomen, zoals de 'g' en de 'ui'. Ook de grammatica, met de twee lidwoorden 'de' en 'het', geeft veel mensen hoofdbrekens. Toch zeggen veel cursisten dat ze snel vooruitgang merken als ze de taal ook buiten de les oefenen.","Taalscholen, gemeenten en bibliotheken bieden NT2-cursussen aan op verschillende niveaus. Het staatsexamen NT2 is een officieel examen dat bestaat uit vier onderdelen: lezen, luisteren, schrijven en spreken. Dit examen is verplicht voor mensen die willen inburgeren of een permanente verblijfsvergunning willen aanvragen.","Experts adviseren om zoveel mogelijk Nederlands te spreken in het dagelijks leven. Televisie kijken met Nederlandse ondertiteling, Nederlandse kranten lezen of vrijwilligerswerk doen zijn goede manieren om de taal te oefenen. De sleutel is: niet bang zijn om fouten te maken, want van fouten leer je het meest."],"questions":[{"text":"Wie volgen NT2-cursussen?","type":"Detail","options":["Alleen studenten aan Nederlandse universiteiten.","Alleen nieuwkomers uit vluchtelingenkampen.","Alleen mensen met een werkvergunning.","Nieuwkomers, expats en mensen die al jaren in Nederland wonen."],"correct":3,"highlight":"nieuwkomers, expats en mensen die al jaren in Nederland wonen maar de taal nog niet goed spreken","feedback":{"ok":"Goed! Nieuwkomers, expats én langdurige inwoners.","nee":"Niet juist. Alinea 1: nieuwkomers, expats en mensen die al jaren in Nederland wonen."}},{"text":"Wat vinden veel leerders moeilijk aan het Nederlands?","type":"Detail","options":["Het schrijven van brieven.","De uitspraak en de twee lidwoorden 'de' en 'het'.","Het leren van cijfers en getallen.","De lange zinnen in kranten."],"correct":1,"highlight":"De uitspraak is lastig","feedback":{"ok":"Correct! Uitspraak en de lidwoorden zijn bekende struikelblokken.","nee":"Niet correct. Alinea 2: de uitspraak en de lidwoorden 'de' en 'het' zijn moeilijk."}},{"text":"Waarvoor is het staatsexamen NT2 verplicht?","type":"Detail","options":["Voor werk bij de Nederlandse overheid.","Voor toegang tot universiteiten.","Voor alle nieuwe inwoners direct bij aankomst.","Voor inburgering of een permanente verblijfsvergunning."],"correct":3,"highlight":"verplicht voor mensen die willen inburgeren of een permanente verblijfsvergunning willen aanvragen","feedback":{"ok":"Juist! Voor inburgering of een permanente verblijfsvergunning.","nee":"Niet juist. Alinea 3: verplicht voor inburgering of een permanente verblijfsvergunning."}},{"text":"Wat adviseren experts om de taal te verbeteren?","type":"Inferentie","options":["Alleen schriftelijk oefenen.","Pas spreken als je perfect bent.","Alleen naar taalschool gaan.","Zoveel mogelijk Nederlands spreken in het dagelijks leven."],"correct":3,"highlight":"zoveel mogelijk Nederlands te spreken in het dagelijks leven","feedback":{"ok":"Goed! Oefenen in het dagelijks leven is het advies.","nee":"Niet juist. Alinea 4: experts adviseren zoveel mogelijk Nederlands te spreken."}},{"text":"Wat is de sleutel tot succes bij het leren van Nederlands?","type":"Hoofdgedachte","options":["Een taalapp gebruiken.","Heel veel geld investeren in cursussen.","Alleen met Nederlanders omgaan.","Niet bang zijn om fouten te maken."],"correct":3,"highlight":"niet bang zijn om fouten te maken, want van fouten leer je het meest","feedback":{"ok":"Prima! Niet bang zijn voor fouten — daar leer je van.","nee":"Niet correct. Alinea 4: de sleutel is niet bang zijn om fouten te maken."}}]},{"topic":"Duurzaamheid","title":"Zonnepanelen in Nederland: een zonnige toekomst?","paragraphs":["Nederland telt inmiddels meer dan drie miljoen huishoudens met zonnepanelen op het dak. Dat is een enorme groei vergeleken met tien jaar geleden, toen zonnepanelen nog schaars en erg duur waren. De dalende kosten en subsidies van de overheid hebben de populariteit sterk vergroot.","Zonnepanelen produceren elektriciteit uit zonlicht. In Nederland schijnt de zon minder dan in landen als Spanje of Italië, maar er is genoeg zonlicht om zonnepanelen rendabel te maken. Op een zonnige dag kan een gemiddeld huishouden meer stroom opwekken dan het zelf gebruikt, en het overschot kan worden teruggeleverd aan het elektriciteitsnet.","Niet iedereen kan echter zonnepanelen plaatsen. Mensen die in een huurhuis of appartement wonen, zijn afhankelijk van de beslissing van hun verhuurder of vereniging van eigenaars. Bovendien zijn niet alle daken geschikt vanwege de richting of schaduw van bomen en andere gebouwen.","De Nederlandse overheid stimuleert de overgang naar hernieuwbare energie, maar er zijn ook zorgen. Het elektriciteitsnet is op sommige plekken overbelast doordat er te veel stroom tegelijk wordt ingevoed. Netbeheerders werken aan uitbreidingen, maar dat kost tijd en geld."],"questions":[{"text":"Waardoor zijn zonnepanelen populairder geworden?","type":"Detail","options":["Buurlanden begonnen er ook mee.","De zon schijnt meer dan vroeger.","Huurhuizen zijn verplicht panelen te plaatsen.","Dalende kosten en overheidssubsidies."],"correct":3,"highlight":"De dalende kosten en subsidies van de overheid hebben de populariteit sterk vergroot","feedback":{"ok":"Goed! Dalende kosten en subsidies zijn de reden.","nee":"Niet juist. Alinea 1: dalende kosten en overheidssubsidies."}},{"text":"Wat gebeurt er als een huishouden meer stroom opwekt dan het gebruikt?","type":"Detail","options":["De stroom gaat verloren.","De panelen stoppen automatisch.","Het overschot wordt in een batterij opgeslagen.","Het overschot wordt teruggeleverd aan het net."],"correct":3,"highlight":"het overschot kan worden teruggeleverd aan het elektriciteitsnet","feedback":{"ok":"Correct! Het overschot gaat terug naar het net.","nee":"Niet correct. Alinea 2: terugleveren aan het elektriciteitsnet."}},{"text":"Waarom kunnen niet alle mensen zonnepanelen plaatsen?","type":"Inferentie","options":["De montage duurt te lang.","De overheid staat het niet toe.","Ze zijn nog te duur.","Huurders zijn afhankelijk van hun verhuurder."],"correct":3,"highlight":"zijn afhankelijk van de beslissing van hun verhuurder of vereniging van eigenaars","feedback":{"ok":"Juist! Huurders hebben toestemming nodig van de verhuurder.","nee":"Niet juist. Alinea 3: huurders zijn afhankelijk van hun verhuurder."}},{"text":"Wat betekent 'hernieuwbare energie' (alinea 4)?","type":"Woordbetekenis","options":["Energie die duurder is","Energie die 's nachts beschikbaar is","Energie uit gas","Energie die niet opraakt, zoals zon en wind"],"correct":3,"highlight":"de overgang naar hernieuwbare energie","feedback":{"ok":"Goed! Hernieuwbare energie raakt niet op.","nee":"Niet juist. Hernieuwbaar = onuitputtelijke bronnen zoals zon en wind."}},{"text":"Welk probleem noemt de tekst voor het elektriciteitsnet?","type":"Detail","options":["Het net is niet geschikt voor thuisopslag.","Zonnepanelen leveren stroom van slechte kwaliteit.","Te weinig stroom voor industrie.","Het net raakt overbelast door te veel gelijktijdige invoeding."],"correct":3,"highlight":"Het elektriciteitsnet is op sommige plekken overbelast doordat er te veel stroom tegelijk wordt ingevoed","feedback":{"ok":"Prima! Overbelasting door te veel gelijktijdige invoeding.","nee":"Niet correct. Alinea 4: overbelasting doordat er te veel stroom tegelijk wordt ingevoed."}}]},{"topic":"Maatschappij","title":"Vrijwilligerswerk in Nederland: wie doet het en waarom?","paragraphs":["Nederland heeft een sterke traditie van vrijwilligerswerk. Ongeveer vier op de tien Nederlanders doen regelmatig vrijwilligerswerk. Ze helpen bij sportverenigingen, zorginstellingen, buurthuizen of voedselbanken. Zonder vrijwilligers zouden veel maatschappelijke voorzieningen niet kunnen functioneren.","Mensen doen vrijwilligerswerk om verschillende redenen. Sommigen willen iets terugdoen voor de samenleving, anderen willen nieuwe mensen ontmoeten of iets leren. Er zijn ook mensen die vrijwilligerswerk doen om werkervaring op te doen of om hun cv te versterken, vooral als ze werkloos zijn.","Toch staat het vrijwilligerswerk in Nederland onder druk. Het aantal mensen dat zich opgeeft als vrijwilliger daalt langzaam. Organisaties merken dat mensen minder tijd willen vastleggen en liever kortdurend of eenmalig helpen. De verwachting dat iemand elke week beschikbaar is, schrikt velen af.","Organisaties spelen hierop in door flexibeler te worden. Ze bieden projecten aan waarbij iemand één dag of een weekend helpt in plaats van een vaste wekelijkse verplichting. Zo hopen ze ook jongere generaties aan te trekken, die het moeilijk vinden om langdurige verplichtingen aan te gaan."],"questions":[{"text":"Hoeveel Nederlanders doen regelmatig vrijwilligerswerk?","type":"Detail","options":["Acht op de tien","Twee op de tien","Één op de tien","Vier op de tien"],"correct":3,"highlight":"Ongeveer vier op de tien Nederlanders doen regelmatig vrijwilligerswerk","feedback":{"ok":"Goed! Vier op de tien Nederlanders.","nee":"Niet juist. Alinea 1: vier op de tien Nederlanders."}},{"text":"Waarom doen werklozen vrijwilligerswerk?","type":"Detail","options":["Ze worden door de overheid verplicht.","Ze willen een eigen bedrijf starten.","Ze worden er goed voor betaald.","Ze willen werkervaring opdoen en hun cv versterken."],"correct":3,"highlight":"vrijwilligerswerk doen om werkervaring op te doen of om hun cv te versterken, vooral als ze werkloos zijn","feedback":{"ok":"Correct! Werkervaring opdoen en cv versterken.","nee":"Niet correct. Alinea 2: werkervaring en cv versterken."}},{"text":"Waarom daalt het aantal vrijwilligers?","type":"Inferentie","options":["Vrijwilligerswerk is wettelijk beperkt.","Er is minder behoefte aan vrijwilligers.","Vrijwilligerswerk wordt slechter betaald.","Mensen willen liever kortdurend helpen dan vaste verplichtingen."],"correct":3,"highlight":"mensen minder tijd willen vastleggen en liever kortdurend of eenmalig helpen","feedback":{"ok":"Juist! Mensen vermijden vaste, langdurige verplichtingen.","nee":"Niet juist. Alinea 3: mensen willen liever kortdurend of eenmalig helpen."}},{"text":"Wat betekent 'maatschappelijke voorzieningen' (alinea 1)?","type":"Woordbetekenis","options":["Overheidsgebouwen","Commerciële bedrijven","Luxediensten voor rijken","Diensten nuttig voor de samenleving"],"correct":3,"highlight":"Zonder vrijwilligers zouden veel maatschappelijke voorzieningen niet kunnen functioneren","feedback":{"ok":"Goed! Maatschappelijke voorzieningen zijn diensten voor de samenleving.","nee":"Niet juist. Maatschappelijke voorzieningen zijn diensten die de samenleving ten goede komen."}},{"text":"Hoe proberen organisaties meer vrijwilligers aan te trekken?","type":"Detail","options":["Door vrijwilligerswerk verplicht te stellen.","Door de minimumleeftijd te verlagen.","Door hogere vergoedingen.","Door flexibelere, kortdurende projecten."],"correct":3,"highlight":"Ze bieden projecten aan waarbij iemand één dag of een weekend helpt","feedback":{"ok":"Prima! Kortdurende, flexibele projecten.","nee":"Niet correct. Alinea 4: kortdurende projecten zoals één dag of een weekend."}}]},{"topic":"Economie","title":"De boerenmarkt: nostalgie of echte trend?","paragraphs":["In veel Nederlandse steden en dorpen zijn boerenmarkten populairder dan ooit. Op deze markten verkopen lokale boeren en producenten direct aan de consument, zonder tussenkomst van supermarkten of groothandels. Je vindt er verse groenten, fruit, zuivel, vlees en ambachtelijke producten zoals kaas en jam.","Mensen gaan naar de boerenmarkt om verschillende redenen. Sommigen willen weten waar hun eten vandaan komt en kiezen bewust voor lokale producten. Anderen genieten van de gezellige sfeer en de persoonlijke aandacht van de verkopers. En er zijn mensen die vinden dat producten op de boerenmarkt lekkerder smaken dan die uit de supermarkt.","Toch zijn er ook kritische geluiden. Producten op de boerenmarkt zijn vaak duurder dan in de supermarkt. Niet iedereen kan zich dat veroorloven. Bovendien is het aanbod seizoensgebonden: in de winter zijn er minder verse producten beschikbaar dan in de zomer.","Voor boeren biedt de markt een kans om een eerlijkere prijs te krijgen voor hun producten. In de reguliere supermarktwereld worden boeren soms onder druk gezet om hun producten voor een lage prijs te verkopen. Op de boerenmarkt kunnen ze zelf bepalen wat ze vragen en direct contact onderhouden met hun klanten."],"questions":[{"text":"Wat is kenmerkend voor een boerenmarkt?","type":"Detail","options":["Er zijn alleen biologische producten.","Het is een online marktplaats.","Producten zijn altijd goedkoper dan in de supermarkt.","Lokale producenten verkopen direct aan de consument."],"correct":3,"highlight":"lokale boeren en producenten direct aan de consument, zonder tussenkomst van supermarkten of groothandels","feedback":{"ok":"Goed! Direct van producent naar consument, zonder tussenpersoon.","nee":"Niet juist. Alinea 1: lokale producenten verkopen direct aan de consument."}},{"text":"Waarom gaan sommige mensen naar de boerenmarkt?","type":"Detail","options":["Omdat er nooit rijen zijn.","Omdat supermarkten te ver weg zijn.","Omdat de producten altijd goedkoper zijn.","Omdat ze willen weten waar hun eten vandaan komt."],"correct":3,"highlight":"Sommigen willen weten waar hun eten vandaan komt en kiezen bewust voor lokale producten","feedback":{"ok":"Correct! Ze willen weten waar hun eten vandaan komt.","nee":"Niet correct. Alinea 2: sommigen willen weten waar hun eten vandaan komt."}},{"text":"Wat is een nadeel van de boerenmarkt?","type":"Detail","options":["Er is te weinig keuze.","Er zijn geen verse producten beschikbaar.","De markten zijn altijd overvol.","Producten zijn vaak duurder dan in de supermarkt."],"correct":3,"highlight":"Producten op de boerenmarkt zijn vaak duurder dan in de supermarkt","feedback":{"ok":"Juist! De hogere prijs is een nadeel.","nee":"Niet juist. Alinea 3: producten zijn vaak duurder dan in de supermarkt."}},{"text":"Wat betekent 'seizoensgebonden' (alinea 3)?","type":"Woordbetekenis","options":["Duurder in de winter","Alleen 's zomers verkrijgbaar","Het hele jaar beschikbaar","Afhankelijk van het seizoen"],"correct":3,"highlight":"het aanbod seizoensgebonden: in de winter zijn er minder verse producten beschikbaar","feedback":{"ok":"Goed! Seizoensgebonden = afhankelijk van het seizoen.","nee":"Niet juist. Seizoensgebonden betekent dat iets afhangt van het seizoen."}},{"text":"Welk voordeel biedt de boerenmarkt voor boeren?","type":"Inferentie","options":["Ze kunnen hun producten langer bewaren.","Ze hoeven geen belasting te betalen.","Ze kunnen meer producten verkopen dan via de supermarkt.","Ze kunnen zelf de prijs bepalen en direct contact hebben met klanten."],"correct":3,"highlight":"kunnen ze zelf bepalen wat ze vragen en direct contact onderhouden met hun klanten","feedback":{"ok":"Prima! Zelf prijs bepalen en direct klantcontact.","nee":"Niet correct. Alinea 4: boeren kunnen zelf de prijs bepalen en direct contact hebben met klanten."}}]},{"topic":"Sport","title":"Hardlopen in Nederland: voor iedereen?","paragraphs":["Hardlopen is een van de populairste sporten in Nederland. Meer dan drie miljoen Nederlanders lopen regelmatig hard. Je hebt er weinig voor nodig: een paar goede schoenen en een geschikte route. Daardoor is het een van de goedkoopste sporten die er zijn.","De populariteit van hardlopen is de afgelopen jaren verder gegroeid. Grote evenementen zoals de Dam tot Damloop en de marathon van Rotterdam en Amsterdam trekken tienduizenden deelnemers en toeschouwers. Veel lopers trainen maandenlang om zo'n evenement te kunnen voltooien.","Hardlopen heeft duidelijke gezondheidsvoordelen. Het versterkt het hart en de spieren, en helpt bij het op een gezond gewicht blijven. Maar er zijn ook risico's. Blessures zoals knieproblemen en spierblessures komen veel voor, vooral als mensen te snel te veel gaan lopen.","Experts adviseren om rustig te beginnen en de trainingsintensiteit langzaam op te bouwen. Een goede warming-up en cooling-down zijn belangrijk, net als de juiste schoenen voor je loopstijl. Beginners kunnen het best starten met een loopprogramma dat afwisselt tussen lopen en wandelen."],"questions":[{"text":"Hoeveel Nederlanders lopen regelmatig hard?","type":"Detail","options":["Meer dan vijf miljoen","Meer dan een miljoen","Meer dan twee miljoen","Meer dan drie miljoen"],"correct":3,"highlight":"Meer dan drie miljoen Nederlanders lopen regelmatig hard","feedback":{"ok":"Goed! Meer dan drie miljoen Nederlanders.","nee":"Niet juist. Alinea 1: meer dan drie miljoen Nederlanders."}},{"text":"Waarom is hardlopen een van de goedkoopste sporten?","type":"Inferentie","options":["Sportschoenen zijn in Nederland goedkoop.","Je kunt gratis trainen bij een coach.","Je hebt alleen goede schoenen en een route nodig.","Je hebt een duur lidmaatschap nodig."],"correct":2,"highlight":"Je hebt er weinig voor nodig: een paar goede schoenen en een geschikte route","feedback":{"ok":"Correct! Je hebt weinig materiaal nodig.","nee":"Niet correct. Alinea 1: je hebt alleen goede schoenen en een route nodig."}},{"text":"Wat zijn risico's van hardlopen?","type":"Detail","options":["Gewrichtsversterking.","Oververhitting in de winter.","Te weinig calorieën verbranden.","Knieproblemen en spierblessures."],"correct":3,"highlight":"Blessures zoals knieproblemen en spierblessures komen veel voor","feedback":{"ok":"Juist! Knieproblemen en spierblessures zijn veelvoorkomende risico's.","nee":"Niet juist. Alinea 3: knieproblemen en spierblessures komen veel voor."}},{"text":"Wat adviseren experts voor beginners?","type":"Detail","options":["Alleen lopen op een loopband.","Direct starten met een marathon.","Elke dag minimaal tien kilometer lopen.","Beginnen met een programma dat afwisselt tussen lopen en wandelen."],"correct":3,"highlight":"Beginners kunnen het best starten met een loopprogramma dat afwisselt tussen lopen en wandelen","feedback":{"ok":"Goed! Afwisselen tussen lopen en wandelen voor beginners.","nee":"Niet juist. Alinea 4: een programma dat afwisselt tussen lopen en wandelen."}},{"text":"Wat betekent 'trainingsintensiteit' (alinea 4)?","type":"Woordbetekenis","options":["De kosten van je training","Hoe lang je traint","Hoe vaak je per week traint","Hoe zwaar of intensief je traint"],"correct":3,"highlight":"de trainingsintensiteit langzaam op te bouwen","feedback":{"ok":"Goed! Trainingsintensiteit = hoe zwaar of intensief je traint.","nee":"Niet juist. Trainingsintensiteit verwijst naar de zwaarte van je training."}}]},{"topic":"Geschiedenis","title":"Anne Frank: een verhaal dat de wereld raakte","paragraphs":["Anne Frank was een joods meisje dat tijdens de Tweede Wereldoorlog samen met haar familie ondergedoken zat in een achterhuis in Amsterdam. Ze was dertien jaar oud toen ze begon met het bijhouden van een dagboek. Daarin schreef ze over haar dagelijkse leven, haar dromen en haar angsten.","Het achterhuis bevond zich op de Prinsengracht in Amsterdam. Twee jaar lang leefde de familie Frank er in het geheim, samen met vier andere onderduikers. Ze konden het gebouw niet verlaten en waren afhankelijk van hulp van vertrouwde medewerkers. In augustus 1944 werden ze ontdekt en gearresteerd.","Anne Frank overleefde de oorlog niet. Ze stierf in februari 1945 in het concentratiekamp Bergen-Belsen, kort voor de bevrijding. Haar vader Otto Frank was de enige die de oorlog overleefde. Na de bevrijding liet hij het dagboek van Anne publiceren.","Het dagboek van Anne Frank is inmiddels in meer dan tachtig talen vertaald en wereldwijd meer dan dertig miljoen keer verkocht. Het Anne Frank Huis in Amsterdam trekt elk jaar meer dan een miljoen bezoekers. Het verhaal van Anne Frank herinnert mensen aan de gevaren van discriminatie en onverdraagzaamheid."],"questions":[{"text":"Hoe oud was Anne Frank toen ze begon met haar dagboek?","type":"Detail","options":["Veertien jaar","Elf jaar","Dertien jaar","Twaalf jaar"],"correct":2,"highlight":"Ze was dertien jaar oud toen ze begon met het bijhouden van een dagboek","feedback":{"ok":"Goed! Anne was dertien jaar oud.","nee":"Niet juist. Alinea 1: ze was dertien jaar oud."}},{"text":"Waar bevond het achterhuis zich?","type":"Detail","options":["In Rotterdam.","In Utrecht.","Op de Keizersgracht in Amsterdam.","Op de Prinsengracht in Amsterdam."],"correct":3,"highlight":"Het achterhuis bevond zich op de Prinsengracht in Amsterdam","feedback":{"ok":"Correct! Het achterhuis stond op de Prinsengracht.","nee":"Niet correct. Alinea 2: op de Prinsengracht in Amsterdam."}},{"text":"Hoe lang leefde de familie Frank ondergedoken?","type":"Detail","options":["Vier jaar","Drie jaar","Een jaar","Twee jaar"],"correct":3,"highlight":"Twee jaar lang leefde de familie Frank er in het geheim","feedback":{"ok":"Juist! Twee jaar lang.","nee":"Niet juist. Alinea 2: twee jaar lang."}},{"text":"Wat betekent 'onverdraagzaamheid' (alinea 4)?","type":"Woordbetekenis","options":["Het niet kunnen verdragen van pijn","Een houding van vriendelijkheid","Een ziekte die veel pijn veroorzaakt","Het niet accepteren van anderen die anders zijn"],"correct":3,"highlight":"de gevaren van discriminatie en onverdraagzaamheid","feedback":{"ok":"Goed! Onverdraagzaamheid = het niet accepteren van mensen die anders zijn.","nee":"Niet juist. Onverdraagzaamheid betekent het niet dulden van anderen."}},{"text":"Wat is het belang van het verhaal van Anne Frank?","type":"Hoofdgedachte","options":["Het is de beste manier om Duits te leren.","Het laat zien hoe Amsterdam er vroeger uitzag.","Het toont aan dat dagboeken schrijven nuttig is.","Het herinnert mensen aan de gevaren van discriminatie en onverdraagzaamheid."],"correct":3,"highlight":"Het verhaal van Anne Frank herinnert mensen aan de gevaren van discriminatie en onverdraagzaamheid","feedback":{"ok":"Prima! Het verhaal waarschuwt voor discriminatie en onverdraagzaamheid.","nee":"Niet correct. Alinea 4: het verhaal herinnert aan de gevaren van discriminatie."}}]},{"topic":"Gezondheidszorg","title":"De huisarts: eerste aanspreekpunt in de zorg","paragraphs":["In Nederland is de huisarts voor de meeste mensen het eerste aanspreekpunt als ze ziek zijn of klachten hebben. De huisarts kent zijn patiënten vaak al jaren en kan daardoor snel inschatten of iemand doorverwezen moet worden naar een specialist of dat een eenvoudige behandeling volstaat.","Nederland heeft een poortwachterssysteem in de gezondheidszorg. Dit betekent dat je bijna altijd eerst naar de huisarts moet voordat je een specialist kunt bezoeken. Dit systeem voorkomt dat specialisten overbelast raken met klachten die ook door de huisarts behandeld kunnen worden.","De werkdruk voor huisartsen is de afgelopen jaren sterk gestegen. Er zijn te weinig huisartsen voor het groeiende aantal patiënten. Wachttijden bij huisartsenpraktijken lopen op, en steeds meer mensen hebben moeite om een vaste huisarts te vinden. Dit is een groeiend probleem in Nederland.","Om de druk te verlichten, werken huisartsenpraktijken steeds vaker samen in grotere gezondheidscentra. Hier werken ook praktijkverpleegkundigen, diëtisten en fysiotherapeuten. Hierdoor kunnen patiënten voor meer soorten zorg terecht op één plek, en wordt de werkdruk beter verdeeld."],"questions":[{"text":"Wat is de rol van de huisarts?","type":"Detail","options":["De huisarts werkt alleen in ziekenhuizen.","De huisarts schrijft altijd medicijnen voor.","De huisarts vervangt specialisten volledig.","De huisarts is het eerste aanspreekpunt bij klachten."],"correct":3,"highlight":"de huisarts voor de meeste mensen het eerste aanspreekpunt","feedback":{"ok":"Goed! De huisarts is het eerste aanspreekpunt.","nee":"Niet juist. Alinea 1: de huisarts is het eerste aanspreekpunt bij klachten."}},{"text":"Wat is het poortwachterssysteem?","type":"Woordbetekenis","options":["Een systeem waarbij patiënten zelf een specialist kiezen.","Een systeem waarbij specialisten altijd direct bereikbaar zijn.","Een systeem waarbij zorgverzekeringen de toegang regelen.","Een systeem waarbij je eerst naar de huisarts moet voordat je een specialist kunt bezoeken."],"correct":3,"highlight":"je bijna altijd eerst naar de huisarts moet voordat je een specialist kunt bezoeken","feedback":{"ok":"Correct! Eerst naar de huisarts, dan eventueel naar de specialist.","nee":"Niet correct. Alinea 2: je moet eerst naar de huisarts."}},{"text":"Wat is een groeiend probleem bij huisartsen?","type":"Detail","options":["Patiënten vertrouwen huisartsen niet meer.","Huisartsen verdienen te weinig.","Huisartsenpraktijken zijn te groot geworden.","Er zijn te weinig huisartsen voor het groeiende aantal patiënten."],"correct":3,"highlight":"Er zijn te weinig huisartsen voor het groeiende aantal patiënten","feedback":{"ok":"Juist! Te weinig huisartsen voor te veel patiënten.","nee":"Niet juist. Alinea 3: er zijn te weinig huisartsen."}},{"text":"Hoe verlichten huisartsenpraktijken de werkdruk?","type":"Detail","options":["Door alleen nog digitale consulten aan te bieden.","Door patiënten direct naar de spoedeisende hulp te sturen.","Door minder patiënten aan te nemen.","Door samen te werken in grotere gezondheidscentra."],"correct":3,"highlight":"huisartsenpraktijken steeds vaker samen in grotere gezondheidscentra","feedback":{"ok":"Goed! Samenwerken in gezondheidscentra verlicht de druk.","nee":"Niet juist. Alinea 4: samenwerken in grotere gezondheidscentra."}},{"text":"Welk voordeel hebben gezondheidscentra voor patiënten?","type":"Inferentie","options":["Ze krijgen altijd dezelfde huisarts.","Ze hoeven nooit meer naar een ziekenhuis.","Ze kunnen goedkoper zorg krijgen.","Ze kunnen voor meer soorten zorg terecht op één plek."],"correct":3,"highlight":"kunnen patiënten voor meer soorten zorg terecht op één plek","feedback":{"ok":"Prima! Meer soorten zorg op één plek.","nee":"Niet correct. Alinea 4: patiënten kunnen voor meer soorten zorg terecht op één plek."}}]},{"topic":"Reizen","title":"Toerisme in Amsterdam: te veel of net genoeg?","paragraphs":["Amsterdam is een van de meest bezochte steden van Europa. Elk jaar komen er meer dan twintig miljoen toeristen naar de stad. Ze komen voor de grachten, de musea zoals het Rijksmuseum en het Van Gogh Museum, de bruine kroegen en de fietscultuur. De stad heeft een unieke sfeer die mensen van over de hele wereld aantrekt.","Maar de grote toestroom van toeristen zorgt ook voor problemen. Bewoners klagen over drukte, lawaai en stijgende huurprijzen. Populaire plekken zijn soms zo vol dat bewoners zich in hun eigen wijk niet meer thuis voelen. Er is ook overlast van groepen toeristen die zich misdragen.","De gemeente Amsterdam heeft verschillende maatregelen genomen om het toerisme te beperken. Nieuwe hotels mogen niet meer worden gebouwd in het stadscentrum. Toeristen die in de stad overnachten, betalen een hogere toeristenbelasting. En sommige populaire attracties werken alleen nog met reserveringen vooraf.","Niet iedereen is het eens met de aanpak van de gemeente. Horeca en winkels die van toeristen afhankelijk zijn, vrezen voor hun omzet. Ze zeggen dat toerisme ook veel oplevert voor de stad: werkgelegenheid, belastinginkomsten en internationale bekendheid. Het debat over de balans tussen leefbaarheid en toerisme gaat nog altijd door."],"questions":[{"text":"Hoeveel toeristen bezoeken Amsterdam elk jaar?","type":"Detail","options":["Meer dan vijfentwintig miljoen","Meer dan tien miljoen","Meer dan vijftien miljoen","Meer dan twintig miljoen"],"correct":3,"highlight":"Elk jaar komen er meer dan twintig miljoen toeristen naar de stad","feedback":{"ok":"Goed! Meer dan twintig miljoen toeristen per jaar.","nee":"Niet juist. Alinea 1: meer dan twintig miljoen toeristen per jaar."}},{"text":"Waarover klagen bewoners van Amsterdam?","type":"Detail","options":["Over slechte bereikbaarheid van de stad.","Over de hoge kosten van musea.","Over te weinig toeristen in de winter.","Over drukte, lawaai en stijgende huurprijzen."],"correct":3,"highlight":"Bewoners klagen over drukte, lawaai en stijgende huurprijzen","feedback":{"ok":"Correct! Drukte, lawaai en stijgende huurprijzen.","nee":"Niet correct. Alinea 2: bewoners klagen over drukte, lawaai en stijgende huurprijzen."}},{"text":"Welke maatregel heeft Amsterdam genomen?","type":"Detail","options":["Toeristen mogen maar twee dagen blijven.","Gratis openbaar vervoer voor bewoners.","Alle attracties zijn gratis voor bewoners.","Nieuwe hotels mogen niet meer worden gebouwd in het centrum."],"correct":3,"highlight":"Nieuwe hotels mogen niet meer worden gebouwd in het stadscentrum","feedback":{"ok":"Juist! Geen nieuwe hotels in het centrum.","nee":"Niet juist. Alinea 3: nieuwe hotels mogen niet meer worden gebouwd in het stadscentrum."}},{"text":"Wat betekent 'toeristenbelasting' (alinea 3)?","type":"Woordbetekenis","options":["Een belasting op souvenirs.","Een belasting op vliegtickets naar Amsterdam.","Een belasting die toeristen betalen als ze de stad beschadigen.","Een belasting die toeristen betalen als ze in de stad overnachten."],"correct":3,"highlight":"Toeristen die in de stad overnachten, betalen een hogere toeristenbelasting","feedback":{"ok":"Goed! Toeristenbelasting = een belasting voor toeristen die overnachten.","nee":"Niet juist. Toeristenbelasting is een belasting die je betaalt als je in een stad overnacht."}},{"text":"Waarom zijn horeca en winkels tegen het beperken van toerisme?","type":"Inferentie","options":["Ze denken dat bewoners van de toeristen profiteren.","Ze willen meer hotels bouwen.","Ze vinden dat toeristen geen overlast geven.","Ze vrezen voor hun omzet en zeggen dat toerisme veel oplevert."],"correct":3,"highlight":"vrezen voor hun omzet. Ze zeggen dat toerisme ook veel oplevert voor de stad","feedback":{"ok":"Prima! Ze vrezen voor hun omzet en noemen de voordelen van toerisme.","nee":"Niet correct. Alinea 4: horeca en winkels vrezen voor hun omzet."}}]},{"topic":"Wetenschap","title":"Slaap: waarom je er niet zonder kunt","paragraphs":["Slapen is een basisbehoefte van het menselijk lichaam, net als eten en drinken. Tijdens de slaap herstelt het lichaam zich: spieren worden gerepareerd, het immuunsysteem wordt versterkt en herinneringen worden verwerkt en opgeslagen. Wetenschappers zijn het erover eens dat volwassenen gemiddeld zeven tot negen uur slaap per nacht nodig hebben.","Toch slaapt een groot deel van de bevolking te weinig. Werkdruk, schermgebruik voor het slapengaan en stress zijn veelgenoemde oorzaken. Blauw licht van telefoons en tablets houdt de hersenen actief en verstoort de aanmaak van het slaaphormoon melatonine. Hierdoor duurt het langer voordat mensen in slaap vallen.","Chronisch slaaptekort heeft ernstige gevolgen. Het verhoogt het risico op hart- en vaatziekten, diabetes en depressie. Ook het geheugen en de concentratie worden aangetast. Mensen die structureel te weinig slapen, functioneren overdag slechter en maken vaker fouten.","Slaapexperts geven verschillende tips om beter te slapen. Ga op vaste tijden naar bed en sta op vaste tijden op, ook in het weekend. Vermijd schermen een uur voor het slapengaan. Zorg voor een koele, donkere en rustige slaapkamer. En beperk cafeïne in de namiddag en avond."],"questions":[{"text":"Hoeveel uur slaap hebben volwassenen gemiddeld nodig?","type":"Detail","options":["Acht tot tien uur","Vijf tot zeven uur","Zes tot acht uur","Zeven tot negen uur"],"correct":3,"highlight":"volwassenen gemiddeld zeven tot negen uur slaap per nacht nodig hebben","feedback":{"ok":"Goed! Zeven tot negen uur per nacht.","nee":"Niet juist. Alinea 1: zeven tot negen uur slaap per nacht."}},{"text":"Wat doet blauw licht van schermen met je lichaam?","type":"Detail","options":["Het verbetert de geheugenopslag.","Het verstoort de aanmaak van melatonine.","Het versterkt het immuunsysteem.","Het helpt je sneller in slaap vallen."],"correct":1,"highlight":"Blauw licht van telefoons en tablets houdt de hersenen actief en verstoort de aanmaak van het slaaphormoon melatonine","feedback":{"ok":"Correct! Blauw licht verstoort de aanmaak van melatonine.","nee":"Niet correct. Alinea 2: blauw licht verstoort de aanmaak van melatonine."}},{"text":"Welk gevolg heeft chronisch slaaptekort?","type":"Detail","options":["Je hebt minder honger.","Je hebt minder dromen.","Je wordt energieker overdag.","Het verhoogt het risico op hart- en vaatziekten en depressie."],"correct":3,"highlight":"Het verhoogt het risico op hart- en vaatziekten, diabetes en depressie","feedback":{"ok":"Juist! Slaaptekort verhoogt het risico op ernstige aandoeningen.","nee":"Niet juist. Alinea 3: slaaptekort verhoogt het risico op hart- en vaatziekten en depressie."}},{"text":"Wat betekent 'chronisch' (alinea 3)?","type":"Woordbetekenis","options":["Plotseling en onverwacht","Ernstig en ongeneeslijk","Eenmalig en tijdelijk","Langdurig en regelmatig terugkerend"],"correct":3,"highlight":"Chronisch slaaptekort heeft ernstige gevolgen","feedback":{"ok":"Goed! Chronisch = langdurig en regelmatig terugkerend.","nee":"Niet juist. Chronisch betekent langdurig en structureel aanwezig."}},{"text":"Wat raden slaapexperts aan voor een betere nachtrust?","type":"Detail","options":["Cafeïne drinken voor het slapengaan.","Elke nacht een ander slaaptijdstip kiezen.","Overdag zo lang mogelijk slapen.","Op vaste tijden naar bed gaan en schermen vermijden voor het slapengaan."],"correct":3,"highlight":"Ga op vaste tijden naar bed en sta op vaste tijden op","feedback":{"ok":"Prima! Vaste tijden en schermen vermijden zijn de adviezen.","nee":"Niet correct. Alinea 4: vaste tijden en schermen vermijden voor het slapengaan."}}]},{"topic":"Energie","title":"Windenergie in Nederland: wind mee of tegenwind?","paragraphs":["Nederland is een van de windrijkste landen van Europa. Met name langs de kust en op zee waait het bijna altijd. Het is dan ook niet verrassend dat windenergie een belangrijke rol speelt in de Nederlandse energietransitie. De overheid heeft als doel om in 2030 zeventig procent van alle elektriciteit uit hernieuwbare bronnen op te wekken.","Er zijn twee soorten windparken: windparken op land en windparken op zee. Windparken op zee, ook wel 'offshore' windparken genoemd, hebben grote voordelen. Ze staan verder van bewoonde gebieden af, de wind waait er constanter en de turbines kunnen groter zijn. Nadeel is dat ze duurder zijn om te bouwen en te onderhouden.","Windparken op land stuiten soms op weerstand van omwonenden. Mensen klagen over geluidsoverlast, slagschaduw — het flikkeren van schaduwen als de wieken draaien — en het effect op het landschap. Gemeenten moeten bij het plannen van windparken rekening houden met de belangen van omwonenden.","Ondanks de bezwaren groeit het aantal windturbines in Nederland snel. Windenergie is inmiddels een van de goedkoopste manieren om elektriciteit op te wekken. En met de stijgende energieprijzen en de noodzaak om minder afhankelijk te zijn van fossiele brandstoffen, wordt investeren in wind steeds aantrekkelijker."],"questions":[{"text":"Wat is het doel van de Nederlandse overheid voor 2030?","type":"Detail","options":["Alle kolencentrales sluiten.","50% minder energie gebruiken dan in 2020.","Alle energie uit windmolens halen.","70% van alle elektriciteit uit hernieuwbare bronnen opwekken."],"correct":3,"highlight":"De overheid heeft als doel om in 2030 zeventig procent van alle elektriciteit uit hernieuwbare bronnen op te wekken","feedback":{"ok":"Goed! 70% hernieuwbare elektriciteit in 2030.","nee":"Niet juist. Alinea 1: het doel is 70% hernieuwbare elektriciteit in 2030."}},{"text":"Wat is een voordeel van windparken op zee?","type":"Detail","options":["Ze zijn makkelijker te onderhouden.","Ze zijn goedkoper te bouwen.","Ze produceren meer elektriciteit in de zomer.","Ze staan verder van bewoonde gebieden en de wind waait er constanter."],"correct":3,"highlight":"Ze staan verder van bewoonde gebieden af, de wind waait er constanter en de turbines kunnen groter zijn","feedback":{"ok":"Correct! Verder van bewoning, constantere wind en grotere turbines.","nee":"Niet correct. Alinea 2: verder van bewoning, constantere wind, grotere turbines."}},{"text":"Wat is 'slagschaduw' (alinea 3)?","type":"Woordbetekenis","options":["De schaduw van grote gebouwen","Een technisch probleem met windturbines","Geluid dat windturbines produceren","Het flikkeren van schaduwen als de wieken draaien"],"correct":3,"highlight":"slagschaduw — het flikkeren van schaduwen als de wieken draaien","feedback":{"ok":"Goed! Slagschaduw = flikkerende schaduwen van draaiende wieken.","nee":"Niet juist. Alinea 3 legt slagschaduw uit als het flikkeren van schaduwen."}},{"text":"Wat klagen omwonenden over bij windparken op land?","type":"Detail","options":["Het gebrek aan windturbines in hun buurt.","De gevaren voor vogels.","De hoge kosten van stroom.","Geluidsoverlast, slagschaduw en effect op het landschap."],"correct":3,"highlight":"Mensen klagen over geluidsoverlast, slagschaduw","feedback":{"ok":"Juist! Geluidsoverlast, slagschaduw en landschapseffect.","nee":"Niet juist. Alinea 3: klachten over geluidsoverlast, slagschaduw en effect op het landschap."}},{"text":"Waarom wordt investeren in wind steeds aantrekkelijker?","type":"Inferentie","options":["Omdat de overheid subsidies afschaft.","Omdat windturbines steeds kleiner worden.","Omdat windenergie de enige hernieuwbare energiebron is.","Vanwege stijgende energieprijzen en de wens minder afhankelijk te zijn van fossiele brandstoffen."],"correct":3,"highlight":"met de stijgende energieprijzen en de noodzaak om minder afhankelijk te zijn van fossiele brandstoffen","feedback":{"ok":"Prima! Stijgende prijzen en minder fossiele brandstoffen.","nee":"Niet correct. Alinea 4: stijgende energieprijzen en minder afhankelijkheid van fossiele brandstoffen."}}]},{"topic":"Dieren","title":"De wolf is terug in Nederland","paragraphs":["Na meer dan honderd jaar afwezigheid is de wolf teruggekeerd in Nederland. De eerste wolf werd in 2015 gesignaleerd op de Veluwe. Sindsdien hebben zich meerdere wolven gevestigd en zijn er zelfs roedels — families van wolven — ontstaan. Het is een bijzondere ontwikkeling in een dichtbevolkt land als Nederland.","De terugkeer van de wolf zorgt voor enthousiasme bij natuurliefhebbers, maar ook voor bezorgdheid bij boeren. Wolven vallen schapen, geiten en soms koeien aan. Boeren worden financieel gecompenseerd als hun dieren door een wolf worden gedood, maar ze klagen dat de vergoedingen niet altijd voldoende zijn en dat het bureaucratische proces te lang duurt.","Om aanvallen te voorkomen, worden boeren aangeraden om elektrische rasters te plaatsen rond hun kuddes. De overheid subsidieert een deel van de kosten hiervoor. Ook worden waakhonden ingezet om het vee te beschermen. Maar in een land met zoveel wegen en bebouwing is het moeilijk om wolven en vee volledig van elkaar te scheiden.","Biologen wijzen erop dat de wolf een belangrijke rol speelt in het ecosysteem. Als roofdier houdt hij populaties van herten en reeën in evenwicht. Dit heeft op zijn beurt een positief effect op de vegetatie, omdat de grazers minder vrij rondlopen. De terugkeer van de wolf is daarmee niet alleen een uitdaging, maar ook een kans voor de Nederlandse natuur."],"questions":[{"text":"Wanneer werd de eerste wolf gesignaleerd in Nederland?","type":"Detail","options":["In 2018","In 2010","In 2013","In 2015"],"correct":3,"highlight":"De eerste wolf werd in 2015 gesignaleerd op de Veluwe","feedback":{"ok":"Goed! De eerste wolf werd in 2015 gesignaleerd.","nee":"Niet juist. Alinea 1: de eerste wolf werd in 2015 gesignaleerd."}},{"text":"Waarover klagen boeren bij de financiële compensatie?","type":"Detail","options":["Ze krijgen geen compensatie voor aanvallen op koeien.","De vergoedingen zijn te hoog.","De overheid betaalt alleen voor schapen.","De vergoedingen zijn niet altijd voldoende en het proces duurt te lang."],"correct":3,"highlight":"de vergoedingen niet altijd voldoende zijn en dat het bureaucratische proces te lang duurt","feedback":{"ok":"Correct! Onvoldoende vergoedingen en een traag proces.","nee":"Niet correct. Alinea 2: de vergoedingen zijn soms onvoldoende en het proces duurt te lang."}},{"text":"Wat wordt aangeraden om aanvallen van wolven te voorkomen?","type":"Detail","options":["Wolven vangen en verplaatsen.","Jagers inzetten om wolven te verjagen.","Vee 's nachts binnenhalen.","Elektrische rasters plaatsen rond kuddes."],"correct":3,"highlight":"worden boeren aangeraden om elektrische rasters te plaatsen rond hun kuddes","feedback":{"ok":"Juist! Elektrische rasters zijn de aanbevolen maatregel.","nee":"Niet juist. Alinea 3: elektrische rasters plaatsen rond de kuddes."}},{"text":"Wat betekent 'ecosysteem' (alinea 4)?","type":"Woordbetekenis","options":["Een beschermd bosgebied","Een gebied met alleen wilde dieren","Een wetenschappelijk laboratorium","Het geheel van levende wezens en hun omgeving die samen functioneren"],"correct":3,"highlight":"de wolf een belangrijke rol speelt in het ecosysteem","feedback":{"ok":"Goed! Een ecosysteem is het geheel van levende wezens en hun omgeving.","nee":"Niet juist. Een ecosysteem is het geheel van levende organismen en hun leefomgeving."}},{"text":"Welk positief effect heeft de wolf op de natuur?","type":"Inferentie","options":["De wolf helpt boeren door kleine dieren te verjagen.","De wolf vermindert het aantal auto-ongelukken met wilde dieren.","De wolf eet insecten die schadelijk zijn voor planten.","De wolf houdt herten- en reepopulaties in evenwicht, wat goed is voor de vegetatie."],"correct":3,"highlight":"houdt hij populaties van herten en reeën in evenwicht. Dit heeft op zijn beurt een positief effect op de vegetatie","feedback":{"ok":"Prima! De wolf reguleert grazers, wat de vegetatie ten goede komt.","nee":"Niet correct. Alinea 4: de wolf houdt herten- en reepopulaties in evenwicht."}}]},{"topic":"Winkelen","title":"De opkomst van online shoppen in Nederland","paragraphs":["Nederland behoort tot de landen met de hoogste percentages online shoppers in Europa. Bijna tachtig procent van de Nederlanders koopt regelmatig iets via internet. De coronapandemie heeft deze trend versneld: veel mensen die voorheen altijd in de winkel kochten, ontdekten het gemak van thuisbezorgd winkelen.","Het succes van online winkelen heeft grote gevolgen voor de fysieke winkelstraat. Veel winkels sloten hun deuren, waardoor leegstand in binnensteden een groeiend probleem is geworden. Gemeenten en ondernemers zoeken naar manieren om winkelgebieden aantrekkelijk te houden, bijvoorbeeld door meer horeca en beleving aan te bieden.","Bezorgdiensten en pakketbedrijven draaien op volle toeren. Elke dag rijden er duizenden bestelbusjes door Nederlandse wijken om pakketten af te leveren. Dit leidt tot meer verkeer en uitstoot in woonwijken. Steden zoals Amsterdam en Utrecht experimenteren met elektrische bezorgfietsen en pakketpunten om de overlast te verminderen.","Toch blijft de fysieke winkel voor veel mensen aantrekkelijk. Kleding passen, producten voelen en direct meenemen zijn voordelen die online shoppen niet kan bieden. Steeds meer succesvolle webwinkels openen ook een fysieke winkel, omdat ze merken dat klanten graag beide ervaringen combineren."],"questions":[{"text":"Hoeveel procent van de Nederlanders koopt regelmatig online?","type":"Detail","options":["Bijna zestig procent","Bijna vijftig procent","Bijna negentig procent","Bijna tachtig procent"],"correct":3,"highlight":"Bijna tachtig procent van de Nederlanders koopt regelmatig iets via internet","feedback":{"ok":"Goed! Bijna tachtig procent.","nee":"Niet juist. Alinea 1: bijna tachtig procent koopt regelmatig online."}},{"text":"Wat is een gevolg van online winkelen voor de winkelstraat?","type":"Detail","options":["Meer mensen gaan winkelen in het centrum.","Winkels worden groter.","Leegstand in binnensteden is een groeiend probleem geworden.","Winkeliers verdienen meer door hogere prijzen."],"correct":2,"highlight":"waardoor leegstand in binnensteden een groeiend probleem is geworden","feedback":{"ok":"Correct! Leegstand in binnensteden is een gevolg.","nee":"Niet correct. Alinea 2: leegstand in binnensteden is een groeiend probleem."}},{"text":"Hoe proberen steden de overlast van bezorgdiensten te verminderen?","type":"Detail","options":["Door online winkelen te verbieden.","Door extra parkeerplaatsen te bouwen.","Door meer bestelbusjes toe te staan.","Door elektrische bezorgfietsen en pakketpunten te gebruiken."],"correct":3,"highlight":"Steden zoals Amsterdam en Utrecht experimenteren met elektrische bezorgfietsen en pakketpunten","feedback":{"ok":"Juist! Elektrische fietsen en pakketpunten helpen de overlast te verminderen.","nee":"Niet juist. Alinea 3: elektrische bezorgfietsen en pakketpunten."}},{"text":"Wat betekent 'leegstand' (alinea 2)?","type":"Woordbetekenis","options":["Een winkel met veel klanten","Te veel producten op voorraad","Panden die leeg staan omdat er geen huurder voor is","Een straat zonder verkeer"],"correct":2,"highlight":"leegstand in binnensteden een groeiend probleem","feedback":{"ok":"Goed! Leegstand = panden die leeg staan zonder huurder.","nee":"Niet juist. Leegstand betekent dat panden leeg staan omdat er geen huurder voor gevonden wordt."}},{"text":"Waarom openen succesvolle webwinkels ook een fysieke winkel?","type":"Inferentie","options":["Omdat online winkelen te duur is geworden.","Omdat klanten graag beide ervaringen combineren.","Omdat de overheid dit verplicht stelt.","Omdat online adverteren niet meer werkt."],"correct":1,"highlight":"klanten graag beide ervaringen combineren","feedback":{"ok":"Prima! Klanten willen zowel online als in de winkel kunnen winkelen.","nee":"Niet correct. Alinea 4: klanten combineren graag de online en fysieke winkelervaring."}}]},{"topic":"Klimaat","title":"Droogte in Nederland: een nieuw normaal?","paragraphs":["Nederland staat bekend om zijn regenachtige klimaat, maar de afgelopen jaren hebben droge zomers steeds vaker voor problemen gezorgd. In 2018 en 2022 was er sprake van extreme droogte die leidde tot oogstschade bij boeren, lage waterstanden in rivieren en gevaar voor branden in natuurgebieden.","De droogte heeft grote gevolgen voor de landbouw. Gewassen verdrogen, grasland verschraalt en boeren moeten extra irrigeren om hun land productief te houden. Dit vergroot het waterverbruik, terwijl er juist minder water beschikbaar is. Sommige boeren overwegen hun gewassen aan te passen aan het droger wordende klimaat.","Ook de natuur lijdt onder de droogte. Veengebieden, die normaal gesproken veel water vasthouden, drogen uit en kunnen gaan smeulen. Eenmaal aangestoken zijn veenbrandjes moeilijk te blussen. Bovendien stoot uitdrogend veen grote hoeveelheden CO2 uit, wat de klimaatverandering verder versterkt.","Waterbeheerders en beleidsmakers zoeken naar oplossingen. Het beter vasthouden van regenwater, het verminderen van waterverbruik en het herstel van natuurlijke waterbergingsgebieden zijn mogelijke maatregelen. Experts waarschuwen dat Nederland zich structureel moet aanpassen aan een droger klimaat, ook al is de jaarlijkse regenval gemiddeld nog steeds relatief hoog."],"questions":[{"text":"In welke jaren was er sprake van extreme droogte in Nederland?","type":"Detail","options":["In 2015 en 2019","In 2019 en 2021","In 2016 en 2020","In 2018 en 2022"],"correct":3,"highlight":"In 2018 en 2022 was er sprake van extreme droogte","feedback":{"ok":"Goed! In 2018 en 2022 was er extreme droogte.","nee":"Niet juist. Alinea 1: in 2018 en 2022 was er extreme droogte."}},{"text":"Wat is een gevolg van droogte voor de landbouw?","type":"Detail","options":["Boeren hoeven minder te werken.","De oogst wordt groter door warmte.","Er is meer water beschikbaar voor irrigatie.","Gewassen verdrogen en boeren moeten extra irrigeren."],"correct":3,"highlight":"Gewassen verdrogen, grasland verschraalt en boeren moeten extra irrigeren","feedback":{"ok":"Correct! Gewassen verdrogen en boeren irrigeren meer.","nee":"Niet correct. Alinea 2: gewassen verdrogen en boeren moeten extra irrigeren."}},{"text":"Waarom zijn veenbrandjes gevaarlijk voor het klimaat?","type":"Inferentie","options":["Ze verspreiden giftige stoffen in het water.","Ze maken het moeilijk om te ademen in de omgeving.","Ze veroorzaken overstromingen.","Uitdrogend veen stoot grote hoeveelheden CO2 uit."],"correct":3,"highlight":"stoot uitdrogend veen grote hoeveelheden CO2 uit, wat de klimaatverandering verder versterkt","feedback":{"ok":"Juist! Uitdrogend veen stoot CO2 uit en versterkt de klimaatverandering.","nee":"Niet juist. Alinea 3: uitdrogend veen stoot CO2 uit."}},{"text":"Wat betekent 'waterberging' (alinea 4)?","type":"Woordbetekenis","options":["Het zuiveren van drinkwater","Het laten wegstromen van overtollig water","Het opslaan en vasthouden van water","Het meten van de waterstand in rivieren"],"correct":2,"highlight":"het herstel van natuurlijke waterbergingsgebieden","feedback":{"ok":"Goed! Waterberging = het opslaan en vasthouden van water.","nee":"Niet juist. Waterberging gaat over het opslaan en vasthouden van water."}},{"text":"Wat is de hoofdboodschap van deze tekst?","type":"Hoofdgedachte","options":["Nederland heeft nooit last van droogte gehad.","Droogte is alleen een probleem in andere landen.","Droogte is een toenemend probleem waarvoor Nederland zich structureel moet aanpassen.","Boeren moeten stoppen met irrigeren."],"correct":2,"highlight":"Nederland zich structureel moet aanpassen aan een droger klimaat","feedback":{"ok":"Prima! Structurele aanpassing aan droogte is de kernboodschap.","nee":"Niet correct. De tekst benadrukt dat Nederland zich structureel moet aanpassen aan een droger klimaat."}}]},{"topic":"Cultuur","title":"Nederlandse musea: wereldklasse in een kleine ruimte","paragraphs":["Nederland heeft meer musea per inwoner dan welk land ter wereld ook. Van het wereldberoemde Rijksmuseum in Amsterdam tot kleine streekmusea in dorpen en steden: er is voor elk wat wils. De grote steden trekken miljoenen bezoekers per jaar met topstukken van schilders als Rembrandt, Vermeer en Van Gogh.","Naast kunstmusea heeft Nederland ook wetenschappelijke en technische musea die populair zijn bij families en scholieren. Het Nemo Science Museum in Amsterdam trekt jaarlijks meer dan zeshonderdduizend bezoekers. Musea als Naturalis in Leiden en het Spoorwegmuseum in Utrecht combineren educatie met beleving.","Digitalisering biedt musea nieuwe mogelijkheden. Steeds meer musea bieden virtuele rondleidingen en online collecties aan, zodat mensen van over de hele wereld de werken kunnen bekijken zonder naar Nederland te reizen. Toch zeggen museumexperts dat de digitale ervaring nooit het echte bezoek kan vervangen.","Musea spelen ook een rol in de lokale gemeenschap. Ze organiseren tentoonstellingen over actuele thema's, bieden educatieve programma's aan voor scholen en werken samen met lokale kunstenaars. Zo zijn musea niet alleen plekken om het verleden te bewaren, maar ook om na te denken over de toekomst."],"questions":[{"text":"Wat is bijzonder aan Nederland op het gebied van musea?","type":"Detail","options":["Nederland heeft de grootste musea ter wereld.","Alle musea zijn gratis toegankelijk in Nederland.","Nederland heeft de oudste musea ter wereld.","Nederland heeft meer musea per inwoner dan welk land ook."],"correct":3,"highlight":"Nederland heeft meer musea per inwoner dan welk land ter wereld ook","feedback":{"ok":"Goed! Meer musea per inwoner dan welk land ook.","nee":"Niet juist. Alinea 1: meer musea per inwoner dan welk land ter wereld ook."}},{"text":"Hoeveel bezoekers trekt het Nemo Science Museum per jaar?","type":"Detail","options":["Meer dan een miljoen","Meer dan twee miljoen","Meer dan zeshonderdduizend","Meer dan vierhonderdduizend"],"correct":2,"highlight":"Het Nemo Science Museum in Amsterdam trekt jaarlijks meer dan zeshonderdduizend bezoekers","feedback":{"ok":"Correct! Meer dan zeshonderdduizend bezoekers per jaar.","nee":"Niet correct. Alinea 2: meer dan zeshonderdduizend bezoekers per jaar."}},{"text":"Wat zeggen museumexperts over digitale rondleidingen?","type":"Detail","options":["Digitale rondleidingen zijn beter dan een echt bezoek.","Digitale rondleidingen zijn te duur om te maken.","De digitale ervaring kan het echte bezoek nooit vervangen.","Alle musea moeten stoppen met digitale rondleidingen."],"correct":2,"highlight":"de digitale ervaring nooit het echte bezoek kan vervangen","feedback":{"ok":"Juist! Experts zeggen dat digitaal het echte bezoek niet vervangt.","nee":"Niet juist. Alinea 3: de digitale ervaring kan het echte bezoek niet vervangen."}},{"text":"Wat betekent 'digitalisering' (alinea 3)?","type":"Woordbetekenis","options":["Het afbreken van oude gebouwen","Het sluiten van musea voor renovatie","Het omzetten van informatie naar digitale vormen en het gebruik van digitale technologie","Het inhuren van meer museummedewerkers"],"correct":2,"highlight":"Digitalisering biedt musea nieuwe mogelijkheden","feedback":{"ok":"Goed! Digitalisering = het gebruik van digitale technologie en het omzetten van informatie.","nee":"Niet juist. Digitalisering verwijst naar het gebruik van digitale technologie en het omzetten van analoge informatie."}},{"text":"Hoe spelen musea een rol in de lokale gemeenschap?","type":"Inferentie","options":["Door alleen internationale kunstenaars uit te nodigen.","Door tentoonstelling en educatie te combineren en samen te werken met lokale kunstenaars.","Door hun deuren te sluiten voor scholen.","Door alleen topstukken te bewaren en niets te organiseren."],"correct":1,"highlight":"Ze organiseren tentoonstellingen over actuele thema's, bieden educatieve programma's aan voor scholen en werken samen met lokale kunstenaars","feedback":{"ok":"Prima! Tentoonstellingen, educatie en samenwerking met lokale kunstenaars.","nee":"Niet correct. Alinea 4: tentoonstellingen, educatieve programma's en samenwerking met lokale kunstenaars."}}]},{"topic":"Financiën","title":"Sparen of beleggen: wat is slimmer?","paragraphs":["Veel Nederlanders bewaren hun geld op een spaarrekening bij de bank. Dat voelt veilig: het geld staat er altijd, je kunt het makkelijk opnemen en het depositogarantiestelsel beschermt spaartegoeden tot honderdduizend euro per persoon per bank. Maar de rente op spaarrekeningen is de afgelopen jaren laag geweest, waardoor spaarders nauwelijks rendement maakten.","Beleggen is een alternatief dat de afgelopen jaren aan populariteit heeft gewonnen. Door te beleggen in aandelen, obligaties of fondsen kan je op de lange termijn meer rendement behalen dan met sparen. Steeds meer Nederlanders, ook jongeren, beginnen met beleggen via apps die het toegankelijk maken.","Maar beleggen brengt ook risico's met zich mee. De waarde van beleggingen kan dalen, soms fors. Wie zijn geld op korte termijn nodig heeft, kan een slecht moment treffen. Experts adviseren dan ook om alleen geld te beleggen dat je langere tijd kunt missen, en te beginnen met kleine bedragen.","Voor de meeste mensen is een combinatie van sparen en beleggen het verstandigst. Een buffer op de spaarrekening voor onverwachte uitgaven, en eventueel extra geld beleggen voor de lange termijn. Financieel adviseurs benadrukken dat goede spreiding en een lange tijdshorizon de risico's van beleggen sterk verminderen."],"questions":[{"text":"Hoeveel spaargeld beschermt het depositogarantiestelsel per persoon per bank?","type":"Detail","options":["Tot vijftigduizend euro","Tot tweehonderdduizend euro","Tot honderdduizend euro","Tot vijfentwintigduizend euro"],"correct":2,"highlight":"het depositogarantiestelsel beschermt spaartegoeden tot honderdduizend euro per persoon per bank","feedback":{"ok":"Goed! Het depositogarantiestelsel beschermt tot honderdduizend euro.","nee":"Niet juist. Alinea 1: bescherming tot honderdduizend euro per persoon per bank."}},{"text":"Waarom is beleggen populairder geworden?","type":"Detail","options":["Omdat spaarrekeningen niet meer bestaan.","Omdat beleggen altijd winstgevend is.","Omdat de overheid dit verplicht stelt.","Omdat men op de lange termijn meer rendement kan behalen dan met sparen."],"correct":3,"highlight":"op de lange termijn meer rendement behalen dan met sparen","feedback":{"ok":"Correct! Op de lange termijn meer rendement dan sparen.","nee":"Niet correct. Alinea 2: meer rendement op de lange termijn."}},{"text":"Wat is een risico van beleggen?","type":"Detail","options":["Je kunt het geld niet meer opnemen.","De bank kan failliet gaan.","De waarde van beleggingen kan dalen.","Je betaalt altijd meer belasting."],"correct":2,"highlight":"De waarde van beleggingen kan dalen, soms fors","feedback":{"ok":"Juist! Beleggingen kunnen in waarde dalen.","nee":"Niet juist. Alinea 3: de waarde van beleggingen kan dalen."}},{"text":"Wat betekent 'tijdshorizon' (alinea 4)?","type":"Woordbetekenis","options":["De maximale winst die je kunt maken","Het maximum bedrag dat je mag beleggen","De periode waarvoor je belegt of spaart","De kosten van een beleggingsrekening"],"correct":2,"highlight":"een lange tijdshorizon de risico's van beleggen sterk verminderen","feedback":{"ok":"Goed! Tijdshorizon = de periode waarvoor je belegt.","nee":"Niet juist. Tijdshorizon verwijst naar de periode waarvoor je belegt of spaart."}},{"text":"Wat is het advies voor de meeste mensen?","type":"Hoofdgedachte","options":["Alles beleggen voor het hoogste rendement.","Alleen sparen en nooit beleggen.","Een combinatie van sparen en beleggen.","Alle spaargeld bewaren in contant geld."],"correct":2,"highlight":"een combinatie van sparen en beleggen het verstandigst","feedback":{"ok":"Prima! Een combinatie van sparen en beleggen is het verstandigst.","nee":"Niet correct. Alinea 4: voor de meeste mensen is een combinatie het verstandigst."}}]},{"topic":"Architectuur","title":"Nederlandse architectuur: van grachtenpand tot wolkenkrabber","paragraphs":["De Nederlandse architectuur is de afgelopen eeuwen sterk veranderd. De smalle grachtenpanden in Amsterdam, met hun gevels en grote ramen, dateren uit de Gouden Eeuw van de zeventiende eeuw. Ze werden gebouwd op de smalle kavels langs de grachten, waardoor ze hoog en smal zijn. De gevels zijn vaak versierd met trapgevels, halsgevel of klokgevels.","In de twintigste eeuw moderniseerde de Nederlandse architectuur ingrijpend. Nederland werd een internationaal begrip dankzij stromingen als De Stijl, met architecten als Gerrit Rietveld. Het Rietveld Schröderhuis in Utrecht is een wereldberoemd voorbeeld van modernistische architectuur en staat op de UNESCO-werelderfgoedlijst.","Tegenwoordig staat Nederland bekend als een laboratorium voor innovatieve architectuur. Steden als Rotterdam, dat grotendeels opnieuw werd opgebouwd na de Tweede Wereldoorlog, tonen spectaculaire gebouwen zoals de Markthal en de kubuswoningen. Architectenbureaus zoals Rem Koolhaas' OMA hebben wereldwijde invloed.","Duurzaamheid speelt een steeds grotere rol in de hedendaagse Nederlandse architectuur. Nieuwe gebouwen worden ontworpen met zonnepanelen, groene daken en energie-efficiënte materialen. Er zijn ook projecten waarbij oude fabrieken of kantoren worden omgebouwd tot woningen, om zo duurzaam gebruik te maken van bestaande structuren."],"questions":[{"text":"Waarom zijn grachtenpanden in Amsterdam hoog en smal?","type":"Detail","options":["Omdat het goedkoper was om hoge gebouwen te bouwen.","Omdat brede gebouwen verboden waren.","Omdat ze gebouwd werden op smalle kavels langs de grachten.","Omdat de bouwhoogte door de overheid werd bepaald."],"correct":2,"highlight":"Ze werden gebouwd op de smalle kavels langs de grachten, waardoor ze hoog en smal zijn","feedback":{"ok":"Goed! Smalle kavels langs de grachten bepaalden de vorm.","nee":"Niet juist. Alinea 1: de smalle kavels langs de grachten."}},{"text":"Op welke lijst staat het Rietveld Schröderhuis?","type":"Detail","options":["De lijst van nationale monumenten van Utrecht.","De Forbes-lijst van duurste gebouwen.","De lijst van de duurste architecten ter wereld.","De UNESCO-werelderfgoedlijst."],"correct":3,"highlight":"staat op de UNESCO-werelderfgoedlijst","feedback":{"ok":"Correct! Het Rietveld Schröderhuis staat op de UNESCO-werelderfgoedlijst.","nee":"Niet correct. Alinea 2: het staat op de UNESCO-werelderfgoedlijst."}},{"text":"Waarvoor staat Rotterdam bekend op het gebied van architectuur?","type":"Detail","options":["Voor zijn historische grachtenpanden.","Voor zijn gemiddelde architectuur.","Voor zijn traditionele dorpskerken.","Voor spectaculaire innovatieve gebouwen zoals de Markthal."],"correct":3,"highlight":"tonen spectaculaire gebouwen zoals de Markthal en de kubuswoningen","feedback":{"ok":"Juist! Rotterdam heeft spectaculaire innovatieve gebouwen.","nee":"Niet juist. Alinea 3: Rotterdam heeft spectaculaire gebouwen zoals de Markthal."}},{"text":"Wat betekent 'energie-efficiënt' (alinea 4)?","type":"Woordbetekenis","options":["Duurder om te verwarmen","Zo weinig mogelijk energie gebruiken voor hetzelfde resultaat","Powered by solar energy","Gemakkelijk te verwarmen in de winter"],"correct":1,"highlight":"energie-efficiënte materialen","feedback":{"ok":"Goed! Energie-efficiënt = zo min mogelijk energie gebruiken voor hetzelfde resultaat.","nee":"Niet juist. Energie-efficiënt betekent zo weinig mogelijk energie gebruiken voor hetzelfde resultaat."}},{"text":"Hoe wordt duurzaamheid toegepast in nieuwe gebouwen?","type":"Inferentie","options":["Door alleen traditionele materialen te gebruiken.","Door gebouwen kleiner te maken.","Door gebruik van zonnepanelen, groene daken en hergebruik van bestaande structuren.","Door gebouwen in de natuur te plaatsen."],"correct":2,"highlight":"Nieuwe gebouwen worden ontworpen met zonnepanelen, groene daken en energie-efficiënte materialen","feedback":{"ok":"Prima! Zonnepanelen, groene daken en hergebruik van bestaande structuren.","nee":"Niet correct. Alinea 4: zonnepanelen, groene daken en hergebruik van bestaande structuren."}}]},{"topic":"Muziek","title":"Nederlandse muziek: meer dan alleen Nederlandstalig","paragraphs":["Nederland heeft een rijke muziektraditie die veel verder gaat dan alleen Nederlandstalige popmuziek. In de klassieke muziek staat het Concertgebouworkest in Amsterdam wereldwijd bekend als een van de beste orkesten ter wereld. Het Concertgebouw, gebouwd in 1888, trekt jaarlijks ruim achthonderdduizend bezoekers.","In de popmuziek heeft Nederland internationaal succes geboekt met artiesten als Tiësto, Afrojack en Martin Garrix, die de elektronische dansmuziek naar een wereldwijd publiek hebben gebracht. De stad Amsterdam geldt als een van de centra van de internationale dj-cultuur. Jaarlijks vindt het Amsterdam Dance Event plaats, een van de grootste elektronische muziekfestivals ter wereld.","Nederlandstalige muziek beleeft de laatste jaren een opmerkelijke renaissance. Artiesten als Snelle, Maan en Nielson scoren grote hits met liedjes in het Nederlands. Jongeren die vroeger liever Engelstalige muziek luisterden, omarmen nu steeds vaker muziek in hun eigen taal.","Naast popmuziek is er in Nederland ook een levendige folktraditie. Volksmuziek uit provincies als Zeeland, Friesland en Limburg heeft eigen kenmerken en instrumenten. Friese muziek kent bijvoorbeeld een sterke koortraditie, terwijl Limburgse muziek sterk beïnvloed is door de buurlanden België en Duitsland."],"questions":[{"text":"Hoeveel bezoekers trekt het Concertgebouw jaarlijks?","type":"Detail","options":["Ruim vierhonderdduizend","Ruim zeshonderdduizend","Ruim tweehonderdduizend","Ruim achthonderdduizend"],"correct":3,"highlight":"trekt jaarlijks ruim achthonderdduizend bezoekers","feedback":{"ok":"Goed! Ruim achthonderdduizend bezoekers per jaar.","nee":"Niet juist. Alinea 1: ruim achthonderdduizend bezoekers per jaar."}},{"text":"Waarvoor staat Amsterdam bekend in de muziekwereld?","type":"Detail","options":["Als centrum van klassieke muziek in Europa.","Als centrum van de internationale dj-cultuur.","Als birthplace van Nederlandstalige pop.","Als centrum van volksmuziek."],"correct":1,"highlight":"De stad Amsterdam geldt als een van de centra van de internationale dj-cultuur","feedback":{"ok":"Correct! Amsterdam is een centrum van de internationale dj-cultuur.","nee":"Niet correct. Alinea 2: Amsterdam staat bekend als centrum van de internationale dj-cultuur."}},{"text":"Wat is opmerkelijk aan de renaissance van Nederlandstalige muziek?","type":"Detail","options":["Jongeren luisteren minder muziek dan vroeger.","Nederlandstalige muziek wordt alleen in het buitenland populair.","Jongeren omarmen steeds vaker muziek in hun eigen taal.","Engelstalige muziek is verboden op radio."],"correct":2,"highlight":"Jongeren die vroeger liever Engelstalige muziek luisterden, omarmen nu steeds vaker muziek in hun eigen taal","feedback":{"ok":"Juist! Jongeren kiezen vaker voor Nederlandstalige muziek.","nee":"Niet juist. Alinea 3: jongeren omarmen nu steeds vaker muziek in hun eigen taal."}},{"text":"Wat betekent 'renaissance' (alinea 3)?","type":"Woordbetekenis","options":["Een langzame achteruitgang","Een nieuw begin of hergeboorte van iets","Een muziekgenre uit Italië","Een festival voor klassieke muziek"],"correct":1,"highlight":"beleeft de laatste jaren een opmerkelijke renaissance","feedback":{"ok":"Goed! Renaissance betekent een herleving of nieuw begin.","nee":"Niet juist. Renaissance betekent een herleving of nieuw begin van iets."}},{"text":"Wat is kenmerkend voor Limburgse muziek?","type":"Inferentie","options":["Een sterke koortraditie.","Eigen unieke instrumenten die nergens anders voorkomen.","Invloed van de buurlanden België en Duitsland.","Volledig gebaseerd op Nederlandstalige teksten."],"correct":2,"highlight":"Limburgse muziek sterk beïnvloed is door de buurlanden België en Duitsland","feedback":{"ok":"Prima! Limburgse muziek is sterk beïnvloed door België en Duitsland.","nee":"Niet correct. Alinea 4: Limburgse muziek is beïnvloed door België en Duitsland."}}]},{"topic":"Voedsel","title":"Kaas: een Nederlandse trots","paragraphs":["Nederland is een van de grootste kaasproducenten en kaasexporteurs ter wereld. Bekende Nederlandse kaassoorten zoals Gouda, Edam en Leerdammer worden wereldwijd gegeten. De kaasmarkt in Alkmaar, een van de laatste authentieke kaasmarkten in Nederland, trekt elk jaar tienduizenden toeristen.","De productie van kaas begint bij de koe. Nederland heeft een hoge veedichtheid: er leven meer dan vier miljoen koeien in het land. De melk die zij produceren, wordt verwerkt door zuivelfabrieken die verspreid over het land liggen. Het hele proces, van melken tot kaasproductie, is in Nederland sterk geautomatiseerd.","Kaas speelt een belangrijke rol in de Nederlandse eetcultuur. Nederlanders eten gemiddeld meer dan veertien kilo kaas per jaar per persoon, wat ver boven het Europees gemiddelde ligt. Kaas wordt gegeten als broodbeleg, als snack, verwerkt in warme gerechten of geserveerd op een kaasplank bij de borrel.","De kaassector staat echter voor uitdagingen. Milieucritici wijzen op de hoge uitstoot van broeikasgassen door de veeteelt. Er is ook druk om het waterverbruik en de stikstofuitstoot te verminderen. Sommige kaasmakers experimenteren met plantaardige alternatieven, maar traditionele kaasliefhebbers zijn niet snel overtuigd."],"questions":[{"text":"Hoeveel koeien leven er in Nederland?","type":"Detail","options":["Meer dan drie miljoen","Meer dan vijf miljoen","Meer dan twee miljoen","Meer dan vier miljoen"],"correct":3,"highlight":"er leven meer dan vier miljoen koeien in het land","feedback":{"ok":"Goed! Meer dan vier miljoen koeien.","nee":"Niet juist. Alinea 2: meer dan vier miljoen koeien."}},{"text":"Hoeveel kaas eten Nederlanders gemiddeld per jaar?","type":"Detail","options":["Meer dan tien kilo","Meer dan twintig kilo","Meer dan veertien kilo","Meer dan acht kilo"],"correct":2,"highlight":"Nederlanders eten gemiddeld meer dan veertien kilo kaas per jaar per persoon","feedback":{"ok":"Correct! Meer dan veertien kilo per persoon per jaar.","nee":"Niet correct. Alinea 3: meer dan veertien kilo per persoon per jaar."}},{"text":"Welke uitdaging staat de kaassector te wachten?","type":"Detail","options":["Te weinig koeien voor de productie.","Hoge uitstoot van broeikasgassen door de veeteelt.","Gebrek aan interesse van consumenten.","Te veel concurrentie uit het buitenland."],"correct":1,"highlight":"de hoge uitstoot van broeikasgassen door de veeteelt","feedback":{"ok":"Juist! Hoge uitstoot van broeikasgassen is een grote uitdaging.","nee":"Niet juist. Alinea 4: de hoge uitstoot van broeikasgassen door de veeteelt."}},{"text":"Wat betekent 'veedichtheid' (alinea 2)?","type":"Woordbetekenis","options":["Het gewicht van de koeien in een gebied","De kwaliteit van het veevoer","Het aantal dieren per oppervlakte-eenheid","De afstand tussen boerderijen"],"correct":2,"highlight":"Nederland heeft een hoge veedichtheid","feedback":{"ok":"Goed! Veedichtheid = het aantal dieren per oppervlakte-eenheid.","nee":"Niet juist. Veedichtheid verwijst naar het aantal dieren per oppervlakte-eenheid."}},{"text":"Wat is de hoofdboodschap van deze tekst?","type":"Hoofdgedachte","options":["Nederland moet stoppen met kaasproductie.","Kaas is het populairste voedsel in Europa.","Kaas is een belangrijke sector in Nederland, maar staat voor milieu-uitdagingen.","Toeristen komen alleen naar Nederland voor kaas."],"correct":2,"highlight":"De kaassector staat echter voor uitdagingen","feedback":{"ok":"Prima! Kaas is belangrijk voor Nederland maar staat voor uitdagingen.","nee":"Niet correct. De tekst beschrijft zowel het belang als de uitdagingen van de kaassector."}}]},{"topic":"Politiek","title":"De Nederlandse democratie: hoe werkt het?","paragraphs":["Nederland is een constitutionele monarchie met een parlementaire democratie. De koning of koningin heeft een ceremoniële rol, terwijl de politieke macht bij de gekozen volksvertegenwoordigers ligt. Het parlement, de Staten-Generaal, bestaat uit twee kamers: de Tweede Kamer en de Eerste Kamer.","De Tweede Kamer heeft 150 zetels en wordt direct gekozen door de Nederlandse bevolking via evenredige vertegenwoordiging. Dit betekent dat partijen zetels krijgen in verhouding tot het percentage stemmen dat ze behalen. Hierdoor zijn er in Nederland altijd meerdere partijen in de Tweede Kamer, soms wel vijftien of meer.","Omdat geen enkele partij ooit de meerderheid haalt, moeten partijen samenwerken om een coalitie te vormen. Dit proces, de formatie, kan weken of zelfs maanden duren. Een formateur of informateur begeleidt de onderhandelingen. Uiteindelijk presenteert de coalitie een regeerakkoord met de plannen voor de komende jaren.","De Eerste Kamer, ook wel de Senaat of de 'chambre de réflexion' genoemd, bestaat uit 75 leden die indirect worden gekozen door de provinciale staten. De Eerste Kamer kan wetten goedkeuren of verwerpen, maar kan ze niet zelf wijzigen. Dit systeem zorgt voor een extra controle op de wetgeving."],"questions":[{"text":"Hoeveel zetels heeft de Tweede Kamer?","type":"Detail","options":["125 zetels","100 zetels","175 zetels","150 zetels"],"correct":3,"highlight":"De Tweede Kamer heeft 150 zetels","feedback":{"ok":"Goed! De Tweede Kamer heeft 150 zetels.","nee":"Niet juist. Alinea 2: de Tweede Kamer heeft 150 zetels."}},{"text":"Wat betekent evenredige vertegenwoordiging?","type":"Woordbetekenis","options":["Alle partijen krijgen evenveel zetels.","Alleen grote partijen krijgen zetels.","Partijen krijgen zetels in verhouding tot hun stempercentage.","De koning verdeelt de zetels eerlijk."],"correct":2,"highlight":"partijen zetels krijgen in verhouding tot het percentage stemmen dat ze behalen","feedback":{"ok":"Correct! Zetels worden verdeeld naar stempercentage.","nee":"Niet correct. Alinea 2: zetels worden verdeeld in verhouding tot het stempercentage."}},{"text":"Waarom duurt de formatie soms lang?","type":"Inferentie","options":["Omdat de koning het regeerakkoord moet goedkeuren.","Omdat partijen moeten samenwerken om een meerderheidscoalitie te vormen.","Omdat verkiezingen opnieuw gehouden moeten worden.","Omdat de Eerste Kamer het formatieteam moet aanwijzen."],"correct":1,"highlight":"moeten partijen samenwerken om een coalitie te vormen. Dit proces, de formatie, kan weken of zelfs maanden duren","feedback":{"ok":"Juist! Samenwerken voor een coalitie kost tijd.","nee":"Niet juist. Alinea 3: partijen moeten onderhandelen over een coalitie."}},{"text":"Wat kan de Eerste Kamer NIET doen?","type":"Detail","options":["Wetten goedkeuren.","Wetten verwerpen.","Wetten zelf wijzigen.","Wetsvoorstellen beoordelen."],"correct":2,"highlight":"De Eerste Kamer kan wetten goedkeuren of verwerpen, maar kan ze niet zelf wijzigen","feedback":{"ok":"Goed! De Eerste Kamer kan wetten niet zelf wijzigen.","nee":"Niet juist. Alinea 4: de Eerste Kamer kan wetten niet zelf wijzigen."}},{"text":"Welke rol heeft de koning in de Nederlandse democratie?","type":"Detail","options":["De koning beslist over nieuwe wetten.","De koning kiest de ministers.","De koning heeft een ceremoniële rol.","De koning leidt de formatie."],"correct":2,"highlight":"De koning of koningin heeft een ceremoniële rol","feedback":{"ok":"Prima! De rol van de koning is ceremonieel.","nee":"Niet correct. Alinea 1: de koning heeft een ceremoniële rol."}}]},{"topic":"Technologie","title":"Kunstmatige intelligentie in het dagelijks leven","paragraphs":["Kunstmatige intelligentie, ook wel AI genoemd, is niet meer weg te denken uit het dagelijks leven. Van de aanbevelingen op streamingdiensten tot de navigatieapp op je telefoon: AI werkt overal op de achtergrond. Veel mensen gebruiken AI zonder het te beseffen, omdat de technologie naadloos in bestaande producten is geïntegreerd.","In de gezondheidszorg biedt AI grote kansen. Computerprogramma's kunnen medische scans analyseren en afwijkingen opsporen die voor het menselijk oog moeilijk zichtbaar zijn. Ook bij het voorspellen van ziektes en het personaliseren van behandelingen speelt AI een steeds grotere rol. Artsen gebruiken AI als hulpmiddel, maar de uiteindelijke beslissing blijft bij de dokter.","Op de arbeidsmarkt roept AI gemengde gevoelens op. Sommige banen verdwijnen doordat machines taken overnemen die vroeger mensen deden. Maar AI creëert ook nieuwe banen: er is grote vraag naar mensen die AI-systemen kunnen ontwikkelen, beheren en controleren. Experts verwachten dat de komende decennia grote verschuivingen op de arbeidsmarkt zullen plaatsvinden.","Er zijn ook zorgen over de risico's van AI. Algoritmes kunnen vooroordelen bevatten als ze getraind worden op ongelijke data. Deepfakes — nep video's of foto's gemaakt met AI — kunnen worden gebruikt om mensen te misleiden. Overheden werken aan regelgeving om de ontwikkeling van AI in goede banen te leiden."],"questions":[{"text":"Hoe gebruikt AI op aanbevelingen van streamingdiensten?","type":"Inferentie","options":["AI schrijft de films en series zelf.","AI bepaalt de abonnementsprijs.","AI werkt op de achtergrond om aanbevelingen te doen.","AI vertaalt de films naar het Nederlands."],"correct":2,"highlight":"AI werkt overal op de achtergrond","feedback":{"ok":"Goed! AI werkt op de achtergrond bij aanbevelingen.","nee":"Niet juist. Alinea 1: AI werkt op de achtergrond bij aanbevelingen."}},{"text":"Hoe wordt AI gebruikt in de gezondheidszorg?","type":"Detail","options":["AI vervangt artsen volledig.","AI schrijft recepten uit zonder tussenkomst van artsen.","AI analyseert medische scans en helpt ziektes te voorspellen.","AI bepaalt welke patiënten behandeld worden."],"correct":2,"highlight":"Computerprogramma's kunnen medische scans analyseren en afwijkingen opsporen","feedback":{"ok":"Correct! AI analyseert scans en helpt bij het voorspellen van ziektes.","nee":"Niet correct. Alinea 2: AI analyseert scans en helpt ziektes voorspellen."}},{"text":"Wat voor nieuwe banen creëert AI?","type":"Detail","options":["Banen in de traditionele industrie.","Banen voor mensen die AI-systemen ontwikkelen en beheren.","Banen als verpleegkundige en leraar.","Banen in de landbouw."],"correct":1,"highlight":"er is grote vraag naar mensen die AI-systemen kunnen ontwikkelen, beheren en controleren","feedback":{"ok":"Juist! Er is vraag naar mensen die AI ontwikkelen en beheren.","nee":"Niet juist. Alinea 3: er is vraag naar mensen die AI-systemen ontwikkelen en beheren."}},{"text":"Wat zijn deepfakes?","type":"Woordbetekenis","options":["Nep accounts op sociale media","Foute informatie op internet","Nep video's of foto's gemaakt met AI","Virussen die computersystemen aanvallen"],"correct":2,"highlight":"Deepfakes — nep video's of foto's gemaakt met AI","feedback":{"ok":"Goed! Deepfakes zijn nep video's of foto's gemaakt met AI.","nee":"Niet juist. Alinea 4: deepfakes zijn nep video's of foto's gemaakt met AI."}},{"text":"Wat is de hoofdboodschap van deze tekst?","type":"Hoofdgedachte","options":["AI is gevaarlijk en moet verboden worden.","AI heeft alleen voordelen voor de samenleving.","AI biedt kansen maar brengt ook risico's met zich mee.","AI vervangt alle menselijke banen."],"correct":2,"highlight":"Er zijn ook zorgen over de risico's van AI","feedback":{"ok":"Prima! AI biedt kansen maar brengt ook risico's met zich mee.","nee":"Niet correct. De tekst bespreekt zowel kansen als risico's van AI."}}]},{"topic":"Geografie","title":"De Waddeneilanden: parels van de Noordzee","paragraphs":["De Waddeneilanden zijn een rij van vijf bewoonde eilanden voor de kust van Noord-Holland en Friesland: Texel, Vlieland, Terschelling, Ameland en Schiermonnikoog. Ze maken deel uit van het Waddengebied, dat in 2009 op de UNESCO-werelderfgoedlijst werd geplaatst vanwege zijn unieke natuur.","Het Wad, de ondiepe zee tussen de eilanden en de vaste wal, droogt tweemaal per dag gedeeltelijk droog bij laagwater. Dit fenomeen, het getij, maakt het mogelijk om te wadlopen: te voet door het slik en zand van het wad trekken bij laagwater. Wadlopen is een populaire activiteit die alleen onder begeleiding van een gids mag plaatsvinden.","De eilanden zijn een paradijs voor vogels en zeehonden. Miljoenen vogels gebruiken het Waddengebied als rustplaats tijdens hun trek van en naar noordelijkere broedgebieden. Zeehonden leggen op de zandplaten en zijn een geliefde attractie voor toeristen. Het gebied is dan ook aangewezen als beschermd natuurgebied.","Toerisme is voor de eilanden een belangrijke bron van inkomsten, maar ook een uitdaging. In de zomer stromen de eilanden vol met bezoekers, wat druk legt op de natuur en de sfeer voor bewoners. Sommige eilanden beperken het aantal dagtoeristen om de leefbaarheid en de natuur te beschermen."],"questions":[{"text":"Hoeveel bewoonde Waddeneilanden heeft Nederland?","type":"Detail","options":["Vier","Zeven","Drie","Vijf"],"correct":3,"highlight":"een rij van vijf bewoonde eilanden","feedback":{"ok":"Goed! Nederland heeft vijf bewoonde Waddeneilanden.","nee":"Niet juist. Alinea 1: er zijn vijf bewoonde Waddeneilanden."}},{"text":"Wanneer werd het Waddengebied op de UNESCO-lijst geplaatst?","type":"Detail","options":["In 2005","In 2015","In 2000","In 2009"],"correct":3,"highlight":"in 2009 op de UNESCO-werelderfgoedlijst werd geplaatst","feedback":{"ok":"Correct! In 2009 werd het op de UNESCO-lijst geplaatst.","nee":"Niet correct. Alinea 1: in 2009."}},{"text":"Wanneer is wadlopen mogelijk?","type":"Detail","options":["Alleen bij vloed.","Het hele jaar door, ongeacht het getij.","Alleen bij zonsondergang.","Bij laagwater, als het wad gedeeltelijk droogvalt."],"correct":3,"highlight":"te voet door het slik en zand van het wad trekken bij laagwater","feedback":{"ok":"Juist! Wadlopen is mogelijk bij laagwater.","nee":"Niet juist. Alinea 2: wadlopen is mogelijk bij laagwater."}},{"text":"Wat betekent 'broedgebied' (alinea 3)?","type":"Woordbetekenis","options":["Een gebied waar dieren overwinteren","Een gebied waar dieren voedsel zoeken","Een gebied waar vogels of dieren jongen grootbrengen","Een beschermd bosgebied"],"correct":2,"highlight":"broedgebieden","feedback":{"ok":"Goed! Een broedgebied is waar vogels of dieren jongen grootbrengen.","nee":"Niet juist. Een broedgebied is een gebied waar dieren zich voortplanten en jongen grootbrengen."}},{"text":"Waarom beperken sommige eilanden het aantal dagtoeristen?","type":"Inferentie","options":["Omdat er te weinig hotels zijn.","Omdat dagtouristen te weinig geld uitgeven.","Om de leefbaarheid en de natuur te beschermen.","Omdat de veerboten te weinig capaciteit hebben."],"correct":2,"highlight":"Sommige eilanden beperken het aantal dagtoeristen om de leefbaarheid en de natuur te beschermen","feedback":{"ok":"Prima! Om de leefbaarheid en natuur te beschermen.","nee":"Niet correct. Alinea 4: om de leefbaarheid en de natuur te beschermen."}}]},{"topic":"Ondernemen","title":"Startups in Nederland: een bloeiend ecosysteem","paragraphs":["Nederland heeft de afgelopen decennia een sterk ecosysteem voor startups opgebouwd. Amsterdam staat in Europese ranglijsten consequent in de top vijf van beste steden voor startende ondernemers. De aanwezigheid van grote internationale bedrijven, goede infrastructuur en een hoog opgeleid Engelstalig personeelsbestand trekken jonge bedrijven aan.","De Nederlandse overheid stimuleert ondernemerschap actief. Er zijn fiscale voordelen voor investeerders in startups en er bestaan subsidies voor innovatieve bedrijven. De WBSO, een fiscale regeling voor onderzoek en ontwikkeling, helpt technologiebedrijven om hun kosten te drukken. Incubators en accelerators begeleiden startende ondernemers met advies en netwerk.","Bekende Nederlandse successen uit de startupwereld zijn onder meer Booking.com, Adyen en Coolblue. Deze bedrijven begonnen klein maar groeiden uit tot internationale spelers. Booking.com, oorspronkelijk opgericht in Amsterdam, is inmiddels een van de grootste reisplatforms ter wereld.","Toch is ondernemen niet zonder risico. Veel startups mislukken binnen de eerste vijf jaar. Gebrek aan financiering, te sterke concurrentie of een product dat de markt niet nodig blijkt te hebben, zijn veelgenoemde oorzaken. Succesvolle ondernemers benadrukken het belang van flexibiliteit, het leren van fouten en het opbouwen van een sterk netwerk."],"questions":[{"text":"Waar staat Amsterdam consequent in op Europese ranglijsten?","type":"Detail","options":["In de top tien van duurzaamste steden.","In de top vijf van beste steden voor startende ondernemers.","In de top drie van goedkoopste steden voor bedrijven.","In de top vijf van steden met de meeste grote bedrijven."],"correct":1,"highlight":"Amsterdam staat in Europese ranglijsten consequent in de top vijf van beste steden voor startende ondernemers","feedback":{"ok":"Goed! Amsterdam staat in de top vijf van beste steden voor startende ondernemers.","nee":"Niet juist. Alinea 1: Amsterdam staat consequent in de top vijf."}},{"text":"Waarvoor dient de WBSO-regeling?","type":"Detail","options":["Om startups te verbinden met investeerders.","Om werknemers bij te scholen.","Om technologiebedrijven te helpen hun kosten te drukken.","Om de export van Nederlandse producten te stimuleren."],"correct":2,"highlight":"De WBSO, een fiscale regeling voor onderzoek en ontwikkeling, helpt technologiebedrijven om hun kosten te drukken","feedback":{"ok":"Correct! De WBSO helpt technologiebedrijven hun kosten te drukken.","nee":"Niet correct. Alinea 2: de WBSO helpt technologiebedrijven kosten te drukken."}},{"text":"Waar is Booking.com oorspronkelijk opgericht?","type":"Detail","options":["In Rotterdam","In Utrecht","In Amsterdam","In Den Haag"],"correct":2,"highlight":"Booking.com, oorspronkelijk opgericht in Amsterdam","feedback":{"ok":"Juist! Booking.com is opgericht in Amsterdam.","nee":"Niet juist. Alinea 3: Booking.com is oorspronkelijk opgericht in Amsterdam."}},{"text":"Wat betekent 'accelerator' (alinea 2)?","type":"Woordbetekenis","options":["Een overheidsorganisatie die belastingen controleert","Een programma dat startende bedrijven begeleidt met advies en netwerk","Een investeringsfonds voor grote bedrijven","Een softwareprogramma voor financiële administratie"],"correct":1,"highlight":"Incubators en accelerators begeleiden startende ondernemers met advies en netwerk","feedback":{"ok":"Goed! Een accelerator begeleidt startende bedrijven met advies en netwerk.","nee":"Niet juist. Een accelerator is een programma dat startende bedrijven begeleidt."}},{"text":"Wat benadrukken succesvolle ondernemers als sleutel tot succes?","type":"Detail","options":["Zo snel mogelijk veel geld ophalen bij investeerders.","Flexibiliteit, leren van fouten en een sterk netwerk.","Altijd vasthouden aan het oorspronkelijke plan.","Zo weinig mogelijk risico's nemen."],"correct":1,"highlight":"Succesvolle ondernemers benadrukken het belang van flexibiliteit, het leren van fouten en het opbouwen van een sterk netwerk","feedback":{"ok":"Prima! Flexibiliteit, leren van fouten en netwerk opbouwen.","nee":"Niet correct. Alinea 4: flexibiliteit, leren van fouten en een sterk netwerk."}}]},{"topic":"Gezondheid","title":"Mentale gezondheid: een groeiend aandachtspunt","paragraphs":["Mentale gezondheid staat in Nederland steeds meer op de agenda. Steeds meer mensen zoeken hulp voor psychische klachten zoals angst, depressie of burn-out. De wachttijden bij psychologen en psychiaters zijn de afgelopen jaren sterk opgelopen, wat een teken is van de groeiende vraag naar geestelijke gezondheidszorg.","Burn-out is een van de meest voorkomende klachten. Het gaat om een staat van uitputting die ontstaat door langdurige stress, vaak door werkdruk. Klachten zijn onder meer extreme vermoeidheid, concentratieproblemen en een gevoel van machteloosheid. Herstel van een burn-out duurt gemiddeld meerdere maanden.","Werkgevers beginnen het belang van mentale gezondheid te erkennen. Steeds meer bedrijven bieden hun werknemers toegang tot coaching, online therapie of een bedrijfsmaatschappelijk werker. Preventie — het voorkomen van klachten voordat ze ernstig worden — staat hoog op de agenda van HR-afdelingen.","Jongeren zijn een bijzondere risicogroep. Onderzoek toont aan dat jongeren in Nederland meer stress ervaren dan vorige generaties. Sociale media, prestatiedruk op school en onzekerheid over de toekomst zijn genoemde factoren. Scholen en gemeenten werken aan programma's om de weerbaarheid van jongeren te versterken."],"questions":[{"text":"Wat is een teken van de groeiende vraag naar geestelijke gezondheidszorg?","type":"Detail","options":["Meer psychologen worden opgeleid.","Er zijn meer ziekenhuizen gebouwd.","De wachttijden bij psychologen zijn sterk opgelopen.","Mensen praten openlijker over mentale gezondheid."],"correct":2,"highlight":"De wachttijden bij psychologen en psychiaters zijn de afgelopen jaren sterk opgelopen","feedback":{"ok":"Goed! Oplopende wachttijden zijn een teken van de groeiende vraag.","nee":"Niet juist. Alinea 1: de wachttijden zijn sterk opgelopen."}},{"text":"Wat is een burn-out?","type":"Woordbetekenis","options":["Een tijdelijke verkoudheid door stress","Een staat van uitputting door langdurige stress","Een psychische aandoening die erfelijk is","Een korte periode van vermoeidheid na sport"],"correct":1,"highlight":"een staat van uitputting die ontstaat door langdurige stress","feedback":{"ok":"Correct! Burn-out is een staat van uitputting door langdurige stress.","nee":"Niet correct. Alinea 2: burn-out is een staat van uitputting door langdurige stress."}},{"text":"Hoe reageren werkgevers op de mentale gezondheidscrisis?","type":"Detail","options":["Ze verminderen de werkdruk voor alle werknemers.","Ze ontslaan werknemers met psychische klachten.","Ze bieden toegang tot coaching, online therapie of bedrijfsmaatschappelijk werk.","Ze sturen werknemers vaker op vakantie."],"correct":2,"highlight":"Steeds meer bedrijven bieden hun werknemers toegang tot coaching, online therapie of een bedrijfsmaatschappelijk werker","feedback":{"ok":"Juist! Coaching, online therapie en bedrijfsmaatschappelijk werk.","nee":"Niet juist. Alinea 3: coaching, online therapie en bedrijfsmaatschappelijk werk."}},{"text":"Welke factoren zorgen voor stress bij jongeren?","type":"Detail","options":["Gebrek aan sport en beweging.","Te weinig slaap door laat uitgaan.","Sociale media, prestatiedruk en onzekerheid over de toekomst.","Gebrek aan vriendschappen."],"correct":2,"highlight":"Sociale media, prestatiedruk op school en onzekerheid over de toekomst zijn genoemde factoren","feedback":{"ok":"Goed! Sociale media, prestatiedruk en toekomstangst.","nee":"Niet juist. Alinea 4: sociale media, prestatiedruk en onzekerheid over de toekomst."}},{"text":"Wat is het doel van preventie in de context van mentale gezondheid?","type":"Inferentie","options":["Zo snel mogelijk medicijnen voorschrijven.","Klachten behandelen nadat ze ernstig zijn geworden.","Mensen ontmoedigen om hulp te vragen.","Klachten voorkomen voordat ze ernstig worden."],"correct":3,"highlight":"Preventie — het voorkomen van klachten voordat ze ernstig worden","feedback":{"ok":"Prima! Preventie = voorkomen dat klachten ernstig worden.","nee":"Niet correct. Alinea 3: preventie is het voorkomen van klachten voordat ze ernstig worden."}}]},{"topic":"Sport","title":"Schaatsen in Nederland: een nationale passie","paragraphs":["Schaatsen is in Nederland meer dan een sport — het is een cultureel fenomeen. Op de schaatsbaan, maar ook op bevroren sloten, meren en kanalen, scheren Nederlanders over het ijs zodra de temperatuur lang genoeg laag genoeg is. De Elfstedentocht, een tocht van bijna tweehonderd kilometer langs elf Friese steden, is het hoogtepunt van de schaatscultuur.","De laatste Elfstedentocht werd gereden in 1997. Sindsdien is het in Nederland niet meer koud genoeg geweest voor de tocht. Door de klimaatverandering worden strenge winters steeds zeldzamer. Toch blijft de verwachting voor een nieuwe Elfstedentocht elk winter opleven als de temperaturen dalen.","Op de kunstijsbaan laat Nederland ook internationaal van zich horen. Nederlandse schaatsers domineren al decennialang het internationale schaatsen. Op de Olympische Spelen behalen Nederlanders regelmatig medailles op het langebaanschaatsen. Schaatssteden zoals Heerenveen en Thialf zijn bekende namen in de wereld van de topsport.","Schaatsen is niet alleen voor topsporters. Miljoenen Nederlanders schaatsen recreatief. IJsbanen zijn in de wintermaanden populaire uitjes voor families en schoolklassen. Er zijn ook speciale schaatsroutes door het landschap, die worden bijgehouden door vrijwilligers zodra het ijs dik genoeg is."],"questions":[{"text":"Hoe lang is de Elfstedentocht?","type":"Detail","options":["Bijna honderd kilometer","Bijna driehonderd kilometer","Bijna vijftig kilometer","Bijna tweehonderd kilometer"],"correct":3,"highlight":"een tocht van bijna tweehonderd kilometer langs elf Friese steden","feedback":{"ok":"Goed! De Elfstedentocht is bijna tweehonderd kilometer.","nee":"Niet juist. Alinea 1: bijna tweehonderd kilometer."}},{"text":"Wanneer werd de laatste Elfstedentocht gereden?","type":"Detail","options":["In 2002","In 1985","In 1997","In 1990"],"correct":2,"highlight":"De laatste Elfstedentocht werd gereden in 1997","feedback":{"ok":"Correct! De laatste Elfstedentocht was in 1997.","nee":"Niet correct. Alinea 2: de laatste Elfstedentocht werd gereden in 1997."}},{"text":"Waarom is de Elfstedentocht de afgelopen decennia niet gereden?","type":"Inferentie","options":["Er zijn te weinig deelnemers.","De route is te gevaarlijk geworden.","Door klimaatverandering worden strenge winters steeds zeldzamer.","De organisatie is gestopt."],"correct":2,"highlight":"Door de klimaatverandering worden strenge winters steeds zeldzamer","feedback":{"ok":"Juist! Klimaatverandering maakt strenge winters zeldzamer.","nee":"Niet juist. Alinea 2: klimaatverandering maakt strenge winters zeldzamer."}},{"text":"Wat betekent 'recreatief' (alinea 4)?","type":"Woordbetekenis","options":["Voor competitie en prijzen","Voor geld en inkomen","Voor plezier en ontspanning, niet als topsport","Als onderdeel van je werk"],"correct":2,"highlight":"Miljoenen Nederlanders schaatsen recreatief","feedback":{"ok":"Goed! Recreatief = voor plezier en ontspanning.","nee":"Niet juist. Recreatief betekent voor plezier en ontspanning, niet als topsport."}},{"text":"Wat maakt schaatsen in Nederland bijzonder?","type":"Hoofdgedachte","options":["Het is de enige sport waarbij Nederlanders medailles winnen.","Het is alleen mogelijk in professionele ijshallen.","Het is een cultureel fenomeen dat veel verder gaat dan topsport.","Het is recent populair geworden door de media."],"correct":2,"highlight":"Schaatsen is in Nederland meer dan een sport — het is een cultureel fenomeen","feedback":{"ok":"Prima! Schaatsen is een cultureel fenomeen dat meer is dan topsport.","nee":"Niet correct. Alinea 1: schaatsen is een cultureel fenomeen dat verder gaat dan topsport."}}]},{"topic":"Immigratie","title":"Nieuwkomers in Nederland: inburgering en integratie","paragraphs":["Elk jaar komen er tienduizenden mensen naar Nederland om er te wonen en te werken. Ze komen uit allerlei landen: uit andere EU-landen voor werk, uit vluchtelingenlanden voor veiligheid, of als gezinsmigranten die zich bij familieleden voegen. Nederland heeft al eeuwenlang een traditie van opvang van vluchtelingen en arbeidsmigranten.","Nieuwkomers die van buiten de EU komen en langer dan vijf jaar in Nederland willen blijven, zijn verplicht in te burgeren. Inburgering betekent het leren van de Nederlandse taal en kennis opdoen over de Nederlandse samenleving. Hiervoor moeten ze een inburgeringsexamen afleggen dat bestaat uit meerdere onderdelen, waaronder taal en maatschappelijke oriëntatie.","Integratie gaat verder dan inburgeren. Het gaat om het vinden van werk, het opbouwen van sociale contacten en het deelnemen aan de samenleving. Onderzoek wijst uit dat integratie het best verloopt als nieuwkomers snel toegang krijgen tot de arbeidsmarkt en taalonderwijs volgen. Sociale isolatie is een groot risico voor mensen die thuis blijven.","Het integratiedebat in Nederland is politiek gevoelig. Sommige partijen pleiten voor een strenger migratiebeleid, anderen benadrukken het belang van diversiteit voor de economie en de samenleving. Wetenschappers wijzen erop dat migranten economisch een positieve bijdrage leveren, maar dat de snelheid van integratie sterk afhangt van individuele omstandigheden en overheidsbeleid."],"questions":[{"text":"Wie zijn verplicht in te burgeren in Nederland?","type":"Detail","options":["Alle mensen die naar Nederland komen.","Alle EU-burgers die in Nederland werken.","Mensen van buiten de EU die langer dan vijf jaar willen blijven.","Alleen vluchtelingen."],"correct":2,"highlight":"Nieuwkomers die van buiten de EU komen en langer dan vijf jaar in Nederland willen blijven, zijn verplicht in te burgeren","feedback":{"ok":"Goed! Mensen van buiten de EU die langer dan vijf jaar willen blijven.","nee":"Niet juist. Alinea 2: mensen van buiten de EU die langer dan vijf jaar willen blijven."}},{"text":"Wat houdt inburgering in?","type":"Detail","options":["Alleen het vinden van werk.","Het leren van de taal en kennis opdoen over de Nederlandse samenleving.","Het aanvragen van een paspoort.","Het volgen van beroepsopleidingen."],"correct":1,"highlight":"het leren van de Nederlandse taal en kennis opdoen over de Nederlandse samenleving","feedback":{"ok":"Correct! Taal leren en kennis opdoen over de samenleving.","nee":"Niet correct. Alinea 2: taal leren en kennis opdoen over de Nederlandse samenleving."}},{"text":"Wanneer verloopt integratie het best?","type":"Inferentie","options":["Als nieuwkomers in eigen wijken wonen.","Als nieuwkomers snel toegang krijgen tot de arbeidsmarkt en taalonderwijs volgen.","Als nieuwkomers een jaar thuisblijven.","Als nieuwkomers meteen staatsexamen doen."],"correct":1,"highlight":"integratie het best verloopt als nieuwkomers snel toegang krijgen tot de arbeidsmarkt en taalonderwijs volgen","feedback":{"ok":"Juist! Snel toegang tot werk en taalonderwijs helpt integratie.","nee":"Niet juist. Alinea 3: integratie verloopt het best met snel toegang tot werk en taalonderwijs."}},{"text":"Wat betekent 'sociale isolatie' (alinea 3)?","type":"Woordbetekenis","options":["Te veel contacten hebben in de samenleving","Buiten de samenleving staan en weinig sociale contacten hebben","Een psychische aandoening veroorzaakt door stress","Het bewust kiezen voor een rustig leven"],"correct":1,"highlight":"Sociale isolatie is een groot risico voor mensen die thuis blijven","feedback":{"ok":"Goed! Sociale isolatie = buiten de samenleving staan met weinig contacten.","nee":"Niet juist. Sociale isolatie betekent buiten de samenleving staan en weinig sociale contacten hebben."}},{"text":"Wat concluderen wetenschappers over migranten?","type":"Detail","options":["Migranten kosten de samenleving alleen geld.","Migranten passen zich nooit aan aan de Nederlandse samenleving.","Migranten leveren economisch een positieve bijdrage.","Migranten willen niet integreren."],"correct":2,"highlight":"migranten economisch een positieve bijdrage leveren","feedback":{"ok":"Prima! Migranten leveren economisch een positieve bijdrage.","nee":"Niet correct. Alinea 4: migranten leveren economisch een positieve bijdrage."}}]},{"topic":"Natuur","title":"Bloembollenvelden: kleur in het polderlandschap","paragraphs":["In het voorjaar kleurt een groot deel van het Nederlandse landschap in felle tinten rood, geel, roze en paars. De bloembollenvelden van tulpen, narcissen en hyacinten zijn een van de meest herkenbare beelden van Nederland. De Bollenstreek, een gebied tussen Leiden en Haarlem, is het hart van de bollenteelt.","Nederland is de grootste exporteur van bloembollen ter wereld. Jaarlijks exporteert Nederland voor miljarden euro's aan bloembollen en snijbloemen naar meer dan honderd landen. De veiling in Aalsmeer, FloraHolland, is de grootste bloemenveilig ter wereld en verhandelt dagelijks miljoenen bloemen.","De bollenteelt heeft grote gevolgen voor het landschap, maar ook voor het milieu. Het gebruik van pesticiden en kunstmest heeft de biodiversiteit in de Bollenstreek aangetast. Grondwater raakt verontreinigd en insectenpopulaties nemen af. Steeds meer telers experimenteren met biologische teeltmethoden om deze schade te beperken.","Toeristen komen van heinde en ver om de bloembollenvelden te bewonderen. Keukenhof, een groot bloemenparkgoed in Lisse, ontvangt jaarlijks meer dan een miljoen bezoekers uit de hele wereld. Het park is slechts enkele weken per jaar open, maar trekt in die korte periode enorme drukte."],"questions":[{"text":"Waar ligt de Bollenstreek?","type":"Detail","options":["Tussen Amsterdam en Utrecht","Tussen Rotterdam en Den Haag","Tussen Leiden en Haarlem","Tussen Haarlem en Amsterdam"],"correct":2,"highlight":"De Bollenstreek, een gebied tussen Leiden en Haarlem","feedback":{"ok":"Goed! De Bollenstreek ligt tussen Leiden en Haarlem.","nee":"Niet juist. Alinea 1: tussen Leiden en Haarlem."}},{"text":"Hoeveel landen importeren Nederlandse bloembollen?","type":"Detail","options":["Meer dan vijftig landen","Meer dan tweehonderd landen","Meer dan honderd landen","Meer dan zeventig landen"],"correct":2,"highlight":"naar meer dan honderd landen","feedback":{"ok":"Correct! Meer dan honderd landen importeren Nederlandse bloembollen.","nee":"Niet correct. Alinea 2: naar meer dan honderd landen."}},{"text":"Wat is een negatief milieugevolg van de bollenteelt?","type":"Detail","options":["Overproductie van zuurstof door de bloemen.","Verontreiniging van grondwater en afname van insectenpopulaties.","Te veel bijen door de overvloed aan bloemen.","Verlies van landbouwgrond door de bollenteelt."],"correct":1,"highlight":"Grondwater raakt verontreinigd en insectenpopulaties nemen af","feedback":{"ok":"Juist! Grondwaterverontreiniging en afname van insectenpopulaties.","nee":"Niet juist. Alinea 3: grondwater raakt verontreinigd en insectenpopulaties nemen af."}},{"text":"Wat betekent 'verontreinigd' (alinea 3)?","type":"Woordbetekenis","options":["Opgedroogd en onbruikbaar","Vervuild met schadelijke stoffen","Overvol met water","Verwarmd door de zon"],"correct":1,"highlight":"Grondwater raakt verontreinigd","feedback":{"ok":"Goed! Verontreinigd = vervuild met schadelijke stoffen.","nee":"Niet juist. Verontreinigd betekent vervuild met schadelijke stoffen."}},{"text":"Hoe lang is Keukenhof per jaar open?","type":"Inferentie","options":["Het hele jaar","Een half jaar","Slechts enkele weken","Vier maanden"],"correct":2,"highlight":"Het park is slechts enkele weken per jaar open","feedback":{"ok":"Prima! Keukenhof is slechts enkele weken per jaar open.","nee":"Niet correct. Alinea 4: het park is slechts enkele weken per jaar open."}}]},{"topic":"Taal","title":"Dialect of standaardtaal: de strijd om de Nederlandse taal","paragraphs":["Nederland kent een rijke dialecttraditie. Van het Gronings in het noorden tot het Limburgs in het zuiden: elke regio heeft zijn eigen taalvarianten met unieke klanken, woorden en grammatica. Sommige dialecten, zoals het Zeeuws en het Twents, zijn zo anders dat sprekers van de standaardtaal ze amper begrijpen.","Het gebruik van dialect is de afgelopen eeuwen sterk afgenomen. Door de opkomst van nationale media, onderwijs in standaardnederlands en de toegenomen mobiliteit van mensen, spreken steeds minder Nederlanders nog dialect. Jongeren gebruiken dialect minder dan ouderen, en in steden verdwijnt het sneller dan op het platteland.","Toch is er ook hernieuwde interesse in dialect. Streektalen zoals het Fries, het Limburgs en het Nedersaksisch zijn officieel erkend als regionale talen in Nederland. Fries heeft zelfs een co-officiële status in de provincie Friesland: overheidsdocumenten worden er in zowel Nederlands als Fries gepubliceerd.","Linguïsten waarschuwen dat veel dialecten op de rand van uitsterven staan. Als de laatste sprekers overlijden zonder dat hun taal is gedocumenteerd, gaat een stuk cultureel erfgoed verloren. Er zijn projecten om dialecten op te nemen en vast te leggen voor toekomstige generaties, zodat het talig erfgoed bewaard blijft."],"questions":[{"text":"Welk dialect is zo anders dat standaardtaalsprekers het amper begrijpen?","type":"Detail","options":["Het Amsterdams en het Rotterdams","Het Haags en het Utrechts","Het Zeeuws en het Twents","Het Gronings en het Limburgs"],"correct":2,"highlight":"Sommige dialecten, zoals het Zeeuws en het Twents, zijn zo anders dat sprekers van de standaardtaal ze amper begrijpen","feedback":{"ok":"Goed! Het Zeeuws en het Twents zijn moeilijk begrijpbaar.","nee":"Niet juist. Alinea 1: het Zeeuws en het Twents zijn zo anders dat standaardtaalsprekers ze amper begrijpen."}},{"text":"Waarom neemt het gebruik van dialect af?","type":"Detail","options":["Omdat dialecten verboden zijn op scholen.","Omdat jongeren dialecten lelijker vinden.","Door nationale media, onderwijs en toegenomen mobiliteit.","Omdat standaardnederlands makkelijker te leren is."],"correct":2,"highlight":"door de opkomst van nationale media, onderwijs in standaardnederlands en de toegenomen mobiliteit van mensen","feedback":{"ok":"Correct! Nationale media, onderwijs en mobiliteit verklaren de afname.","nee":"Niet correct. Alinea 2: nationale media, onderwijs en toegenomen mobiliteit."}},{"text":"Welke bijzondere status heeft het Fries in Friesland?","type":"Detail","options":["Het is de enige officiële taal van Friesland.","Het is verboden in officiële communicatie.","Het heeft een co-officiële status naast het Nederlands.","Het wordt alleen op scholen onderwezen."],"correct":2,"highlight":"Fries heeft zelfs een co-officiële status in de provincie Friesland","feedback":{"ok":"Juist! Fries heeft een co-officiële status in Friesland.","nee":"Niet juist. Alinea 3: Fries heeft een co-officiële status in Friesland."}},{"text":"Wat betekent 'uitsterven' (alinea 4)?","type":"Woordbetekenis","options":["Steeds populairder worden","Volledig verdwijnen omdat er geen sprekers meer zijn","Verboden worden door de overheid","Veranderen in een andere taal"],"correct":1,"highlight":"veel dialecten op de rand van uitsterven staan","feedback":{"ok":"Goed! Uitsterven = volledig verdwijnen omdat er geen sprekers meer zijn.","nee":"Niet juist. Uitsterven betekent dat iets volledig verdwijnt omdat er geen dragers meer zijn."}},{"text":"Waarom worden dialecten opgenomen en vastgelegd?","type":"Inferentie","options":["Zodat ze op scholen onderwezen kunnen worden.","Zodat het talig erfgoed bewaard blijft voor toekomstige generaties.","Zodat wetenschappers betere woordenboeken kunnen maken.","Zodat dialectsprekers meer geld kunnen verdienen."],"correct":1,"highlight":"zodat het talig erfgoed bewaard blijft","feedback":{"ok":"Prima! Vastleggen zorgt dat het talig erfgoed bewaard blijft.","nee":"Niet correct. Alinea 4: zodat het talig erfgoed bewaard blijft voor toekomstige generaties."}}]},{"topic":"Steden","title":"Rotterdam: de stad die zichzelf opnieuw uitvond","paragraphs":["Rotterdam is de op een na grootste stad van Nederland en heeft de grootste haven van Europa. Op 14 mei 1940 werd het stadscentrum van Rotterdam vrijwel volledig verwoest door een bombardement van de Duitse luchtmacht. De stad moest na de Tweede Wereldoorlog van bijna niets opnieuw worden opgebouwd.","De wederopbouw van Rotterdam bood een unieke kans om een moderne stad te ontwerpen. Waar andere Nederlandse steden historische binnensteden bewaarden, kon Rotterdam experimenteren met nieuwe architectuur en stedenbouw. Dit leidde tot een skyline die in Nederland uniek is, met wolkenkrabbers, futuristische gebouwen en brede boulevards.","Rotterdam is een echte havenstad. De Rotterdamse haven, de Maasvlakte, strekt zich uit over tientallen kilometers en verwerkt jaarlijks honderden miljoenen tonnen goederen. Container- en bulkschepen uit de hele wereld lossen en laden hun goederen. De haven is een van de belangrijkste economische motoren van Nederland en Europa.","Ondanks zijn industriële imago heeft Rotterdam zich de afgelopen decennia ook cultureel ontwikkeld. Het Boijmans Van Beuningen museum, architectuurroutes en festivals als North Sea Jazz trekken bezoekers van over de hele wereld. De stad staat bekend om zijn multiculturele bevolking: meer dan de helft van de Rotterdammers heeft een niet-Nederlandse achtergrond."],"questions":[{"text":"Wanneer werd het centrum van Rotterdam verwoest?","type":"Detail","options":["Op 10 mei 1945","Op 14 mei 1940","Op 10 mei 1940","Op 14 mei 1945"],"correct":1,"highlight":"Op 14 mei 1940 werd het stadscentrum van Rotterdam vrijwel volledig verwoest","feedback":{"ok":"Goed! Op 14 mei 1940.","nee":"Niet juist. Alinea 1: op 14 mei 1940."}},{"text":"Wat maakte de wederopbouw van Rotterdam bijzonder?","type":"Detail","options":["Rotterdam koos voor herstel van de historische gebouwen.","Rotterdam mocht experimenteren met moderne architectuur en stedenbouw.","Rotterdam vroeg Belgische architecten om de stad te ontwerpen.","Rotterdam werd kleiner herbouwd dan voor de oorlog."],"correct":1,"highlight":"kon Rotterdam experimenteren met nieuwe architectuur en stedenbouw","feedback":{"ok":"Correct! Rotterdam kon experimenteren met nieuwe architectuur.","nee":"Niet correct. Alinea 2: Rotterdam kon experimenteren met nieuwe architectuur en stedenbouw."}},{"text":"Hoeveel goederen verwerkt de Rotterdamse haven per jaar?","type":"Detail","options":["Tientallen miljoenen tonnen","Honderden miljoenen tonnen","Miljoenen tonnen","Miljarden tonnen"],"correct":1,"highlight":"verwerkt jaarlijks honderden miljoenen tonnen goederen","feedback":{"ok":"Juist! Honderden miljoenen tonnen per jaar.","nee":"Niet juist. Alinea 3: honderden miljoenen tonnen goederen per jaar."}},{"text":"Wat betekent 'multicultureel' (alinea 4)?","type":"Woordbetekenis","options":["Bestaande uit mensen met veel verschillende culturele achtergronden","Een stad met veel verschillende restaurants","Een stad waar veel talen worden gesproken op scholen","Bestaande uit vooral internationale toeristen"],"correct":0,"highlight":"Rotterdam staat bekend om zijn multiculturele bevolking","feedback":{"ok":"Goed! Multicultureel = mensen met veel verschillende culturele achtergronden.","nee":"Niet juist. Multicultureel verwijst naar mensen met veel verschillende culturele achtergronden."}},{"text":"Welke culturele activiteit trekt bezoekers naar Rotterdam?","type":"Detail","options":["De Elfstedentocht","Het Amsterdam Dance Event","North Sea Jazz festival","Het Keukenhof"],"correct":2,"highlight":"festivals als North Sea Jazz trekken bezoekers van over de hele wereld","feedback":{"ok":"Prima! North Sea Jazz festival trekt bezoekers uit de hele wereld.","nee":"Niet correct. Alinea 4: North Sea Jazz festival trekt bezoekers."}}]},{"topic":"Fietsen","title":"Waarom de fiets het populairste vervoermiddel van Nederland is","paragraphs":["In Nederland is de fiets een van de meest gebruikte vervoermiddelen. Bijna iedereen heeft een fiets en gebruikt die dagelijks, voor school, werk of boodschappen. Nederland telt meer fietsen dan inwoners, wat laat zien hoe belangrijk fietsen is in het dagelijks leven. Kinderen leren al op jonge leeftijd fietsen, vaak nog voordat ze naar de basisschool gaan. Fietsen wordt gezien als een normale manier van vervoer, niet als een sport of hobby.","Het land heeft een uitgebreid netwerk van fietspaden, die vaak gescheiden zijn van de rijbaan voor auto's. Dit maakt fietsen veiliger en aantrekkelijker, ook voor kinderen en ouderen. In grote steden zoals Amsterdam en Utrecht zijn er speciale fietsparkeergarages met plaats voor duizenden fietsen. Verkeerslichten zijn vaak afgestemd op fietsers, zodat zij snel en veilig kunnen doorrijden. Deze infrastructuur wordt al tientallen jaren verder ontwikkeld en verbeterd.","Fietsen heeft veel voordelen. Het is goedkoop, gezond en goed voor het milieu, omdat er geen brandstof nodig is. Bovendien is fietsen in de stad vaak sneller dan de auto, vooral tijdens de spits, wanneer wegen vol staan met verkeer. Veel Nederlanders combineren de fiets met het openbaar vervoer: ze fietsen naar het station en nemen daarna de trein naar hun werk of school. Dit heet ook wel voor- en natransport.","Voor mensen uit andere landen kan het fietsgedrag van Nederlanders soms verrassend zijn. Fietsers vervoeren boodschappen, kinderen en zelfs meubels op hun fiets. Ook rijden mensen vaak zonder helm, omdat fietsen als veilig wordt beschouwd dankzij de goede infrastructuur. De fiets is voor veel Nederlanders niet alleen een vervoermiddel, maar ook een symbool van hun manier van leven: praktisch, onafhankelijk en dicht bij de natuur."],"questions":[{"text":"Wat laat zien hoe belangrijk fietsen is in Nederland?","type":"Detail","options":["Nederland heeft meer auto's dan fietsen.","Nederland telt meer fietsen dan inwoners.","Kinderen fietsen pas na hun achttiende.","Fietsen is alleen populair in Amsterdam."],"correct":1,"highlight":"Nederland telt meer fietsen dan inwoners","feedback":{"ok":"Goed! Nederland heeft meer fietsen dan inwoners.","nee":"Niet juist. Alinea 1 zegt dat Nederland meer fietsen dan inwoners telt."}},{"text":"Wat is kenmerkend voor de fietspaden in Nederland?","type":"Detail","options":["Ze lopen vaak samen met de rijbaan voor auto's.","Ze zijn alleen te vinden op het platteland.","Ze zijn vaak gescheiden van de rijbaan voor auto's.","Ze zijn alleen bedoeld voor sportfietsers."],"correct":2,"highlight":"vaak gescheiden zijn van de rijbaan voor auto's","feedback":{"ok":"Klopt! Fietspaden zijn vaak gescheiden van de rijbaan voor auto's.","nee":"Niet correct. Alinea 2 legt uit dat fietspaden vaak gescheiden zijn van de rijbaan."}},{"text":"Waarom fietsen veel Nederlanders naar het station voordat ze de trein nemen?","type":"Inferentie","options":["Omdat fietsen verplicht is bij de trein.","Omdat treinen in Nederland niet vaak rijden.","Omdat fietsen goedkoper is dan een treinkaartje.","Omdat ze op die manier reistijd besparen en flexibel blijven."],"correct":3,"highlight":"fietsen naar het station en nemen daarna de trein naar hun werk of school","feedback":{"ok":"Precies! Zo besparen ze tijd en blijven ze flexibel.","nee":"Niet helemaal. Alinea 3 legt uit dat mensen fietsen en dan de trein nemen om tijd te besparen."}},{"text":"Wat betekent 'de spits' in de tekst?","type":"Woordbetekenis","options":["De tijd van de dag met veel verkeer.","Een stil moment op de weg.","Een fietspad buiten de stad.","Een soort verkeerslicht."],"correct":0,"highlight":"tijdens de spits, wanneer wegen vol staan met verkeer","feedback":{"ok":"Juist! De spits is de drukke tijd met veel verkeer.","nee":"Niet juist. Alinea 3 legt uit dat de spits de drukke verkeerstijd is."}},{"text":"Wat is de hoofdgedachte van de tekst?","type":"Hoofdgedachte","options":["Fietsen is in Nederland alleen een sport.","Auto's zijn in Nederland populairder dan fietsen.","De fiets is een praktisch en belangrijk onderdeel van het dagelijks leven in Nederland.","Fietsen is in Nederland verboden zonder helm."],"correct":2,"highlight":"De fiets is voor veel Nederlanders niet alleen een vervoermiddel, maar ook een symbool van hun manier van leven","feedback":{"ok":"Mooi! De fiets is inderdaad een praktisch en belangrijk deel van het dagelijks leven.","nee":"Niet helemaal. De kern van de tekst is dat de fiets een praktisch en belangrijk onderdeel is van het leven in Nederland."}}]},{"topic":"Koningsdag","title":"Koningsdag: het feest van de koning en het hele land","paragraphs":["Op 27 april viert Nederland Koningsdag, de verjaardag van koning Willem-Alexander. Het is een nationale feestdag waarop scholen, veel winkels en kantoren gesloten zijn. Overal in het land dragen mensen oranje kleding, omdat oranje de kleur van het Koninklijk Huis is. Straten, huizen en pleinen worden versierd met oranje vlaggen, ballonnen en slingers. Voor veel Nederlanders is Koningsdag een van de gezelligste dagen van het jaar.","Een bekend onderdeel van Koningsdag is de vrijmarkt. Op die dag mag iedereen zonder vergunning spullen verkopen op straat, in parken of op pleinen. Vooral kinderen doen hier graag aan mee: ze verkopen oude speelgoed, boeken en kleren voor een klein bedrag. De vrijmarkt zorgt voor een gezellige sfeer in de straten en geeft mensen de kans om spullen die ze niet meer gebruiken door te verkopen aan anderen.","De koning en zijn familie bezoeken elk jaar een of twee steden om Koningsdag te vieren. Daar doen ze mee aan activiteiten, spreken ze met inwoners en bekijken ze optredens. De bezoeken worden live uitgezonden op televisie, zodat mensen in het hele land kunnen meekijken. In veel steden worden ook concerten en festivals georganiseerd, met muziek, eten en drinken voor jong en oud.","Koningsdag bestaat sinds 2014, toen de naam veranderde na de troonswisseling van koningin Beatrix naar koning Willem-Alexander. Daarvoor heette de feestdag Koninginnedag en werd die gevierd op 30 april. De datum van 27 april is gekozen omdat dat de verjaardag van de huidige koning is. Koningsdag laat zien hoe belangrijk het Koninklijk Huis is voor de nationale identiteit en saamhorigheid in Nederland."],"questions":[{"text":"Op welke datum wordt Koningsdag gevierd?","type":"Detail","options":["30 april","5 mei","27 april","31 augustus"],"correct":2,"highlight":"Op 27 april viert Nederland Koningsdag","feedback":{"ok":"Goed! Koningsdag is op 27 april.","nee":"Niet juist. Alinea 1 zegt dat Koningsdag op 27 april wordt gevierd."}},{"text":"Wat mogen mensen doen tijdens de vrijmarkt op Koningsdag?","type":"Detail","options":["Zonder vergunning spullen verkopen op straat.","Gratis het paleis bezoeken.","Een dag vrij nemen van school zonder reden.","Gratis met het openbaar vervoer reizen."],"correct":0,"highlight":"mag iedereen zonder vergunning spullen verkopen op straat","feedback":{"ok":"Correct! Op de vrijmarkt mag iedereen zonder vergunning spullen verkopen.","nee":"Niet correct. Alinea 2 legt uit dat mensen zonder vergunning spullen mogen verkopen."}},{"text":"Waarom worden de bezoeken van de koning live uitgezonden op televisie?","type":"Inferentie","options":["Omdat de koning dat wettelijk verplicht is.","Zodat mensen in het hele land kunnen meekijken, ook als ze niet aanwezig zijn.","Omdat er anders niemand naar het bezoek zou komen.","Omdat de televisie dat elk jaar verplicht uitzendt."],"correct":1,"highlight":"worden live uitgezonden op televisie, zodat mensen in het hele land kunnen meekijken","feedback":{"ok":"Precies! Zo kan iedereen meekijken, ook van thuis.","nee":"Niet helemaal. Alinea 3 legt uit dat de uitzending mensen in het hele land laat meekijken."}},{"text":"Wat betekent 'troonswisseling'?","type":"Woordbetekenis","options":["Een verjaardagsfeest voor de koning.","Het moment waarop een nieuwe koning of koningin aantreedt.","Een verandering van de kleur oranje.","Een nationale feestdag in mei."],"correct":1,"highlight":"de troonswisseling van koningin Beatrix naar koning Willem-Alexander","feedback":{"ok":"Juist! Een troonswisseling is het aantreden van een nieuwe vorst.","nee":"Niet juist. Alinea 4 gebruikt 'troonswisseling' voor de overgang naar een nieuwe koning."}},{"text":"Wat is de hoofdgedachte van de tekst?","type":"Hoofdgedachte","options":["Koningsdag is alleen belangrijk voor de koninklijke familie.","Koningsdag is een nationale feestdag die saamhorigheid en de band met het Koninklijk Huis laat zien.","Koningsdag wordt niet meer gevierd sinds 2014.","Koningsdag is hetzelfde als Koninginnedag."],"correct":1,"highlight":"Koningsdag laat zien hoe belangrijk het Koninklijk Huis is voor de nationale identiteit en saamhorigheid","feedback":{"ok":"Mooi! Koningsdag laat de saamhorigheid en band met het Koninklijk Huis zien.","nee":"Niet helemaal. De tekst laat zien dat Koningsdag vooral saamhorigheid en de band met het Koninklijk Huis toont."}}]},{"topic":"Sinterklaas","title":"Sinterklaas: een Nederlandse traditie in december","paragraphs":["Sinterklaas is een Nederlandse traditie die niets te maken heeft met kerst. Het feest draait om Sinterklaas, een oudere man met een baard, die half november met een stoomboot uit Spanje zou aankomen. Deze aankomst heet de intocht en wordt in veel steden gevierd met een optocht door de straten. Kinderen wachten dan vol spanning op Sinterklaas en zijn helpers, die snoep en kleine cadeautjes uitdelen aan het publiek.","Sinterklaas wordt geholpen door pieten, die hem assisteren bij het regelen van cadeaus voor kinderen. Op de avond van 5 december, pakjesavond, krijgen kinderen cadeautjes die zogenaamd door Sinterklaas zijn gebracht. Vaak worden de cadeaus verstopt of ingepakt met een grappig gedicht erbij. Volwassenen doen ook mee aan deze traditie: ze trekken loten en schrijven gedichten voor elkaar, vaak met humor over eigenschappen van de ontvanger.","In de weken voor pakjesavond zetten kinderen 's avonds hun schoen bij de schoorsteen of de deur, met een wortel voor het paard van Sinterklaas erin. De volgende ochtend zit er vaak een klein cadeautje of snoepgoed in de schoen. Typische lekkernijen bij dit feest zijn pepernoten, marsepein en chocoladeletters, waarbij elke letter meestal de eerste letter van iemands naam is.","De laatste jaren wordt er in Nederland gediscussieerd over het uiterlijk van de pieten, omdat sommige mensen dit als kwetsend ervaren. Daardoor zijn er de afgelopen jaren aanpassingen gemaakt aan hoe pieten eruitzien. Ondanks deze discussie blijft Sinterklaas voor veel Nederlandse gezinnen een belangrijk en geliefd feest, waarbij vooral kinderen genieten van de spanning, de cadeaus en de gezellige sfeer rond die tijd."],"questions":[{"text":"Waarmee zou Sinterklaas volgens de traditie in Nederland aankomen?","type":"Detail","options":["Met een vliegtuig uit Rusland.","Te voet vanuit het noorden.","Met een trein uit Duitsland.","Met een stoomboot uit Spanje."],"correct":3,"highlight":"die half november met een stoomboot uit Spanje zou aankomen","feedback":{"ok":"Goed! Sinterklaas kwam volgens de traditie met een stoomboot uit Spanje.","nee":"Niet juist. Alinea 1 zegt dat Sinterklaas met een stoomboot uit Spanje zou aankomen."}},{"text":"Wat zetten kinderen voor pakjesavond bij de schoorsteen of deur?","type":"Detail","options":["Een brief aan Sinterklaas.","Een kous met snoep erin.","Hun schoen, met een wortel voor het paard.","Een tekening voor de pieten."],"correct":2,"highlight":"zetten kinderen 's avonds hun schoen bij de schoorsteen of de deur, met een wortel voor het paard van Sinterklaas erin","feedback":{"ok":"Correct! Kinderen zetten hun schoen neer met een wortel voor het paard.","nee":"Niet correct. Alinea 3 legt uit dat kinderen hun schoen zetten met een wortel erin."}},{"text":"Wat kun je concluderen uit het feit dat volwassenen loten trekken en gedichten schrijven?","type":"Inferentie","options":["Sinterklaas is alleen een feest voor kinderen.","Ook volwassenen doen actief mee aan de Sinterklaastraditie.","Volwassenen vieren het feest liever niet.","Alleen pieten schrijven gedichten voor volwassenen."],"correct":1,"highlight":"Volwassenen doen ook mee aan deze traditie: ze trekken loten en schrijven gedichten voor elkaar","feedback":{"ok":"Precies! Ook volwassenen doen mee aan de traditie.","nee":"Niet helemaal. Alinea 2 laat zien dat volwassenen ook actief meedoen met loten en gedichten."}},{"text":"Wat betekent 'pakjesavond'?","type":"Woordbetekenis","options":["De avond waarop kinderen naar bed gaan.","De avond van de intocht van Sinterklaas.","Een avond waarop alleen volwassenen cadeaus krijgen.","De avond van 5 december waarop cadeaus worden gegeven."],"correct":3,"highlight":"Op de avond van 5 december, pakjesavond, krijgen kinderen cadeautjes","feedback":{"ok":"Juist! Pakjesavond is de avond van 5 december met cadeaus.","nee":"Niet juist. Alinea 2 legt uit dat pakjesavond op 5 december is, wanneer cadeaus gegeven worden."}},{"text":"Wat is de hoofdgedachte van de tekst?","type":"Hoofdgedachte","options":["Sinterklaas is een aparte Nederlandse traditie met eigen gebruiken, die ondanks discussie geliefd blijft.","Sinterklaas is hetzelfde feest als kerst.","Sinterklaas wordt tegenwoordig niet meer gevierd.","Sinterklaas gaat vooral over volwassenen die cadeaus geven aan pieten."],"correct":0,"highlight":"blijft Sinterklaas voor veel Nederlandse gezinnen een belangrijk en geliefd feest","feedback":{"ok":"Mooi! Sinterklaas is een eigen Nederlandse traditie die geliefd blijft.","nee":"Niet helemaal. De tekst laat zien dat Sinterklaas een aparte traditie is die ondanks discussie geliefd blijft."}}]},{"topic":"Nederlandse keuken","title":"Stamppot, poffertjes en bitterballen: de Nederlandse keuken","paragraphs":["De Nederlandse keuken staat bekend om eenvoudige en voedzame gerechten. Veel traditionele maaltijden zijn ontstaan in een tijd waarin mensen zwaar lichamelijk werk deden en behoefte hadden aan stevige kost. Aardappelen, groenten en vlees vormen vaak de basis van een Nederlandse maaltijd. Hoewel de keuken de laatste decennia internationaler is geworden, blijven traditionele gerechten populair, vooral tijdens de koude wintermaanden.","Een bekend voorbeeld van traditioneel Nederlands eten is stamppot. Dit gerecht bestaat uit gestampte aardappelen, gemengd met groenten zoals boerenkool, zuurkool of andijvie. Stamppot wordt meestal geserveerd met een rookworst of gebakken spek. Het gerecht is populair omdat het goedkoop, vullend en makkelijk te bereiden is. Vooral in de winter eten veel Nederlandse gezinnen regelmatig een stamppot als warme maaltijd.","Naast hartige gerechten kent Nederland ook typische zoete lekkernijen. Poffertjes zijn kleine, dikke pannenkoekjes die warm geserveerd worden met boter en poedersuiker. Ze worden vaak gegeten op kermissen, markten of tijdens gezellige uitjes. Ook stroopwafels, dunne wafels gevuld met een laagje karamelstroop, zijn wereldwijd bekend geworden als typisch Nederlandse lekkernij, en worden vaak bij de koffie gegeten.","Bitterballen zijn een populaire snack die vaak wordt geserveerd bij een borrel, een gezellig samenzijn met drankjes en hapjes. Ze bestaan uit een romige vulling van vlees, gepaneerd en gefrituurd tot een krokant balletje. Bitterballen worden meestal warm gegeten, samen met mosterd. Dit soort snacks laat zien dat de Nederlandse keuken niet alleen bestaat uit dagelijkse maaltijden, maar ook uit gezellige eetmomenten met vrienden of collega's."],"questions":[{"text":"Waar bestaat stamppot uit volgens de tekst?","type":"Detail","options":["Rijst met kip en groente.","Alleen rauwe groenten.","Pasta met tomatensaus.","Gestampte aardappelen gemengd met groente."],"correct":3,"highlight":"gestampte aardappelen, gemengd met groenten zoals boerenkool, zuurkool of andijvie","feedback":{"ok":"Goed! Stamppot bestaat uit gestampte aardappelen met groente.","nee":"Niet juist. Alinea 2 legt uit dat stamppot bestaat uit gestampte aardappelen met groenten."}},{"text":"Wanneer worden bitterballen vaak gegeten?","type":"Detail","options":["Bij het ontbijt.","Alleen tijdens kerst.","Bij een borrel, samen met mosterd.","Als toetje na het avondeten."],"correct":2,"highlight":"worden meestal warm gegeten, samen met mosterd","feedback":{"ok":"Correct! Bitterballen worden vaak bij een borrel met mosterd gegeten.","nee":"Niet correct. Alinea 4 zegt dat bitterballen bij een borrel met mosterd worden gegeten."}},{"text":"Wat kun je concluderen over de reden waarom traditionele Nederlandse gerechten vaak stevig en vullend zijn?","type":"Inferentie","options":["Omdat Nederlanders vroeger vooral licht werk deden.","Omdat de gerechten oorspronkelijk bedoeld waren voor mensen die zwaar lichamelijk werk verrichtten.","Omdat er vroeger weinig eten beschikbaar was.","Omdat stevige gerechten makkelijker te vervoeren waren."],"correct":1,"highlight":"ontstaan in een tijd waarin mensen zwaar lichamelijk werk deden en behoefte hadden aan stevige kost","feedback":{"ok":"Precies! De gerechten ontstonden voor mensen met zwaar werk.","nee":"Niet helemaal. Alinea 1 legt uit dat stevige kost paste bij zwaar lichamelijk werk."}},{"text":"Wat betekent 'een borrel' in de tekst?","type":"Woordbetekenis","options":["Een gezellig samenzijn met drankjes en hapjes.","Een officieel zakelijk diner.","Een warme maaltijd met aardappelen.","Een markt waar eten verkocht wordt."],"correct":0,"highlight":"een gezellig samenzijn met drankjes en hapjes","feedback":{"ok":"Juist! Een borrel is een gezellig samenzijn met drankjes en hapjes.","nee":"Niet juist. Alinea 4 legt uit dat een borrel een gezellig samenzijn is."}},{"text":"Wat is de hoofdgedachte van de tekst?","type":"Hoofdgedachte","options":["De Nederlandse keuken bestaat alleen uit zoete gerechten.","De Nederlandse keuken is uitsluitend internationaal geworden.","De Nederlandse keuken combineert eenvoudige, stevige maaltijden met gezellige hapjes en lekkernijen.","Nederlanders eten nooit traditionele gerechten."],"correct":2,"highlight":"Dit soort snacks laat zien dat de Nederlandse keuken niet alleen bestaat uit dagelijkse maaltijden, maar ook uit gezellige eetmomenten","feedback":{"ok":"Mooi! De Nederlandse keuken combineert stevige maaltijden met gezellige lekkernijen.","nee":"Niet helemaal. De tekst laat zien dat de keuken zowel stevige maaltijden als gezellige hapjes kent."}}]},{"topic":"ZZP en freelancen","title":"Werken als zzp'er: vrijheid en verantwoordelijkheid","paragraphs":["Steeds meer mensen in Nederland kiezen ervoor om als zelfstandige zonder personeel, kortweg zzp'er, te werken. Een zzp'er heeft geen vaste baas en werkt vaak voor verschillende opdrachtgevers tegelijk. Deze manier van werken wordt ook wel freelancen genoemd. Zzp'ers zijn actief in veel verschillende beroepen, van fotografen en schrijvers tot ICT-specialisten en bouwvakkers. Het aantal zzp'ers in Nederland is de afgelopen jaren flink gegroeid.","Een groot voordeel van werken als zzp'er is de vrijheid. Zzp'ers kunnen vaak zelf bepalen wanneer, waar en hoeveel ze werken. Deze flexibiliteit trekt veel mensen aan die hun werk willen combineren met andere verplichtingen, zoals de zorg voor kinderen. Ook kunnen zzp'ers zelf kiezen met welke opdrachtgevers ze samenwerken, wat het werk vaak afwisselender maakt dan een vaste baan bij één werkgever.","Toch brengt het werk als zzp'er ook verantwoordelijkheden en risico's met zich mee. Zzp'ers moeten zelf zorgen voor een pensioen, een verzekering tegen arbeidsongeschiktheid en het betalen van belasting. Als er weinig opdrachten zijn, ontvangen ze geen vast salaris, in tegenstelling tot werknemers in loondienst. Daarom is het voor zzp'ers belangrijk om financiële reserves op te bouwen voor periodes waarin er minder werk is.","Naast het uitvoeren van hun werk moeten zzp'ers ook hun eigen administratie bijhouden. Ze sturen zelf facturen naar klanten, houden hun uitgaven bij en doen jaarlijks belastingaangifte als ondernemer. Sommige zzp'ers besteden dit werk uit aan een boekhouder, anderen doen het zelf met behulp van speciale software. Goede administratie is belangrijk, omdat de Belastingdienst controleert of zzp'ers aan alle regels voldoen."],"questions":[{"text":"Wat betekent de afkorting zzp?","type":"Detail","options":["Zelfstandige zonder personeel.","Zakelijke zorgverzekering plus.","Zelfstandig zorgpersoneel.","Zzp staat voor zakelijk zelfstandig plan."],"correct":0,"highlight":"zelfstandige zonder personeel, kortweg zzp'er","feedback":{"ok":"Goed! Zzp staat voor zelfstandige zonder personeel.","nee":"Niet juist. Alinea 1 legt uit dat zzp 'zelfstandige zonder personeel' betekent."}},{"text":"Waar moeten zzp'ers zelf voor zorgen, volgens de tekst?","type":"Detail","options":["Een vast maandsalaris.","Een baas die de planning maakt.","Gratis administratieve hulp van de overheid.","Pensioen, een verzekering tegen arbeidsongeschiktheid en belasting."],"correct":3,"highlight":"moeten zelf zorgen voor een pensioen, een verzekering tegen arbeidsongeschiktheid en het betalen van belasting","feedback":{"ok":"Correct! Zzp'ers regelen zelf hun pensioen, verzekering en belasting.","nee":"Niet correct. Alinea 3 noemt pensioen, verzekering en belasting als eigen verantwoordelijkheden."}},{"text":"Waarom is het belangrijk dat zzp'ers financiële reserves opbouwen?","type":"Inferentie","options":["Omdat ze verplicht zijn om te sparen voor hun baas.","Omdat ze, anders dan werknemers in loondienst, geen vast salaris krijgen als er weinig werk is.","Omdat de Belastingdienst dit geld direct afneemt.","Omdat reserves nodig zijn om een boekhouder te betalen."],"correct":1,"highlight":"ontvangen ze geen vast salaris, in tegenstelling tot werknemers in loondienst","feedback":{"ok":"Precies! Zonder vast salaris is sparen belangrijk voor mindere periodes.","nee":"Niet helemaal. Alinea 3 legt uit dat zzp'ers geen vast salaris hebben als er weinig werk is."}},{"text":"Wat betekent 'opdrachtgevers' in de tekst?","type":"Woordbetekenis","options":["Collega's die op dezelfde afdeling werken.","Personen of bedrijven die werk of opdrachten geven.","Medewerkers van de Belastingdienst.","Mensen die bij een zzp'er in dienst zijn."],"correct":1,"highlight":"werkt vaak voor verschillende opdrachtgevers tegelijk","feedback":{"ok":"Juist! Opdrachtgevers zijn de klanten die werk geven.","nee":"Niet juist. Alinea 1 gebruikt 'opdrachtgevers' voor de klanten van een zzp'er."}},{"text":"Wat is de hoofdgedachte van de tekst?","type":"Hoofdgedachte","options":["Werken als zzp'er biedt vrijheid, maar brengt ook eigen verantwoordelijkheden en risico's met zich mee.","Zzp'ers hebben altijd een vast salaris, net als werknemers.","Freelancen is in Nederland verboden zonder vergunning.","Zzp'ers hoeven geen belasting te betalen."],"correct":0,"highlight":"brengt het werk als zzp'er ook verantwoordelijkheden en risico's met zich mee","feedback":{"ok":"Mooi! Vrijheid gaat samen met eigen verantwoordelijkheden bij zzp'ers.","nee":"Niet helemaal. De tekst laat zien dat zzp'ers vrijheid hebben, maar ook risico's dragen."}}]},{"topic":"Kinderopvang","title":"Kinderopvang in Nederland: kosten en toeslag","paragraphs":["In Nederland maken veel ouders gebruik van kinderopvang, omdat zij beiden werken of studeren. Er zijn verschillende vormen van kinderopvang, zoals een kinderdagverblijf voor de kleinste kinderen, gastouderopvang bij iemand thuis en buitenschoolse opvang voor kinderen die al naar school gaan. Ouders kiezen vaak een vorm die het beste past bij hun werktijden en de leeftijd van hun kind.","Kinderopvang in Nederland kan behoorlijk duur zijn. De kosten hangen af van het aantal uren dat een kind naar de opvang gaat en van het soort opvang. Gemiddeld betalen ouders enkele euro's per uur per kind, wat bij fulltime opvang kan oplopen tot honderden euro's per maand. Voor veel gezinnen zouden deze kosten zonder extra hulp een groot deel van het inkomen opslokken.","Om kinderopvang betaalbaar te houden, kunnen ouders kinderopvangtoeslag aanvragen bij de Belastingdienst. Deze toeslag is een financiële bijdrage van de overheid die een deel van de kosten vergoedt. De hoogte van de toeslag hangt af van het inkomen van de ouders en het aantal uren dat zij werken. Ouders met een lager inkomen krijgen meestal een groter deel van de kosten vergoed dan ouders met een hoger inkomen.","Kinderopvang speelt een belangrijke rol in de Nederlandse samenleving, omdat het ouders de mogelijkheid geeft om te blijven werken na de geboorte van een kind. Daarnaast leren kinderen op de opvang spelenderwijs sociale vaardigheden, doordat ze omgaan met andere kinderen. De laatste jaren wordt er in de politiek gesproken over het nog toegankelijker en goedkoper maken van kinderopvang voor alle gezinnen."],"questions":[{"text":"Welke vorm van kinderopvang is bedoeld voor kinderen die al naar school gaan?","type":"Detail","options":["Kinderdagverblijf.","Gastouderopvang.","Buitenschoolse opvang.","Peuterspeelzaal."],"correct":2,"highlight":"buitenschoolse opvang voor kinderen die al naar school gaan","feedback":{"ok":"Goed! Buitenschoolse opvang is voor kinderen die al naar school gaan.","nee":"Niet juist. Alinea 1 noemt buitenschoolse opvang voor kinderen die al naar school gaan."}},{"text":"Wat bepaalt de hoogte van de kinderopvangtoeslag?","type":"Detail","options":["De leeftijd van het kind.","Het inkomen van de ouders en het aantal uren dat zij werken.","Het aantal kinderen in de klas.","De locatie van de kinderopvang."],"correct":1,"highlight":"hangt af van het inkomen van de ouders en het aantal uren dat zij werken","feedback":{"ok":"Correct! Inkomen en gewerkte uren bepalen de hoogte van de toeslag.","nee":"Niet correct. Alinea 3 legt uit dat inkomen en gewerkte uren de toeslag bepalen."}},{"text":"Wat kun je concluderen over gezinnen met een lager inkomen en kinderopvangtoeslag?","type":"Inferentie","options":["Zij krijgen geen recht op kinderopvangtoeslag.","Zij mogen hun kind niet naar een kinderdagverblijf brengen.","Zij krijgen relatief meer vergoed, waardoor kinderopvang toegankelijker voor hen wordt.","Zij moeten hogere kosten betalen dan gezinnen met een hoger inkomen."],"correct":2,"highlight":"Ouders met een lager inkomen krijgen meestal een groter deel van de kosten vergoed","feedback":{"ok":"Precies! Lagere inkomens krijgen relatief meer vergoed.","nee":"Niet helemaal. Alinea 3 zegt dat ouders met een lager inkomen meer vergoed krijgen."}},{"text":"Wat betekent 'opslokken' in de tekst?","type":"Woordbetekenis","options":["Besparen.","Terugbetalen aan de overheid.","Langzaam laten groeien.","Een groot deel van iets innemen of verbruiken."],"correct":3,"highlight":"zouden deze kosten zonder extra hulp een groot deel van het inkomen opslokken","feedback":{"ok":"Juist! Opslokken betekent dat iets een groot deel opneemt.","nee":"Niet juist. Alinea 2 gebruikt 'opslokken' voor het grote deel van het inkomen dat opgaat aan kosten."}},{"text":"Wat is de hoofdgedachte van de tekst?","type":"Hoofdgedachte","options":["Kinderopvang kan duur zijn, maar toeslag helpt ouders om het betaalbaar te houden en speelt een belangrijke maatschappelijke rol.","Kinderopvang is in Nederland gratis voor alle gezinnen.","Kinderopvang is alleen bedoeld voor kinderen die nog niet naar school gaan.","De overheid geeft geen enkele financiële steun voor kinderopvang."],"correct":0,"highlight":"kunnen ouders kinderopvangtoeslag aanvragen bij de Belastingdienst","feedback":{"ok":"Mooi! Toeslag maakt kinderopvang betaalbaarder en het speelt een belangrijke rol.","nee":"Niet helemaal. De tekst laat zien dat toeslag kinderopvang betaalbaarder maakt en dat het belangrijk is voor de samenleving."}}]},{"topic":"Deeleconomie","title":"De deeleconomie: samen delen in plaats van alleen bezitten","paragraphs":["De deeleconomie is een manier van consumeren waarbij mensen spullen, diensten of ruimte met elkaar delen in plaats van alles zelf te kopen. Dankzij internet en speciale apps is het tegenwoordig makkelijk om iets te huren, te lenen of te delen met anderen. De deeleconomie is de afgelopen jaren sterk gegroeid, vooral in steden waar mensen dicht bij elkaar wonen en spullen efficiënter kunnen gebruiken.","Een bekend voorbeeld van de deeleconomie is autodelen. In plaats van zelf een auto te kopen, kunnen mensen via een app een auto huren die eigendom is van een particulier of een bedrijf. Dit is vooral aantrekkelijk voor mensen die niet dagelijks een auto nodig hebben. Autodelen bespaart geld en zorgt er bovendien voor dat er minder auto's nodig zijn, wat goed is voor de ruimte in steden.","Ook gereedschap wordt steeds vaker gedeeld. In sommige buurten bestaat een gereedschapsbibliotheek, waar bewoners boren, zagen en andere gereedschappen kunnen lenen in plaats van kopen. Dit is handig voor spullen die mensen maar af en toe gebruiken. Zo hoeft niet iedereen dezelfde boormachine te bezitten, die vervolgens het grootste deel van het jaar ongebruikt in een kast blijft liggen.","Daarnaast bestaan er platforms waarmee mensen een kamer of woning aan reizigers kunnen verhuren, vergelijkbaar met een hotel. Dit geeft toeristen goedkopere en persoonlijkere overnachtingsopties, en geeft verhuurders een extra inkomen. Tegelijkertijd zorgt dit in populaire steden soms voor discussie, omdat woningen die aan toeristen worden verhuurd niet meer beschikbaar zijn voor bewoners die er zelf willen wonen."],"questions":[{"text":"Wat is een voorbeeld van autodelen?","type":"Detail","options":["Een auto lenen van de gereedschapsbibliotheek.","Een auto huren via een app in plaats van er zelf een te kopen.","Een auto kopen met korting via internet.","Een auto delen alleen binnen de eigen familie."],"correct":1,"highlight":"kunnen mensen via een app een auto huren die eigendom is van een particulier of een bedrijf","feedback":{"ok":"Goed! Autodelen betekent een auto huren via een app.","nee":"Niet juist. Alinea 2 legt uit dat autodelen inhoudt dat je een auto huurt via een app."}},{"text":"Wat kunnen bewoners lenen bij een gereedschapsbibliotheek?","type":"Detail","options":["Boren, zagen en andere gereedschappen.","Auto's en fietsen.","Boeken en tijdschriften.","Meubels voor in huis."],"correct":0,"highlight":"boren, zagen en andere gereedschappen kunnen lenen in plaats van kopen","feedback":{"ok":"Correct! Bij een gereedschapsbibliotheek kun je boren, zagen en meer lenen.","nee":"Niet correct. Alinea 3 noemt boren, zagen en andere gereedschappen."}},{"text":"Waarom kan het verhuren van woningen aan toeristen tot discussie leiden in populaire steden?","type":"Inferentie","options":["Omdat toeristen nooit voor overnachtingen betalen.","Omdat woningen die verhuurd worden aan toeristen niet meer beschikbaar zijn voor bewoners.","Omdat verhuurders hier geen inkomen mee verdienen.","Omdat toeristen liever in hotels overnachten."],"correct":1,"highlight":"woningen die aan toeristen worden verhuurd niet meer beschikbaar zijn voor bewoners die er zelf willen wonen","feedback":{"ok":"Precies! Verhuurde woningen zijn niet meer beschikbaar voor bewoners.","nee":"Niet helemaal. Alinea 4 legt uit dat verhuurde woningen niet meer beschikbaar zijn voor bewoners."}},{"text":"Wat betekent 'particulier' in de tekst?","type":"Woordbetekenis","options":["Een groot bedrijf.","Een overheidsinstantie.","Een individuele persoon, geen bedrijf.","Een toerist uit het buitenland."],"correct":2,"highlight":"eigendom is van een particulier of een bedrijf","feedback":{"ok":"Juist! Een particulier is een individuele persoon, geen bedrijf.","nee":"Niet juist. Alinea 2 gebruikt 'particulier' voor een individuele eigenaar, niet een bedrijf."}},{"text":"Wat is de hoofdgedachte van de tekst?","type":"Hoofdgedachte","options":["De deeleconomie draait om spullen en ruimte delen in plaats van alles zelf te bezitten, wat voordelen maar ook discussie oplevert.","De deeleconomie bestaat alleen uit het delen van auto's.","Iedereen moet verplicht meedoen aan de deeleconomie.","De deeleconomie zorgt er alleen voor dat woningen duurder worden."],"correct":0,"highlight":"De deeleconomie is een manier van consumeren waarbij mensen spullen, diensten of ruimte met elkaar delen","feedback":{"ok":"Mooi! De deeleconomie gaat over delen in plaats van bezitten, met voor- en nadelen.","nee":"Niet helemaal. De tekst laat zien dat de deeleconomie draait om delen, wat voordelen en discussie oplevert."}}]},{"topic":"Kansspelen","title":"De Postcodeloterij: geluk hebben met je postcode","paragraphs":["Loterijen zijn al lange tijd populair in Nederland. Een van de bekendste is de Nationale Postcodeloterij, die in 1989 is opgericht. Bij deze loterij wint niet één persoon een prijs, maar kan een hele straat winnen. Elke week wordt willekeurig een postcode getrokken, en alle deelnemers met die postcode krijgen dan een prijs. Deelnemers betalen elke maand voor hun lot, in de hoop dat hun postcode ooit wordt getrokken.","Een bijzonder kenmerk van de Postcodeloterij is dat een deel van de opbrengst naar goede doelen gaat. Miljoenen euro's worden jaarlijks besteed aan organisaties die zich inzetten voor natuur, mensenrechten en ontwikkelingssamenwerking. Daarom zien veel mensen meedoen aan de loterij niet alleen als een kans om te winnen, maar ook als een manier om iets terug te doen voor de samenleving. Deze combinatie van spel en liefdadigheid maakt de loterij in Nederland uniek.","Kansspelen in Nederland worden streng gecontroleerd door de Kansspelautoriteit, een onafhankelijke toezichthouder. Deze organisatie geeft vergunningen aan loterijen en casino's en controleert of aanbieders zich aan de regels houden. Sinds oktober 2021 is het ook legaal om online te gokken, mits een bedrijf hiervoor een vergunning heeft. Voor die tijd was online gokken bij Nederlandse aanbieders niet toegestaan, hoewel veel mensen toch bij buitenlandse websites speelden.","Ondanks de populariteit van kansspelen kleven er ook risico's aan. Sommige mensen ontwikkelen een gokverslaving, waarbij ze de controle over hun speelgedrag verliezen. Dit kan leiden tot financiële problemen en stress binnen gezinnen. Daarom besteedt de overheid aandacht aan verslavingspreventie en verwijst reclame voor kansspelen altijd naar hulporganisaties. Het doel is dat mensen kunnen genieten van het spel, zonder dat dit hun leven negatief beïnvloedt."],"questions":[{"text":"In welk jaar is de Nationale Postcodeloterij opgericht?","type":"Detail","options":["1975","1999","1989","2005"],"correct":2,"highlight":"die in 1989 is opgericht","feedback":{"ok":"Klopt! De loterij is in 1989 opgericht.","nee":"Niet juist. Alinea 1 noemt 1989 als oprichtingsjaar."}},{"text":"Waar gaat een deel van de opbrengst van de Postcodeloterij naartoe?","type":"Detail","options":["Naar goede doelen","Naar de deelnemers zelf","Naar de Belastingdienst","Naar de Kansspelautoriteit"],"correct":0,"highlight":"een deel van de opbrengst naar goede doelen gaat","feedback":{"ok":"Goed! Een deel van de opbrengst gaat naar goede doelen.","nee":"Niet correct. Alinea 2 legt uit dat een deel naar goede doelen gaat."}},{"text":"Wat kun je concluderen over waarom mensen aan de Postcodeloterij meedoen?","type":"Inferentie","options":["Alleen om financieel gewin","Omdat het verplicht is","Omdat de overheid dit promoot","Zowel voor de kans op winst als om iets bij te dragen aan de samenleving"],"correct":3,"highlight":"niet alleen als een kans om te winnen, maar ook als een manier om iets terug te doen voor de samenleving","feedback":{"ok":"Juist! Mensen doen mee voor de kans op winst én om iets bij te dragen.","nee":"Niet helemaal. Alinea 2 laat zien dat mensen ook meedoen om iets terug te doen voor de samenleving."}},{"text":"Wat betekent 'toezichthouder' in de tekst?","type":"Woordbetekenis","options":["Iemand die geld uitleent","Een deelnemer aan een loterij","Een organisatie die controleert of regels worden nageleefd","Een reclamebureau"],"correct":2,"highlight":"onafhankelijke toezichthouder","feedback":{"ok":"Correct! Een toezichthouder controleert of regels worden nageleefd.","nee":"Niet juist. Alinea 3 noemt de Kansspelautoriteit als toezichthouder die controleert."}},{"text":"Wat is de hoofdboodschap van deze tekst?","type":"Hoofdgedachte","options":["Kansspelen zijn verboden in Nederland","Iedereen zou moeten meedoen aan de loterij","Online gokken is altijd illegaal","Kansspelen zijn populair en streng gereguleerd, met zowel voordelen als risico's"],"correct":3,"highlight":"Ondanks de populariteit van kansspelen kleven er ook risico's aan","feedback":{"ok":"Precies! Kansspelen zijn populair, maar ook streng gereguleerd en niet zonder risico.","nee":"Niet helemaal. De tekst laat zien dat kansspelen populair zijn, streng gereguleerd worden en risico's kennen."}}]},{"topic":"Cabaret","title":"Cabaret: lachen en nadenken tegelijk","paragraphs":["Cabaret is een theatervorm die in Nederland al meer dan honderd jaar bestaat. Het combineert humor, muziek en persoonlijke verhalen in één voorstelling. Een cabaretier staat meestal alleen op het podium en vertelt grappige, maar ook serieuze verhalen over het leven. Cabaret verschilt van gewone stand-up comedy, omdat er vaak ook liedjes en een rode draad door de voorstelling lopen. Veel Nederlanders groeien op met cabaret op televisie.","Een cabaretier maakt meestal één nieuwe voorstelling per jaar en gaat daarmee op theatertournee. Zo'n tournee duurt vaak maanden en de cabaretier speelt de show in tientallen theaters door het hele land. Tijdens de voorstelling wisselen grappige sketches, liedjes en persoonlijke anekdotes elkaar af. Het publiek verwacht dat de cabaretier niet alleen vermaakt, maar ook een boodschap meegeeft die tot nadenken zet.","Cabaret gaat vaak over maatschappelijke onderwerpen, zoals politiek, ongelijkheid of actuele gebeurtenissen. Door humor te gebruiken, kunnen cabaretiers moeilijke thema's op een toegankelijke manier bespreken. Het publiek lacht, maar wordt tegelijk aan het denken gezet over de wereld om hen heen. Deze combinatie van vermaak en kritiek maakt cabaret tot meer dan alleen amusement; het is ook een vorm van maatschappelijke reflectie.","Elk jaar worden de beste cabaretvoorstellingen beloond met prijzen, zoals de Poelifinario. Deze prijzen vergroten de bekendheid van cabaretiers en trekken nieuw publiek naar de theaters. Cabaret blijft populair bij zowel jongeren als ouderen, mede dankzij televisieregistraties van voorstellingen. Doordat cabaret zich steeds aanpast aan actuele thema's, blijft deze typisch Nederlandse traditie relevant voor nieuwe generaties."],"questions":[{"text":"Wat doet een cabaretier tijdens een theatertournee?","type":"Detail","options":["Hij speelt elke avond in hetzelfde theater","Hij treedt alleen op televisie op","Hij schrijft alleen liedjes zonder op te treden","Hij speelt dezelfde show in tientallen theaters door het land"],"correct":3,"highlight":"speelt de show in tientallen theaters door het hele land","feedback":{"ok":"Klopt! De cabaretier speelt dezelfde show in veel theaters.","nee":"Niet juist. Alinea 2 beschrijft dat de cabaretier in tientallen theaters speelt."}},{"text":"Waarmee worden de beste cabaretvoorstellingen beloond?","type":"Detail","options":["Met prijzen zoals de Poelifinario","Met een record","Met een Oscar","Met een gouden plaat"],"correct":0,"highlight":"beloond met prijzen, zoals de Poelifinario","feedback":{"ok":"Goed! Prijzen zoals de Poelifinario worden uitgereikt.","nee":"Niet correct. Alinea 4 noemt de Poelifinario als voorbeeld van een prijs."}},{"text":"Wat kun je afleiden over de functie van humor in cabaret?","type":"Inferentie","options":["Humor is alleen bedoeld om te ontspannen","Humor wordt vermeden in serieuze voorstellingen","Humor helpt om moeilijke onderwerpen bespreekbaar te maken","Humor maakt cabaret minder populair"],"correct":2,"highlight":"Door humor te gebruiken, kunnen cabaretiers moeilijke thema's op een toegankelijke manier bespreken","feedback":{"ok":"Juist! Humor maakt moeilijke onderwerpen bespreekbaar.","nee":"Niet helemaal. Alinea 3 legt uit dat humor helpt om moeilijke thema's te bespreken."}},{"text":"Wat betekent 'een rode draad' in de tekst?","type":"Woordbetekenis","options":["Een kleur op het podium","Een kostuum van de cabaretier","Een terugkerend thema dat de voorstelling verbindt","Een technische lichteffect"],"correct":2,"highlight":"een rode draad door de voorstelling lopen","feedback":{"ok":"Correct! Een rode draad is een terugkerend thema.","nee":"Niet juist. Alinea 1 gebruikt 'rode draad' voor een verbindend thema."}},{"text":"Wat is de hoofdboodschap van deze tekst?","type":"Hoofdgedachte","options":["Cabaret is alleen bedoeld voor ouderen","Cabaret is een Nederlandse traditie die vermaak combineert met maatschappelijke reflectie","Cabaret bestaat pas sinds kort in Nederland","Cabaret gaat nooit over politiek"],"correct":1,"highlight":"een vorm van maatschappelijke reflectie","feedback":{"ok":"Precies! Cabaret combineert vermaak met maatschappelijke reflectie.","nee":"Niet helemaal. Alinea 3 laat zien dat cabaret vermaak en reflectie combineert."}}]},{"topic":"Buurthuizen","title":"Buurthuizen: de huiskamer van de wijk","paragraphs":["In veel Nederlandse wijken staat een buurthuis, een plek waar bewoners elkaar kunnen ontmoeten. Buurthuizen bieden ruimte voor allerlei activiteiten, zoals koffieochtenden, taallessen, creatieve cursussen en spelletjesmiddagen. Iedereen is welkom, ongeacht leeftijd of achtergrond. Voor veel mensen is het buurthuis een plek waar ze nieuwe contacten kunnen leggen, vooral als ze weinig sociale contacten hebben in hun directe omgeving.","De meeste buurthuizen worden gerund door vrijwilligers, ondersteund door een klein team van beroepskrachten. Gemeenten dragen vaak financieel bij, omdat buurthuizen bijdragen aan een betere sociale samenhang in de wijk. Zonder deze steun zouden veel buurthuizen moeite hebben om open te blijven, want de kosten voor huur, energie en activiteiten lopen snel op. Vrijwilligers zijn dus onmisbaar voor het voortbestaan van deze plekken.","Buurthuizen spelen een belangrijke rol in de strijd tegen eenzaamheid, vooral onder ouderen. Door regelmatig activiteiten te organiseren, krijgen mensen die weinig buiten komen toch de kans om anderen te ontmoeten. Onderzoek toont aan dat sociale contacten bijdragen aan een beter gevoel van welzijn. Daarom worden buurthuizen door gemeenten gezien als een belangrijk middel om eenzaamheid onder inwoners te verminderen.","Naast ontmoeting bieden buurthuizen ook praktische hulp, zoals ondersteuning bij het invullen van formulieren of hulp bij het vinden van werk. Sommige buurthuizen organiseren ook huiswerkbegeleiding voor kinderen of workshops over gezonde voeding. Door dit brede aanbod groeit het buurthuis uit tot meer dan een ontmoetingsplek; het wordt een plek waar bewoners elkaar op allerlei manieren kunnen helpen en versterken."],"questions":[{"text":"Wie runnen de meeste buurthuizen?","type":"Detail","options":["Alleen betaalde medewerkers","De gemeenteraad","Alleen jongeren uit de wijk","Vrijwilligers, ondersteund door een klein team van beroepskrachten"],"correct":3,"highlight":"gerund door vrijwilligers, ondersteund door een klein team van beroepskrachten","feedback":{"ok":"Klopt! Vrijwilligers runnen de meeste buurthuizen.","nee":"Niet juist. Alinea 2 zegt dat vrijwilligers, samen met een klein team, buurthuizen runnen."}},{"text":"Welke praktische hulp kan een buurthuis bieden?","type":"Detail","options":["Medische zorg","Hulp bij het invullen van formulieren","Juridisch advies","Belastingaangiftes verzorgen"],"correct":1,"highlight":"ondersteuning bij het invullen van formulieren","feedback":{"ok":"Goed! Buurthuizen helpen bij het invullen van formulieren.","nee":"Niet correct. Alinea 4 noemt hulp bij formulieren als voorbeeld."}},{"text":"Waarom zien gemeenten buurthuizen als belangrijk?","type":"Inferentie","options":["Omdat ze bijdragen aan sociale samenhang en minder eenzaamheid","Omdat ze veel geld opleveren","Omdat ze verplicht zijn door de wet","Omdat ze alleen voor jongeren bedoeld zijn"],"correct":0,"highlight":"bijdragen aan een betere sociale samenhang in de wijk","feedback":{"ok":"Juist! Buurthuizen dragen bij aan sociale samenhang en minder eenzaamheid.","nee":"Niet helemaal. Alinea 2 en 3 laten zien dat gemeenten buurthuizen hiervoor belangrijk vinden."}},{"text":"Wat betekent 'sociale samenhang' in de tekst?","type":"Woordbetekenis","options":["Het aantal inwoners van een wijk","De afstand tussen huizen in een wijk","De onderlinge verbondenheid tussen bewoners","De hoeveelheid geld die een gemeente heeft"],"correct":2,"highlight":"sociale samenhang in de wijk","feedback":{"ok":"Correct! Sociale samenhang gaat over verbondenheid tussen mensen.","nee":"Niet juist. Alinea 2 gebruikt de term voor onderlinge verbondenheid in de wijk."}},{"text":"Wat is de hoofdboodschap van deze tekst?","type":"Hoofdgedachte","options":["Buurthuizen zijn alleen bedoeld voor ouderen","Buurthuizen zijn belangrijke ontmoetingsplekken die sociale contacten en hulp bieden","Buurthuizen worden volledig door de overheid betaald","Buurthuizen bestaan alleen in grote steden"],"correct":1,"highlight":"wordt een plek waar bewoners elkaar op allerlei manieren kunnen helpen en versterken","feedback":{"ok":"Precies! Buurthuizen zijn ontmoetingsplekken die ook hulp bieden.","nee":"Niet helemaal. De tekst laat zien dat buurthuizen ontmoeting én hulp combineren."}}]},{"topic":"Klimaat","title":"Het Klimaatakkoord: Nederland maakt plannen voor het klimaat","paragraphs":["In 2015 spraken bijna alle landen ter wereld in Parijs af om de opwarming van de aarde te beperken. Deze afspraak heet het Klimaatakkoord van Parijs. Nederland ondertekende dit akkoord en beloofde de uitstoot van broeikasgassen te verminderen. Om deze belofte waar te maken, stelde de Nederlandse overheid in 2019 een eigen Klimaatakkoord op, met concrete doelen voor de komende decennia.","Het Nederlandse Klimaatakkoord bevat afspraken voor verschillende sectoren, zoals industrie, verkeer, landbouw en de gebouwde omgeving. Het doel is om de uitstoot van CO2 in 2030 met 49 procent te verminderen ten opzichte van 1990. Voor 2050 ligt de lat nog hoger: dan moet de uitstoot met 95 procent zijn gedaald. Deze doelen vragen grote veranderingen in hoe mensen wonen, reizen en werken.","Een belangrijk onderdeel van het akkoord is dat woningen minder aardgas gebruiken. Veel wijken schakelen daarom over op andere warmtebronnen, zoals warmtepompen of stadsverwarming. De overheid biedt subsidies voor huiseigenaren die hun woning isoleren of zonnepanelen plaatsen. Deze maatregelen moeten ervoor zorgen dat huizen minder energie verbruiken en dat de CO2-uitstoot van de gebouwde omgeving daalt.","Niet iedereen is het eens over de manier waarop Nederland de klimaatdoelen moet halen. Sommigen vinden de maatregelen te streng, terwijl anderen vinden dat de overheid juist sneller moet handelen. Toch blijft het Klimaatakkoord de basis voor het Nederlandse klimaatbeleid. De komende jaren zal moeten blijken of Nederland erin slaagt om de gestelde doelen daadwerkelijk te bereiken."],"questions":[{"text":"Met hoeveel procent moet de CO2-uitstoot in 2030 zijn verminderd ten opzichte van 1990?","type":"Detail","options":["25 procent","70 procent","49 procent","95 procent"],"correct":2,"highlight":"in 2030 met 49 procent te verminderen ten opzichte van 1990","feedback":{"ok":"Klopt! Het doel is 49 procent minder uitstoot in 2030.","nee":"Niet juist. Alinea 2 noemt 49 procent als doel voor 2030."}},{"text":"Wat biedt de overheid aan huiseigenaren die hun woning isoleren?","type":"Detail","options":["Een belastingvrijstelling","Een gratis woning","Een lening zonder rente","Subsidies"],"correct":3,"highlight":"biedt subsidies voor huiseigenaren die hun woning isoleren of zonnepanelen plaatsen","feedback":{"ok":"Goed! De overheid biedt subsidies voor isolatie en zonnepanelen.","nee":"Niet correct. Alinea 3 noemt subsidies als ondersteuning."}},{"text":"Wat kun je concluderen over de aanpak van het Klimaatakkoord?","type":"Inferentie","options":["Het vraagt veranderingen in meerdere delen van de samenleving","Het raakt alleen de industrie","Het heeft geen effect op huishoudens","Het is alleen gericht op 2050"],"correct":0,"highlight":"grote veranderingen in hoe mensen wonen, reizen en werken","feedback":{"ok":"Juist! Het akkoord vraagt veranderingen op meerdere terreinen.","nee":"Niet helemaal. Alinea 2 noemt wonen, reizen en werken als voorbeelden."}},{"text":"Wat betekent 'de gebouwde omgeving' in de tekst?","type":"Woordbetekenis","options":["Natuurgebieden en bossen","Wegen en snelwegen","Huizen en gebouwen waarin mensen wonen en werken","Fabrieken in het buitenland"],"correct":2,"highlight":"de gebouwde omgeving","feedback":{"ok":"Correct! De gebouwde omgeving zijn de huizen en gebouwen.","nee":"Niet juist. Alinea 2 gebruikt de term voor huizen en gebouwen."}},{"text":"Wat is de hoofdboodschap van deze tekst?","type":"Hoofdgedachte","options":["Nederland doet niets aan klimaatverandering","Nederland heeft concrete klimaatdoelen gesteld en werkt aan maatregelen om deze te halen","Iedereen in Nederland is het eens over het klimaatbeleid","Het Klimaatakkoord geldt alleen voor de industrie"],"correct":1,"highlight":"blijft het Klimaatakkoord de basis voor het Nederlandse klimaatbeleid","feedback":{"ok":"Precies! Nederland heeft doelen gesteld en werkt aan maatregelen.","nee":"Niet helemaal. Alinea 4 laat zien dat het Klimaatakkoord de basis blijft voor beleid."}}]},{"topic":"Verkeer","title":"Filevorming op de Nederlandse snelwegen","paragraphs":["Nederland heeft een van de dichtste wegennetten van Europa, maar ook veel verkeer. Dagelijks staan duizenden automobilisten in de file, vooral tijdens de ochtend- en avondspits. Deze spits valt meestal tussen zeven en negen uur 's ochtends en tussen vier en zes uur 's middags, wanneer veel mensen naar hun werk of weer naar huis reizen. Vooral rond grote steden zoals Amsterdam, Rotterdam en Utrecht is de kans op file groot.","Files ontstaan om verschillende redenen. Soms is er simpelweg te veel verkeer voor de beschikbare wegcapaciteit. Ook wegwerkzaamheden en ongelukken zorgen regelmatig voor vertraging. Zelfs een klein incident, zoals een auto die kort stilstaat, kan al leiden tot kilometers file, omdat andere automobilisten moeten afremmen. Rijkswaterstaat houdt de wegen dagelijks in de gaten en informeert reizigers via borden en apps over de actuele verkeerssituatie.","Om filevorming te verminderen, nemen overheid en werkgevers verschillende maatregelen. Sommige bedrijven stimuleren werknemers om vaker thuis te werken of buiten de spits te reizen. Ook wordt het gebruik van de fiets en het openbaar vervoer aangemoedigd als alternatief voor de auto. Op sommige snelwegen worden spitsstroken geopend tijdens drukke uren, zodat er tijdelijk meer rijstroken beschikbaar zijn voor het verkeer.","Ondanks deze maatregelen blijft filevorming een hardnekkig probleem in Nederland. Het aantal auto's blijft groeien, terwijl de ruimte om nieuwe wegen aan te leggen beperkt is. Experts verwachten dat alleen een combinatie van meer thuiswerken, beter openbaar vervoer en slimme verkeerstechnologie de filedruk op de lange termijn kan verminderen. Voorlopig blijft de file dus een vertrouwd beeld op de Nederlandse snelwegen."],"questions":[{"text":"Wanneer valt de ochtendspits meestal?","type":"Detail","options":["Tussen vijf en zeven uur","Tussen tien en twaalf uur","Tussen zeven en negen uur","Tussen twee en vier uur"],"correct":2,"highlight":"tussen zeven en negen uur 's ochtends","feedback":{"ok":"Klopt! De ochtendspits valt meestal tussen zeven en negen uur.","nee":"Niet juist. Alinea 1 noemt dit tijdstip voor de ochtendspits."}},{"text":"Wie informeert reizigers over de actuele verkeerssituatie?","type":"Detail","options":["De politie","De gemeente","Werkgevers","Rijkswaterstaat"],"correct":3,"highlight":"Rijkswaterstaat houdt de wegen dagelijks in de gaten","feedback":{"ok":"Goed! Rijkswaterstaat informeert reizigers over de verkeerssituatie.","nee":"Niet correct. Alinea 2 noemt Rijkswaterstaat als verantwoordelijke organisatie."}},{"text":"Wat kun je afleiden over de oorzaak van veel files?","type":"Inferentie","options":["Kleine incidenten kunnen grote gevolgen hebben voor de doorstroming","Files ontstaan altijd door slecht weer","Files komen alleen voor in de nacht","Files worden altijd veroorzaakt door wegwerkzaamheden"],"correct":0,"highlight":"kan al leiden tot kilometers file, omdat andere automobilisten moeten afremmen","feedback":{"ok":"Juist! Een klein incident kan grote gevolgen hebben voor het verkeer.","nee":"Niet helemaal. Alinea 2 legt uit dat kleine incidenten tot kilometers file kunnen leiden."}},{"text":"Wat is een 'spitsstrook'?","type":"Woordbetekenis","options":["Een fietspad langs de snelweg","Een parkeerplaats bij een file","Een extra rijstrook die tijdens drukke uren wordt geopend","Een weg alleen voor vrachtwagens"],"correct":2,"highlight":"spitsstroken geopend tijdens drukke uren","feedback":{"ok":"Correct! Een spitsstrook is een extra rijstrook tijdens drukke uren.","nee":"Niet juist. Alinea 3 beschrijft de spitsstrook zo."}},{"text":"Wat is de hoofdboodschap van deze tekst?","type":"Hoofdgedachte","options":["Files zijn volledig verdwenen door nieuwe maatregelen","Filevorming blijft een hardnekkig probleem, ondanks verschillende maatregelen","Nederlanders reizen nooit tijdens de spits","Alleen nieuwe wegen kunnen files oplossen"],"correct":1,"highlight":"filevorming een hardnekkig probleem in Nederland","feedback":{"ok":"Precies! Filevorming blijft een hardnekkig probleem, ondanks maatregelen.","nee":"Niet helemaal. Alinea 4 noemt filevorming een hardnekkig probleem."}}]},{"topic":"Studiefinanciering","title":"Studeren met een studieschuld","paragraphs":["Studeren in Nederland kost geld: collegegeld, boeken en levensonderhoud lopen al snel op. Veel studenten lenen daarom geld bij DUO, de organisatie die studiefinanciering verzorgt. Sinds 2015 bestond er geen gratis basisbeurs meer voor de meeste studenten; zij moesten volledig lenen om te kunnen studeren. Dit systeem werd het leenstelsel genoemd en zorgde ervoor dat veel studenten met een flinke schuld afstudeerden.","Door het leenstelsel bouwden studenten gemiddeld duizenden euro's schuld op tijdens hun studietijd. Deze schuld moet na de studie worden terugbetaald aan DUO, meestal over een periode van vijfentwintig tot vijfendertig jaar. De maandelijkse aflossing hangt af van het inkomen van de oud-student: wie weinig verdient, betaalt minder terug. Toch maakten veel jongeren zich zorgen over de gevolgen van hun schuld voor de toekomst.","Vanwege kritiek op het leenstelsel besloot de overheid in 2023 de basisbeurs weer in te voeren. Studenten aan het hoger onderwijs krijgen sindsdien opnieuw een vast bedrag per maand, naast de mogelijkheid om extra te lenen. Deze verandering moest de financiële druk op studenten verminderen en studeren weer aantrekkelijker maken. Studenten die eerder onder het leenstelsel studeerden, kregen bovendien een tegemoetkoming voor hun opgebouwde schuld.","Een studieschuld beïnvloedt het leven van jongeren op verschillende manieren. Banken houden bijvoorbeeld rekening met de schuld bij het bepalen van de maximale hypotheek die iemand kan krijgen. Hierdoor kunnen oud-studenten met een schuld soms minder lenen voor een huis. Toch benadrukken deskundigen dat een studieschuld niet hetzelfde is als een gewone schuld, omdat de voorwaarden voor terugbetaling gunstig zijn afgestemd op het inkomen."],"questions":[{"text":"Bij welke organisatie lenen studenten geld voor hun studie?","type":"Detail","options":["De Belastingdienst","De gemeente","De bank","DUO"],"correct":3,"highlight":"lenen daarom geld bij DUO","feedback":{"ok":"Klopt! Studenten lenen geld bij DUO.","nee":"Niet juist. Alinea 1 noemt DUO als organisatie voor studiefinanciering."}},{"text":"Wanneer voerde de overheid de basisbeurs weer in?","type":"Detail","options":["2015","2019","2023","2025"],"correct":2,"highlight":"besloot de overheid in 2023 de basisbeurs weer in te voeren","feedback":{"ok":"Goed! De basisbeurs werd in 2023 opnieuw ingevoerd.","nee":"Niet correct. Alinea 3 noemt 2023 als jaar van herinvoering."}},{"text":"Wat kun je concluderen over de invloed van een studieschuld op het volwassen leven?","type":"Inferentie","options":["Een studieschuld heeft geen enkel effect op latere financiële keuzes","Een studieschuld kan invloed hebben op bijvoorbeeld het aanvragen van een hypotheek","Een studieschuld moet altijd binnen vijf jaar worden afbetaald","Een studieschuld verdwijnt automatisch na het afstuderen"],"correct":1,"highlight":"Banken houden bijvoorbeeld rekening met de schuld bij het bepalen van de maximale hypotheek","feedback":{"ok":"Juist! Een studieschuld kan invloed hebben op bijvoorbeeld een hypotheekaanvraag.","nee":"Niet helemaal. Alinea 4 legt uit dat banken rekening houden met de studieschuld."}},{"text":"Wat betekent 'het leenstelsel' in de tekst?","type":"Woordbetekenis","options":["Een systeem waarbij studenten volledig moeten lenen in plaats van een gratis beurs te krijgen","Een spaarplan voor studenten","Een belastingvoordeel voor studenten","Een systeem waarbij studeren gratis is"],"correct":0,"highlight":"Dit systeem werd het leenstelsel genoemd","feedback":{"ok":"Correct! Het leenstelsel betekent dat studenten volledig moesten lenen.","nee":"Niet juist. Alinea 1 legt het leenstelsel zo uit."}},{"text":"Wat is de hoofdboodschap van deze tekst?","type":"Hoofdgedachte","options":["Studeren in Nederland is altijd gratis","Studiefinanciering is de afgelopen jaren veranderd en een studieschuld heeft gevolgen voor jongeren","Studenten hoeven hun schuld nooit terug te betalen","Alleen rijke studenten kunnen studeren"],"correct":1,"highlight":"de voorwaarden voor terugbetaling gunstig zijn afgestemd op het inkomen","feedback":{"ok":"Precies! Studiefinanciering is veranderd en een schuld heeft gevolgen voor jongeren.","nee":"Niet helemaal. De tekst beschrijft veranderingen in studiefinanciering en de gevolgen van een schuld."}}]},{"topic":"Verkiezingen","title":"Waarom stemmen Nederlanders? Opkomst bij verkiezingen","paragraphs":["Bij Nederlandse verkiezingen mag iedere burger vanaf achttien jaar stemmen. Vroeger was stemmen verplicht, maar sinds 1970 is deze opkomstplicht afgeschaft. Sindsdien beslist iedereen zelf of hij of zij naar het stemlokaal gaat. Toch blijft de opkomst bij de Tweede Kamerverkiezingen relatief hoog: meestal brengt rond de tachtig procent van de kiesgerechtigden zijn stem uit.","Niet bij elke verkiezing is de opkomst even hoog. Bij verkiezingen voor de Tweede Kamer stemmen doorgaans meer mensen dan bij gemeenteraadsverkiezingen of verkiezingen voor het Europees Parlement. Veel kiezers geven aan dat ze de landelijke politiek belangrijker vinden voor hun dagelijks leven dan de lokale of Europese politiek. Daardoor verschilt de opkomst per type verkiezing soms sterk.","Mensen die wel gaan stemmen, noemen vaak dat ze hun stem willen laten horen en invloed willen hebben op de toekomst van het land. Anderen zien stemmen als een burgerplicht, ook al is het niet verplicht. Mensen die niet stemmen, geven soms aan dat ze geen vertrouwen hebben in de politiek of dat ze denken dat hun stem toch geen verschil maakt.","Om de opkomst te verhogen, doen gemeenten en de overheid verschillende dingen. Zo krijgt iedere kiesgerechtigde een stempas thuisgestuurd als herinnering, en worden er vaak voorlichtingscampagnes gevoerd. Ook stemmen op meerdere locaties, zoals stembussen op stations, moet drempels verlagen. Toch blijft een deel van de bevolking structureel afwezig bij verkiezingen, wat politici en onderzoekers blijft bezighouden."],"questions":[{"text":"Sinds welk jaar is de opkomstplicht afgeschaft?","type":"Detail","options":["1950","1990","1970","2000"],"correct":2,"highlight":"sinds 1970 is deze opkomstplicht afgeschaft","feedback":{"ok":"Klopt! Sinds 1970 is de opkomstplicht afgeschaft.","nee":"Niet juist. Alinea 1 noemt 1970 als jaar van afschaffing."}},{"text":"Wat krijgt elke kiesgerechtigde thuisgestuurd als herinnering?","type":"Detail","options":["Een stempas","Een folder over kandidaten","Een uitnodiging voor een debat","Een gratis krant"],"correct":0,"highlight":"krijgt iedere kiesgerechtigde een stempas thuisgestuurd als herinnering","feedback":{"ok":"Goed! Iedere kiesgerechtigde krijgt een stempas thuisgestuurd.","nee":"Niet correct. Alinea 4 noemt de stempas als herinnering."}},{"text":"Wat kun je afleiden over waarom de opkomst bij gemeenteraadsverkiezingen lager is dan bij Tweede Kamerverkiezingen?","type":"Inferentie","options":["Mensen vinden lokale politiek belangrijker","Gemeenteraadsverkiezingen worden nooit georganiseerd","Bij gemeenteraadsverkiezingen mag niemand stemmen","Mensen vinden landelijke politiek belangrijker voor hun dagelijks leven"],"correct":3,"highlight":"de landelijke politiek belangrijker vinden voor hun dagelijks leven dan de lokale of Europese politiek","feedback":{"ok":"Juist! Mensen vinden landelijke politiek vaak belangrijker voor hun dagelijks leven.","nee":"Niet helemaal. Alinea 2 legt dit verschil in opkomst uit."}},{"text":"Wat betekent 'kiesgerechtigden' in de tekst?","type":"Woordbetekenis","options":["Mensen die een stembureau leiden","Mensen die het recht hebben om te stemmen","Mensen die politici kiezen als beroep","Mensen die verplicht zijn te stemmen"],"correct":1,"highlight":"kiesgerechtigden","feedback":{"ok":"Correct! Kiesgerechtigden zijn mensen die mogen stemmen.","nee":"Niet juist. Alinea 1 gebruikt de term voor mensen met stemrecht."}},{"text":"Wat is de hoofdboodschap van deze tekst?","type":"Hoofdgedachte","options":["Stemmen is in Nederland verplicht","Niemand in Nederland gaat stemmen","Nederlanders stemmen om verschillende redenen, en de opkomst verschilt per soort verkiezing","De opkomst is bij elke verkiezing precies gelijk"],"correct":2,"highlight":"verschilt de opkomst per type verkiezing soms sterk","feedback":{"ok":"Precies! De opkomst verschilt per soort verkiezing en mensen stemmen om diverse redenen.","nee":"Niet helemaal. Alinea 2 en 3 laten dit verschil en de redenen zien."}}]},{"topic":"Privacy","title":"Wie weet wat van jou? Privacy in het digitale tijdperk","paragraphs":["Elke dag laten mensen sporen achter op internet, vaak zonder dat ze het beseffen. Wanneer iemand een website bezoekt, wordt vaak gevraagd om cookies te accepteren. Cookies zijn kleine bestandjes die informatie opslaan over wat iemand op een website doet. Bedrijven gebruiken deze gegevens om te zien welke producten iemand interessant vindt. Zo kunnen ze gerichte advertenties tonen die passen bij de interesses van de gebruiker.","Naast cookies verzamelen apps en sociale media enorme hoeveelheden gegevens. Denk aan de locatie van een telefoon, zoekopdrachten en zelfs hoe lang iemand naar een foto kijkt. Al deze informatie samen wordt vaak 'big data' genoemd. Bedrijven gebruiken big data om patronen te ontdekken in het gedrag van mensen. Dit helpt hen om producten te verbeteren, maar het roept ook vragen op over privacy.","Veel mensen vinden het onprettig dat bedrijven zoveel over hen weten. Ze zijn bang dat hun gegevens verkeerd gebruikt worden of in verkeerde handen vallen. Daarom heeft de Europese Unie strenge regels ingevoerd, zoals de AVG (Algemene Verordening Gegevensbescherming). Deze wet verplicht bedrijven om duidelijk te vertellen welke gegevens ze verzamelen en waarom. Gebruikers moeten ook toestemming geven voordat hun gegevens gebruikt mogen worden.","Toch is het voor veel mensen lastig om echt controle te houden over hun eigen gegevens. Cookiemeldingen zijn vaak lang en ingewikkeld, waardoor mensen ze snel wegklikken zonder goed te lezen. Experts raden aan om regelmatig instellingen te controleren en na te denken over welke informatie je deelt. Bewustwording is de eerste stap om zorgvuldiger om te gaan met persoonlijke gegevens in een wereld vol technologie."],"questions":[{"text":"Wat zijn cookies volgens de tekst?","type":"Detail","options":["Grote bestanden die de computer vertragen","Kleine bestandjes die informatie opslaan over wat iemand op een website doet","Programma's die virussen verwijderen","Wachtwoorden die je moet onthouden"],"correct":1,"highlight":"Cookies zijn kleine bestandjes die informatie opslaan over wat iemand op een website doet.","feedback":{"ok":"Goed! Zo worden cookies in de tekst beschreven.","nee":"Niet juist. Alinea 1 legt uit wat cookies zijn."}},{"text":"Welke wet moet Europese burgers beschermen tegen misbruik van gegevens?","type":"Detail","options":["De Wet op de identiteitskaart","De Arbeidswet","De AVG (Algemene Verordening Gegevensbescherming)","De Huurwet"],"correct":2,"highlight":"de AVG (Algemene Verordening Gegevensbescherming)","feedback":{"ok":"Correct! De AVG beschermt gegevens van burgers.","nee":"Niet correct. Alinea 3 noemt de AVG als beschermende wet."}},{"text":"Waarom klikken veel mensen cookiemeldingen snel weg?","type":"Inferentie","options":["Omdat de meldingen vaak lang en ingewikkeld zijn","Omdat ze de meldingen niet zien","Omdat cookies verboden zijn","Omdat ze geen internet hebben"],"correct":0,"highlight":"Cookiemeldingen zijn vaak lang en ingewikkeld, waardoor mensen ze snel wegklikken zonder goed te lezen.","feedback":{"ok":"Goed afgeleid! De lengte en complexiteit zorgen daarvoor.","nee":"Niet helemaal. Alinea 4 legt uit waarom mensen snel wegklikken."}},{"text":"Wat betekent 'big data' in de tekst?","type":"Woordbetekenis","options":["Een groot computerbestand met foto's","Een soort virus op internet","Een nieuwe smartphone","Een verzameling enorme hoeveelheden gegevens die gebruikt wordt om patronen te ontdekken"],"correct":3,"highlight":"Al deze informatie samen wordt vaak 'big data' genoemd.","feedback":{"ok":"Juist! Big data is een grote verzameling gegevens.","nee":"Niet juist. Alinea 2 legt uit wat big data betekent."}},{"text":"Wat is de hoofdboodschap van deze tekst?","type":"Hoofdgedachte","options":["Cookies zijn altijd gevaarlijk en moeten verboden worden","De AVG is niet belangrijk","Bedrijven verzamelen veel gegevens over mensen, en het is belangrijk om bewust met privacy om te gaan","Niemand kan iets doen aan privacy op internet"],"correct":2,"highlight":"Bewustwording is de eerste stap om zorgvuldiger om te gaan met persoonlijke gegevens in een wereld vol technologie.","feedback":{"ok":"Prima! Bewust omgaan met privacy is de kern van de tekst.","nee":"Niet helemaal. De kern is dat bewustwording belangrijk is bij het omgaan met privacy."}}]},{"topic":"Wonen","title":"Lange wachtlijsten voor een sociale huurwoning","paragraphs":["In veel Nederlandse steden is het moeilijk om een sociale huurwoning te krijgen. Een sociale huurwoning is een woning met een lage huur, bedoeld voor mensen met een beperkt inkomen. Woningcorporaties verhuren deze woningen, maar er zijn veel meer mensen die zich inschrijven dan er woningen beschikbaar zijn. Daardoor ontstaan er lange wachtlijsten, vooral in grote steden zoals Amsterdam en Utrecht.","Wie een sociale huurwoning wil, moet zich eerst inschrijven bij een woningcorporatie. Vanaf dat moment bouwt iemand wachttijd op. Hoe langer iemand ingeschreven staat, hoe hoger de kans dat hij of zij in aanmerking komt voor een woning. In sommige steden duurt het gemiddeld meer dan tien jaar voordat iemand een geschikte woning krijgt aangeboden. Jongeren die net zelfstandig willen wonen, ondervinden hier veel hinder van.","Het tekort aan sociale huurwoningen heeft verschillende oorzaken. Er worden te weinig nieuwe woningen gebouwd, terwijl de bevolking blijft groeien. Ook kiezen sommige gemeenten ervoor om meer dure woningen te bouwen, omdat dit financieel aantrekkelijker is. Daarnaast verhuizen mensen minder vaak dan vroeger, waardoor woningen die vrijkomen schaarser worden. Deskundigen waarschuwen dat het probleem de komende jaren niet snel zal verdwijnen.","Om de wachttijd te verkorten, proberen gemeenten en corporaties nieuwe oplossingen te vinden. Sommige steden bouwen tijdelijke woningen die sneller klaar zijn dan gewone huizen. Andere gemeenten geven voorrang aan mensen met een dringende reden, zoals een scheiding of medische klachten. Toch blijft de vraag naar betaalbare woningen veel groter dan het aanbod, waardoor geduld voor veel woningzoekenden nog altijd noodzakelijk is."],"questions":[{"text":"Wat is een sociale huurwoning?","type":"Detail","options":["Een woning die je alleen kunt kopen","Een woning met een lage huur voor mensen met een beperkt inkomen","Een woning die alleen voor jongeren is","Een tijdelijke vakantiewoning"],"correct":1,"highlight":"Een sociale huurwoning is een woning met een lage huur, bedoeld voor mensen met een beperkt inkomen.","feedback":{"ok":"Goed! Zo wordt een sociale huurwoning omschreven.","nee":"Niet juist. Alinea 1 geeft de definitie van een sociale huurwoning."}},{"text":"Hoe lang duurt het gemiddeld in sommige steden voordat iemand een woning krijgt?","type":"Detail","options":["Minder dan een jaar","Ongeveer drie jaar","Meer dan tien jaar","Precies vijf jaar"],"correct":2,"highlight":"In sommige steden duurt het gemiddeld meer dan tien jaar voordat iemand een geschikte woning krijgt aangeboden.","feedback":{"ok":"Correct! In sommige steden duurt het gemiddeld meer dan tien jaar.","nee":"Niet correct. Alinea 2 noemt een gemiddelde wachttijd van meer dan tien jaar."}},{"text":"Waarom kiezen sommige gemeenten ervoor om meer dure woningen te bouwen?","type":"Inferentie","options":["Omdat dure woningen financieel aantrekkelijker zijn voor de gemeente","Omdat er te veel sociale huurwoningen zijn","Omdat jongeren dat liever willen","Omdat dure woningen sneller gebouwd worden"],"correct":0,"highlight":"omdat dit financieel aantrekkelijker is","feedback":{"ok":"Goed afgeleid! Financieel voordeel speelt hierbij een rol.","nee":"Niet helemaal. Alinea 3 noemt financieel voordeel als reden."}},{"text":"Wat betekent 'voorrang geven' in de tekst?","type":"Woordbetekenis","options":["Extra geld krijgen","Op een wachtlijst gezet worden","Een woning kopen in plaats van huren","Eerder aan de beurt komen dan anderen"],"correct":3,"highlight":"geven voorrang aan mensen met een dringende reden","feedback":{"ok":"Juist! Voorrang krijgen betekent eerder aan de beurt komen.","nee":"Niet juist. Alinea 4 gebruikt 'voorrang' in die betekenis."}},{"text":"Wat is de hoofdboodschap van deze tekst?","type":"Hoofdgedachte","options":["Wachtlijsten voor sociale huurwoningen zijn lang, door een tekort aan betaalbare woningen","Er zijn genoeg sociale huurwoningen voor iedereen","Alleen jongeren hebben moeite met wonen","Het wachtlijstprobleem is al opgelost"],"correct":0,"highlight":"de vraag naar betaalbare woningen veel groter dan het aanbod","feedback":{"ok":"Prima! Het tekort aan betaalbare woningen is de kern.","nee":"Niet helemaal. De tekst gaat over het tekort aan betaalbare woningen en lange wachtlijsten."}}]},{"topic":"Voedselbanken","title":"Voedselbanken: hulp voor wie het nodig heeft","paragraphs":["Een voedselbank is een organisatie die voedselpakketten geeft aan mensen die niet genoeg geld hebben om eten te kopen. In Nederland zijn er meer dan honderd voedselbanken, verspreid over het hele land. Mensen die gebruikmaken van een voedselbank hebben vaak te maken met schulden, werkloosheid of onverwachte tegenslagen. De voedselbank probeert hen tijdelijk te helpen, totdat hun financiële situatie verbetert.","Voedselbanken krijgen hun producten meestal van supermarkten, boeren en voedselfabrikanten. Deze bedrijven leveren voedsel dat nog goed is, maar dat ze zelf niet meer kunnen verkopen. Denk aan producten met een beschadigde verpakking of een korte houdbaarheidsdatum. Vrijwilligers sorteren dit voedsel en stellen er pakketten van samen. Zo wordt voedselverspilling tegengegaan en krijgen mensen die het nodig hebben toch gezonde maaltijden.","Niet iedereen kan zomaar een voedselpakket aanvragen. Voedselbanken hanteren strenge inkomensnormen om te bepalen wie in aanmerking komt voor hulp. Meestal moet iemand aantonen dat er na het betalen van vaste lasten nauwelijks geld overblijft om eten te kopen. Dit systeem zorgt ervoor dat de beperkte voorraad terechtkomt bij de mensen die de hulp het hardst nodig hebben.","De laatste jaren is het aantal mensen dat een voedselbank bezoekt gestegen, mede door hogere prijzen voor boodschappen en energie. Voedselbanken werken volledig met vrijwilligers en zijn afhankelijk van giften. Zonder deze steun van particulieren en bedrijven zouden de voedselbanken niet kunnen bestaan. Ondanks de groeiende vraag blijven voedselbanken proberen om iedereen die recht heeft op hulp, ook daadwerkelijk te bereiken."],"questions":[{"text":"Van wie krijgen voedselbanken meestal hun producten?","type":"Detail","options":["Van de overheid","Van andere voedselbanken","Van ziekenhuizen","Van supermarkten, boeren en voedselfabrikanten"],"correct":3,"highlight":"Voedselbanken krijgen hun producten meestal van supermarkten, boeren en voedselfabrikanten.","feedback":{"ok":"Goed! Supermarkten, boeren en fabrikanten leveren het voedsel.","nee":"Niet juist. Alinea 2 noemt de bronnen van het voedsel."}},{"text":"Waardoor is het aantal bezoekers van voedselbanken de laatste jaren gestegen?","type":"Detail","options":["Door minder vrijwilligers","Door strengere inkomensnormen","Door hogere prijzen voor boodschappen en energie","Door minder giften"],"correct":2,"highlight":"mede door hogere prijzen voor boodschappen en energie","feedback":{"ok":"Correct! Hogere prijzen zorgen voor meer bezoekers.","nee":"Niet correct. Alinea 4 noemt hogere prijzen als oorzaak."}},{"text":"Wat kun je concluderen over het voedsel dat voedselbanken van bedrijven krijgen?","type":"Inferentie","options":["Het is nog goed te eten, maar minder makkelijk verkoopbaar","Het is bedorven en niet meer eetbaar","Het is speciaal voor voedselbanken geproduceerd","Het is altijd duurder dan in de winkel"],"correct":0,"highlight":"Deze bedrijven leveren voedsel dat nog goed is, maar dat ze zelf niet meer kunnen verkopen.","feedback":{"ok":"Goed afgeleid! Het voedsel is nog eetbaar, maar lastig te verkopen.","nee":"Niet helemaal. Alinea 2 legt uit waarom bedrijven dit voedsel afstaan."}},{"text":"Wat betekent 'voedselverspilling'?","type":"Woordbetekenis","options":["Het kopen van te veel voedsel","Het bereiden van een maaltijd","Het weggooien van voedsel dat nog gegeten had kunnen worden","Het inzamelen van geld voor eten"],"correct":2,"highlight":"wordt voedselverspilling tegengegaan","feedback":{"ok":"Juist! Voedselverspilling betekent het weggooien van nog eetbaar voedsel.","nee":"Niet juist. Alinea 2 gebruikt het woord in die betekenis."}},{"text":"Wat is de hoofdboodschap van deze tekst?","type":"Hoofdgedachte","options":["Voedselbanken zijn niet meer nodig in Nederland","Iedereen kan zomaar een voedselpakket krijgen","Voedselbanken worden volledig door de overheid betaald","Voedselbanken helpen mensen in financiële nood met voedsel, dankzij vrijwilligers en giften"],"correct":3,"highlight":"Voedselbanken werken volledig met vrijwilligers en zijn afhankelijk van giften.","feedback":{"ok":"Prima! Vrijwilligers en giften maken de hulp mogelijk.","nee":"Niet helemaal. De tekst laat zien dat voedselbanken draaien op vrijwilligers en giften."}}]},{"topic":"Strand","title":"Het Nederlandse strand: een zomerse trekpleister","paragraphs":["Zodra de temperatuur in Nederland stijgt, trekken duizenden mensen naar het strand. Bekende stranden zoals Zandvoort en Scheveningen liggen dicht bij grote steden en zijn daardoor erg populair. Op warme dagen staan de parkeerplaatsen vol en liggen de handdoeken dicht naast elkaar op het zand. Voor veel Nederlanders is een dagje strand een vaste zomertraditie geworden, ook al is de Noordzee vaak kouder dan verwacht.","Het Nederlandse strand biedt meer dan alleen zon en zee. Langs de kust staan strandpaviljoens waar mensen kunnen eten, drinken en soms zelfs overnachten. Deze paviljoens organiseren regelmatig muziekavonden en andere activiteiten, vooral in het hoogseizoen. Daarnaast zijn er watersporten zoals surfen en suppen erg populair geworden. Wie niet van zwemmen houdt, kan ook gewoon wandelen langs de vloedlijn.","Toch heeft het drukke strandleven ook nadelen. Op de populairste dagen is het lastig om nog een rustig plekje te vinden, en zwerfafval blijft een probleem langs de kust. Strandbeheerders roepen bezoekers regelmatig op om hun afval mee te nemen. Ook waarschuwen reddingsbrigades voor gevaarlijke stromingen in de zee, vooral bij storm of harde wind, omdat zwemmers daardoor makkelijk in de problemen kunnen komen.","Ondanks de drukte en de risico's blijft het strand een geliefde bestemming. Steeds meer gemeenten investeren in schonere stranden en betere voorzieningen, zoals extra fietsenstallingen en toegankelijke paden voor mensen met een beperking. Voor veel Nederlanders hoort een bezoek aan zee onlosmakelijk bij de zomer, ongeacht het weer. Het strand blijft daardoor een plek waar mensen samenkomen om te ontspannen."],"questions":[{"text":"Welke twee stranden worden in de tekst als voorbeeld genoemd?","type":"Detail","options":["Texel en Terschelling","Egmond en Bergen","Zandvoort en Scheveningen","Katwijk en Noordwijk"],"correct":2,"highlight":"Bekende stranden zoals Zandvoort en Scheveningen liggen dicht bij grote steden","feedback":{"ok":"Goed! Zandvoort en Scheveningen worden genoemd als bekende stranden.","nee":"Niet juist. Alinea 1 noemt Zandvoort en Scheveningen."}},{"text":"Waar waarschuwen reddingsbrigades voor?","type":"Detail","options":["Te hoge temperaturen","Te veel kwallen","Volle parkeerplaatsen","Gevaarlijke stromingen in de zee"],"correct":3,"highlight":"waarschuwen reddingsbrigades voor gevaarlijke stromingen in de zee","feedback":{"ok":"Correct! Reddingsbrigades waarschuwen voor gevaarlijke stromingen.","nee":"Niet correct. Alinea 3 noemt gevaarlijke stromingen als waarschuwing."}},{"text":"Wat kun je afleiden uit het feit dat gemeenten investeren in extra voorzieningen bij het strand?","type":"Inferentie","options":["Gemeenten willen het strand toegankelijker en aantrekkelijker maken voor bezoekers","Het strand wordt minder populair","Er komen minder strandpaviljoens","Het zwemmen in zee wordt verboden"],"correct":0,"highlight":"investeren in schonere stranden en betere voorzieningen","feedback":{"ok":"Goed afgeleid! De investeringen maken het strand toegankelijker.","nee":"Niet helemaal. Alinea 4 beschrijft investeringen om het strand te verbeteren."}},{"text":"Wat betekent 'zwerfafval'?","type":"Woordbetekenis","options":["Afval dat wordt gerecycled in fabrieken","Speciaal afval van strandpaviljoens","Afval dat rondslingert in de natuur of op straat","Afval dat in zee drijft na een storm"],"correct":2,"highlight":"zwerfafval blijft een probleem langs de kust","feedback":{"ok":"Juist! Zwerfafval is afval dat rondslingert in de omgeving.","nee":"Niet juist. Alinea 3 gebruikt het woord in die betekenis."}},{"text":"Wat is de hoofdboodschap van deze tekst?","type":"Hoofdgedachte","options":["Het strand is alleen geschikt voor watersporters","Nederlanders gaan liever naar het buitenland op vakantie","Het Nederlandse strand is een populaire zomerbestemming, ondanks drukte en risico's","Strandpaviljoens zijn verboden in Nederland"],"correct":2,"highlight":"Het strand blijft daardoor een plek waar mensen samenkomen om te ontspannen.","feedback":{"ok":"Prima! Het strand blijft populair ondanks de nadelen.","nee":"Niet helemaal. De tekst laat zien dat het strand populair blijft, ondanks drukte en risico's."}}]},{"topic":"Fietsen","title":"De opmars van de elektrische fiets","paragraphs":["De elektrische fiets, ook wel e-bike genoemd, is de afgelopen jaren enorm populair geworden in Nederland. Een e-bike heeft een elektromotor die de trapbeweging ondersteunt, waardoor fietsen minder inspanning kost. Vooral op lange afstanden of bij harde wind maakt dit een groot verschil. Steeds meer mensen kiezen voor een e-bike, niet alleen ouderen, maar ook jongere forenzen die naar hun werk fietsen.","Een belangrijke reden voor de populariteit van de e-bike is het gemak waarmee grotere afstanden overbrugd kunnen worden. Waar mensen vroeger de auto pakten voor een rit van tien kilometer, stappen ze nu vaker op de e-bike. Dit is niet alleen goedkoper, maar ook beter voor het milieu. Werkgevers stimuleren dit soms door een fiscaal voordelige regeling aan te bieden voor werknemers die een e-bike aanschaffen.","Toch kleven er ook nadelen aan de opkomst van de e-bike. Doordat een e-bike zwaarder is en harder kan rijden dan een gewone fiets, ontstaan er vaker ernstige ongelukken. Vooral oudere fietsers blijken kwetsbaar, omdat een val met een e-bike harder aankomt. Verkeersdeskundigen pleiten daarom voor betere voorlichting over veilig fietsgedrag en voor bredere fietspaden die meer ruimte bieden aan alle verkeersdeelnemers.","Ondanks de risico's blijft de verwachting dat het aantal e-bikes de komende jaren verder zal groeien. Fabrikanten investeren in lichtere accu's en modellen die er minder uitzien als een typische e-bike. Ook gemeenten passen hun infrastructuur langzaam aan, met bijvoorbeeld meer oplaadpunten en speciale doorfietsroutes. De elektrische fiets lijkt daarmee een blijvend onderdeel te worden van het Nederlandse straatbeeld."],"questions":[{"text":"Wat doet de elektromotor van een e-bike?","type":"Detail","options":["Hij remt de fiets automatisch af","Hij navigeert automatisch naar een bestemming","Hij ondersteunt de trapbeweging","Hij laadt de telefoon van de fietser op"],"correct":2,"highlight":"Een e-bike heeft een elektromotor die de trapbeweging ondersteunt","feedback":{"ok":"Goed! De motor ondersteunt de trapbeweging.","nee":"Niet juist. Alinea 1 legt uit wat de elektromotor doet."}},{"text":"Wat bieden sommige werkgevers aan werknemers die een e-bike kopen?","type":"Detail","options":["Een gratis fiets","Extra vakantiedagen","Een parkeerplaats bij kantoor","Een fiscaal voordelige regeling"],"correct":3,"highlight":"een fiscaal voordelige regeling aan te bieden voor werknemers die een e-bike aanschaffen","feedback":{"ok":"Correct! Werkgevers bieden soms een fiscaal voordelige regeling.","nee":"Niet correct. Alinea 2 noemt deze regeling van werkgevers."}},{"text":"Waarom zijn oudere fietsers kwetsbaarder bij ongelukken met een e-bike?","type":"Inferentie","options":["Omdat een val met een zwaardere, snellere fiets harder aankomt","Omdat ze niet weten hoe een e-bike werkt","Omdat ze altijd zonder helm fietsen","Omdat e-bikes vaker kapot gaan"],"correct":0,"highlight":"een val met een e-bike harder aankomt","feedback":{"ok":"Goed afgeleid! Het gewicht en de snelheid maken een val harder.","nee":"Niet helemaal. Alinea 3 legt uit waarom ouderen kwetsbaarder zijn."}},{"text":"Wat is een 'doorfietsroute'?","type":"Woordbetekenis","options":["Een fietspad speciaal voor lange, snelle fietsritten tussen plaatsen","Een fietsenwinkel","Een verplichte fietsroute voor toeristen","Een fietspad alleen voor e-bikes"],"correct":0,"highlight":"meer oplaadpunten en speciale doorfietsroutes","feedback":{"ok":"Juist! Een doorfietsroute is bedoeld voor snelle, langere fietsritten.","nee":"Niet juist. Alinea 4 noemt doorfietsroutes als onderdeel van infrastructuur."}},{"text":"Wat is de hoofdboodschap van deze tekst?","type":"Hoofdgedachte","options":["E-bikes zijn te gevaarlijk en worden daarom verboden","De e-bike wordt steeds populairder, ondanks bepaalde veiligheidsrisico's","Alleen ouderen rijden op een e-bike","De e-bike vervangt binnenkort alle auto's"],"correct":1,"highlight":"De elektrische fiets lijkt daarmee een blijvend onderdeel te worden van het Nederlandse straatbeeld.","feedback":{"ok":"Prima! De e-bike groeit in populariteit, ondanks risico's.","nee":"Niet helemaal. De tekst laat zien dat de e-bike populairder wordt, ondanks veiligheidsrisico's."}}]},{"topic":"Bezorgapps","title":"Bezorgapps veranderen de manier waarop Nederlanders eten","paragraphs":["De afgelopen jaren is het bestellen van eten via een app enorm gegroeid in Nederland. Met een paar tikken op de telefoon kan iemand een maaltijd bestellen bij een restaurant in de buurt. Bekende bezorgapps verzamelen het aanbod van talloze restaurants op één platform, zodat gebruikers gemakkelijk kunnen vergelijken. Binnen een uur staat de besteller vaak al aan tafel, zonder zelf te hoeven koken.","Bezorgapps werken meestal met bezorgers die de bestelling met de fiets, scooter of auto naar de klant brengen. Sommige restaurants hebben eigen bezorgers, maar veel restaurants maken gebruik van bezorgers die door het platform zelf worden ingehuurd. Deze bezorgers krijgen betaald per bezorging, wat betekent dat hun inkomen kan schommelen. De groei van bezorgapps heeft daardoor ook een nieuwe groep werknemers gecreëerd.","Ondanks het gemak roepen bezorgapps ook kritiek op. Restaurants moeten vaak een flink percentage van elke bestelling afstaan aan het platform, waardoor hun winst daalt. Daarnaast wordt de arbeidspositie van bezorgers regelmatig bekritiseerd, omdat zij vaak als zelfstandige werken zonder vaste rechten zoals doorbetaling bij ziekte. Vakbonden pleiten al jaren voor betere arbeidsvoorwaarden voor mensen die voor deze platforms werken.","Toch blijft het aantal bestellingen via bezorgapps stijgen, vooral onder jongeren die gewend zijn geraakt aan het gemak van online bestellen. Steeds meer restaurants passen hun menu aan, zodat gerechten ook na bezorging nog goed smaken. Sommige experts verwachten dat bezorgapps in de toekomst nog meer diensten gaan aanbieden, zoals de bezorging van boodschappen. De manier waarop Nederlanders eten, verandert daardoor blijvend."],"questions":[{"text":"Hoe brengen bezorgers de bestelling meestal naar de klant?","type":"Detail","options":["Alleen te voet","Met het openbaar vervoer","Met een drone","Met de fiets, scooter of auto"],"correct":3,"highlight":"met de fiets, scooter of auto naar de klant brengen","feedback":{"ok":"Goed! Bezorgers gebruiken meestal de fiets, scooter of auto.","nee":"Niet juist. Alinea 2 noemt deze vervoersmiddelen."}},{"text":"Wat bekritiseren vakbonden aan het werk van bezorgers?","type":"Detail","options":["Ze werken vaak als zelfstandige zonder vaste rechten","Ze werken te weinig uren","Ze verdienen te veel geld","Ze mogen geen scooter gebruiken"],"correct":0,"highlight":"zij vaak als zelfstandige werken zonder vaste rechten zoals doorbetaling bij ziekte","feedback":{"ok":"Correct! Vakbonden bekritiseren het gebrek aan vaste rechten.","nee":"Niet correct. Alinea 3 beschrijft deze kritiek van vakbonden."}},{"text":"Wat kun je afleiden over de winst van restaurants die met bezorgapps werken?","type":"Inferentie","options":["Hun winst stijgt altijd flink door bezorgapps","Hun winst kan lager uitvallen doordat het platform een percentage afneemt","Restaurants verdienen niets meer aan eten","Restaurants stoppen met bezorgen"],"correct":1,"highlight":"moeten vaak een flink percentage van elke bestelling afstaan aan het platform, waardoor hun winst daalt","feedback":{"ok":"Goed afgeleid! Het percentage voor het platform drukt op de winst.","nee":"Niet helemaal. Alinea 3 legt uit waarom de winst van restaurants kan dalen."}},{"text":"Wat betekent 'schommelen' in de tekst?","type":"Woordbetekenis","options":["Constant hetzelfde blijven","Op en neer bewegen aan een touw","Wisselen tussen hoger en lager worden","Snel stijgen zonder te dalen"],"correct":2,"highlight":"wat betekent dat hun inkomen kan schommelen","feedback":{"ok":"Juist! Schommelen betekent wisselen tussen hoger en lager.","nee":"Niet juist. Alinea 2 gebruikt 'schommelen' in die betekenis."}},{"text":"Wat is de hoofdboodschap van deze tekst?","type":"Hoofdgedachte","options":["Bezorgapps hebben het bestellen van eten makkelijker gemaakt, maar brengen ook kritiek met zich mee","Bezorgapps zijn alleen populair bij restaurants","Bezorgapps gaan binnenkort verdwijnen","Alleen jongeren gebruiken bezorgapps"],"correct":0,"highlight":"De manier waarop Nederlanders eten, verandert daardoor blijvend.","feedback":{"ok":"Prima! Bezorgapps maken bestellen makkelijker, ondanks kritiek.","nee":"Niet helemaal. De tekst laat zowel het gemak als de kritiek op bezorgapps zien."}}]},{"topic":"Film","title":"De Nederlandse filmindustrie en de Gouden Kalf","paragraphs":["De Nederlandse filmindustrie is relatief klein vergeleken met bijvoorbeeld Hollywood, maar produceert elk jaar tientallen speelfilms, documentaires en korte films. Veel Nederlandse films gaan over herkenbare thema's uit het dagelijks leven, zoals familie, liefde of maatschappelijke problemen. Sommige Nederlandse films trekken honderdduizenden bezoekers naar de bioscoop, terwijl andere vooral op filmfestivals te zien zijn.","Het belangrijkste Nederlandse filmfestival is het Nederlands Film Festival, dat jaarlijks in Utrecht plaatsvindt. Tijdens dit festival worden de beste Nederlandse films van het afgelopen jaar getoond aan het publiek. Het festival duurt ongeveer tien dagen en trekt zowel filmliefhebbers als mensen uit de filmindustrie. Aan het einde van het festival wordt bekend wie de belangrijkste prijzen wint.","De belangrijkste Nederlandse filmprijs heet de Gouden Kalf. Deze prijs wordt uitgereikt in verschillende categorieën, zoals beste film, beste regisseur en beste acteur. Een Gouden Kalf winnen wordt gezien als een grote eer binnen de Nederlandse filmwereld en kan de carrière van filmmakers een flinke impuls geven. De prijs wordt sinds de jaren zeventig van de vorige eeuw uitgereikt tijdens het Nederlands Film Festival.","Ondanks de kwaliteit van Nederlandse films is het voor filmmakers vaak lastig om voldoende geld te vinden voor nieuwe producties. Subsidies van de overheid en het Filmfonds spelen daarom een belangrijke rol bij het financieren van films. Zonder deze steun zouden veel kleinere, artistieke films waarschijnlijk niet gemaakt kunnen worden. De Gouden Kalf blijft ondertussen een belangrijk symbool van waardering voor Nederlands filmtalent."],"questions":[{"text":"Waar vindt het Nederlands Film Festival jaarlijks plaats?","type":"Detail","options":["Amsterdam","Rotterdam","Utrecht","Den Haag"],"correct":2,"highlight":"dat jaarlijks in Utrecht plaatsvindt","feedback":{"ok":"Goed! Het festival vindt jaarlijks in Utrecht plaats.","nee":"Niet juist. Alinea 2 noemt Utrecht als locatie."}},{"text":"Hoe heet de belangrijkste Nederlandse filmprijs?","type":"Detail","options":["De Zilveren Leeuw","De Gouden Kalf","De Nederlandse Oscar","De Filmprijs Nederland"],"correct":1,"highlight":"De belangrijkste Nederlandse filmprijs heet de Gouden Kalf.","feedback":{"ok":"Correct! De Gouden Kalf is de belangrijkste filmprijs.","nee":"Niet correct. Alinea 3 noemt de Gouden Kalf."}},{"text":"Waarom zijn subsidies van de overheid belangrijk voor de Nederlandse filmindustrie?","type":"Inferentie","options":["Omdat zonder deze steun veel kleinere, artistieke films niet gemaakt zouden kunnen worden","Omdat bioscopen anders zouden sluiten","Omdat acteurs anders geen salaris krijgen","Omdat het Nederlands Film Festival anders niet zou bestaan"],"correct":0,"highlight":"Zonder deze steun zouden veel kleinere, artistieke films waarschijnlijk niet gemaakt kunnen worden.","feedback":{"ok":"Goed afgeleid! Subsidies maken kleinere films mogelijk.","nee":"Niet helemaal. Alinea 4 legt uit waarom subsidies belangrijk zijn."}},{"text":"Wat betekent 'een impuls geven' in de tekst?","type":"Woordbetekenis","options":["Iets vertragen of tegenhouden","Iets volledig veranderen","Iets beëindigen","Iets een positieve stimulans of duw in de goede richting geven"],"correct":3,"highlight":"kan de carrière van filmmakers een flinke impuls geven","feedback":{"ok":"Juist! Een impuls geven betekent een positieve stimulans geven.","nee":"Niet juist. Alinea 3 gebruikt de uitdrukking in die betekenis."}},{"text":"Wat is de hoofdboodschap van deze tekst?","type":"Hoofdgedachte","options":["De Nederlandse filmindustrie is groter dan Hollywood","De Gouden Kalf is een onbelangrijke prijs","De Nederlandse filmindustrie is klein maar actief, met de Gouden Kalf als hoogste onderscheiding","Nederlandse films worden nooit gesubsidieerd"],"correct":2,"highlight":"De Gouden Kalf blijft ondertussen een belangrijk symbool van waardering voor Nederlands filmtalent.","feedback":{"ok":"Prima! De Gouden Kalf is het hoogtepunt van de Nederlandse filmwereld.","nee":"Niet helemaal. De tekst laat zien dat de Nederlandse filmindustrie klein maar actief is, met de Gouden Kalf als belangrijkste prijs."}}]},{"topic":"Landbouw","title":"Groente uit de kas: de Nederlandse glastuinbouw","paragraphs":["Nederland is een klein land, maar toch is het een van de grootste exporteurs van groente ter wereld. Dat komt door de glastuinbouw. In grote kassen, vooral in het gebied rond Westland, telen boeren tomaten, paprika's en komkommers. Deze kassen zorgen ervoor dat groente het hele jaar door kan groeien, ook als het buiten koud of donker is.","In een moderne kas regelen computers bijna alles. Sensoren meten de temperatuur, de luchtvochtigheid en de hoeveelheid licht. Als het buiten te koud is, wordt de kas verwarmd. Als de planten meer licht nodig hebben, gaan er speciale lampen aan. Zo krijgen de planten precies wat ze nodig hebben, op elk moment van de dag.","Glastuinbouw heeft grote voordelen. Doordat het water in de kas wordt hergebruikt, is er veel minder water nodig dan bij gewone landbouw. Ook groeien de planten dichter bij elkaar, waardoor er meer groente per vierkante meter wordt geoogst. Bovendien gebruiken telers minder gif tegen ziektes, omdat ze insecten inzetten die schadelijke beestjes opeten.","De Nederlandse glastuinbouw is wereldwijd bekend en Nederlandse kennis over kassen wordt naar veel andere landen geëxporteerd. Toch staat de sector ook voor uitdagingen. Het verwarmen van kassen kost veel energie, en telers zoeken naar duurzamere manieren om dat te doen, bijvoorbeeld met warmte uit de grond. Zo blijft de sector zich vernieuwen."],"questions":[{"text":"In welk gebied liggen veel Nederlandse kassen?","type":"Detail","options":["Westland","Flevoland","Zeeland","Limburg"],"correct":0,"highlight":"vooral in het gebied rond Westland","feedback":{"ok":"Klopt! Veel kassen staan in het Westland.","nee":"Niet juist. Alinea 1 noemt het Westland als kassengebied."}},{"text":"Wat meten de sensoren in een moderne kas?","type":"Detail","options":["Alleen de prijs van de groente.","De temperatuur, de luchtvochtigheid en het licht.","Het aantal bezoekers.","De grootte van de tomaten."],"correct":1,"highlight":"Sensoren meten de temperatuur, de luchtvochtigheid en de hoeveelheid licht","feedback":{"ok":"Goed! Sensoren meten temperatuur, luchtvochtigheid en licht.","nee":"Niet correct. Alinea 2 noemt temperatuur, luchtvochtigheid en licht."}},{"text":"Wat kun je afleiden over de toekomstplannen van telers rond energie?","type":"Inferentie","options":["Ze willen stoppen met het verwarmen van kassen.","Ze zoeken naar duurzamere manieren om kassen te verwarmen.","Ze gebruiken geen kassen meer.","Ze verhuizen naar landen zonder winter."],"correct":1,"highlight":"telers zoeken naar duurzamere manieren om dat te doen","feedback":{"ok":"Precies! Telers zoeken naar duurzamere verwarming.","nee":"Niet helemaal. Alinea 4 zegt dat telers duurzamere manieren zoeken."}},{"text":"Wat betekent 'hergebruikt' in de tekst?","type":"Woordbetekenis","options":["Voor de eerste keer gebruikt.","Weggegooid na gebruik.","Opnieuw gebruikt in plaats van weggegooid.","Verkocht aan andere boeren."],"correct":2,"highlight":"het water in de kas wordt hergebruikt","feedback":{"ok":"Juist! Hergebruikt betekent opnieuw gebruikt.","nee":"Niet juist. Alinea 3 gebruikt 'hergebruikt' voor water dat opnieuw wordt ingezet."}},{"text":"Wat is de hoofdboodschap van deze tekst?","type":"Hoofdgedachte","options":["Glastuinbouw is schadelijk voor het milieu.","Dankzij slimme kassen kan Nederland veel groente produceren en exporteren.","Groente kan alleen in de zomer groeien.","Kassen worden niet meer gebruikt in Nederland."],"correct":1,"highlight":"een van de grootste exporteurs van groente ter wereld","feedback":{"ok":"Precies! Dat is de kern van de tekst.","nee":"Niet helemaal. De tekst gaat over hoe Nederland dankzij kassen veel groente exporteert."}}]},{"topic":"Geschiedenis","title":"Waterschappen: al eeuwenlang de baas over het water","paragraphs":["Nederland ligt voor een groot deel onder de zeespiegel. Zonder goede bescherming tegen water zou het land vaak overstromen. Daarom bestaan er al eeuwen waterschappen. Dit zijn organisaties die zorgen voor dijken, sloten en gemalen. De allereerste waterschappen ontstonden al in de middeleeuwen, toen boeren samen dijken bouwden om hun land te beschermen tegen de zee en de rivieren.","In het begin waren waterschappen kleine, lokale organisaties. Dorpen en boeren regelden zelf de dijken rond hun eigen land. Er was nog geen centrale overheid die alles regelde. Mensen die in hetzelfde gebied woonden, moesten samenwerken, want een dijk was alleen sterk als iedereen zijn deel goed onderhield. Wie zijn stuk dijk verwaarloosde, bracht het hele gebied in gevaar.","Later werden de waterschappen groter en beter georganiseerd. Ze kregen eigen bestuurders en regels, en mochten zelfs belasting heffen om dijken en gemalen te betalen. Waterschappen zijn hierdoor een van de oudste vormen van bestuur in Nederland. Zelfs vandaag de dag bestaan waterschappen nog steeds. Ze zorgen voor schoon water, sterke dijken en het op peil houden van sloten en rivieren.","Nederlanders kiezen om de paar jaar hun eigen vertegenwoordigers voor het waterschap, net zoals ze stemmen voor de gemeente of het land. Veel mensen weten niet precies wat een waterschap doet, terwijl het werk erg belangrijk is. Zonder waterschappen zou een groot deel van Nederland regelmatig blank komen te staan. De strijd tegen het water is dus nog steeds actueel."],"questions":[{"text":"Wanneer ontstonden de eerste waterschappen?","type":"Detail","options":["In de middeleeuwen","In de twintigste eeuw","Na de Tweede Wereldoorlog","In de Romeinse tijd"],"correct":0,"highlight":"ontstonden al in de middeleeuwen","feedback":{"ok":"Goed! De eerste waterschappen ontstonden in de middeleeuwen.","nee":"Niet juist. Alinea 1 noemt de middeleeuwen."}},{"text":"Wat mochten waterschappen later doen om dijken te betalen?","type":"Detail","options":["Geld lenen van andere landen","Grond verkopen aan boeren","Belasting heffen","Subsidie vragen aan de kerk"],"correct":2,"highlight":"mochten zelfs belasting heffen om dijken en gemalen te betalen","feedback":{"ok":"Klopt! Waterschappen mochten belasting heffen.","nee":"Niet correct. Alinea 3 zegt dat waterschappen belasting mochten heffen."}},{"text":"Wat kun je afleiden over waarom mensen vroeger goed moesten samenwerken?","type":"Inferentie","options":["Omdat de overheid hen daartoe verplichtte met boetes","Omdat ze anders geen belasting hoefden te betalen","Omdat boeren elkaar niet vertrouwden","Omdat een dijk alleen sterk was als iedereen zijn deel goed onderhield"],"correct":3,"highlight":"een dijk was alleen sterk als iedereen zijn deel goed onderhield","feedback":{"ok":"Juist! Iedereen moest zijn deel van de dijk goed onderhouden.","nee":"Niet helemaal. Alinea 2 legt uit dat een dijk alleen sterk was als iedereen zijn deel onderhield."}},{"text":"Wat betekent 'gemalen' in de tekst?","type":"Woordbetekenis","options":["Oude molens die graan malen tot meel","Kleine bruggen over sloten","Machines die water wegpompen naar een ander niveau","Ambtenaren die dijken controleren"],"correct":2,"highlight":"dijken, sloten en gemalen","feedback":{"ok":"Correct! Gemalen pompen water weg.","nee":"Niet juist. Alinea 1 noemt gemalen als onderdeel van waterbeheer."}},{"text":"Wat is de hoofdboodschap van deze tekst?","type":"Hoofdgedachte","options":["Waterschappen bestaan niet meer in Nederland","Nederland ligt boven de zeespiegel","Alleen de overheid bepaalt wat er met dijken gebeurt","Waterschappen zijn al eeuwenlang belangrijk voor de bescherming tegen water"],"correct":3,"highlight":"De strijd tegen het water is dus nog steeds actueel","feedback":{"ok":"Precies! Waterschappen zijn al eeuwenlang belangrijk.","nee":"Niet helemaal. Alinea 4 benadrukt dat de strijd tegen het water nog steeds actueel is."}}]},{"topic":"Sport","title":"Oranje gekte: voetbal in het hart van Nederland","paragraphs":["Voetbal is de populairste sport van Nederland. Bijna elk dorp en elke stad heeft wel een eigen voetbalclub, en miljoenen Nederlanders spelen zelf in het weekend een wedstrijd. Het Nederlands elftal, ook wel Oranje genoemd, is het nationale team en trekt bij grote toernooien de aandacht van bijna het hele land. Straten en huizen worden dan versierd met oranje vlaggen en shirts.","Nederland heeft een lange voetbalgeschiedenis. In de jaren zeventig werd het land wereldberoemd door het zogenoemde 'totaalvoetbal', een speelstijl waarbij spelers voortdurend van positie wisselden. Spelers zoals Johan Cruijff speelden hierin een grote rol en worden nog steeds gezien als voetballegendes. Hoewel Nederland nooit het WK heeft gewonnen, bereikte het elftal wel meerdere keren de finale.","Naast het Nederlands elftal is ook het clubvoetbal populair. Clubs zoals Ajax, PSV en Feyenoord hebben een grote groep fans en een rijke geschiedenis, met successen in Europese toernooien. Veel Nederlandse voetballers beginnen hun carrière bij een jeugdopleiding van zo'n club en vertrekken later naar grote competities in het buitenland, zoals Engeland, Spanje of Italië.","Voetbal verbindt mensen in Nederland, ongeacht leeftijd, achtergrond of woonplaats. Tijdens interlands zitten mensen samen voor de televisie, in kroegen of op pleinen om de wedstrijd te volgen. Voor veel Nederlanders is voetbal niet zomaar een spel, maar een gedeelde ervaring die mensen dichter bij elkaar brengt. Zo blijft voetbal een belangrijk onderdeel van de Nederlandse cultuur."],"questions":[{"text":"Hoe wordt het Nederlands elftal ook wel genoemd?","type":"Detail","options":["De Leeuwen","Oranje","De Vliegende Hollanders","Het Gouden Elftal"],"correct":1,"highlight":"ook wel Oranje genoemd","feedback":{"ok":"Klopt! Oranje is de bijnaam van het Nederlands elftal.","nee":"Niet juist. Alinea 1 noemt de naam Oranje."}},{"text":"In welk decennium werd Nederland beroemd door het totaalvoetbal?","type":"Detail","options":["jaren negentig","jaren tachtig","jaren zeventig","jaren zestig"],"correct":2,"highlight":"In de jaren zeventig werd het land wereldberoemd","feedback":{"ok":"Goed! In de jaren zeventig werd Nederland beroemd door totaalvoetbal.","nee":"Niet correct. Alinea 2 noemt de jaren zeventig."}},{"text":"Wat kun je afleiden uit het feit dat Nederlandse voetballers vaak naar het buitenland vertrekken?","type":"Inferentie","options":["Nederlandse clubs bieden geen talentontwikkeling","Buitenlandse clubs hebben geen eigen jeugdspelers","Nederlandse voetballers spreken geen andere talen","Nederlandse jeugdopleidingen leveren spelers op die interessant zijn voor grote buitenlandse competities"],"correct":3,"highlight":"vertrekken later naar grote competities in het buitenland","feedback":{"ok":"Juist! Jeugdopleidingen leveren interessante spelers op.","nee":"Niet helemaal. Alinea 3 zegt dat spelers vertrekken naar grote buitenlandse competities."}},{"text":"Wat betekent 'interlands' in de tekst?","type":"Woordbetekenis","options":["Wedstrijden tussen clubs uit dezelfde stad","Trainingen van de jeugdopleiding","Voetbalvelden in het buitenland","Wedstrijden van het nationale team tegen andere landen"],"correct":3,"highlight":"Tijdens interlands zitten mensen samen","feedback":{"ok":"Correct! Interlands zijn wedstrijden van het nationale team.","nee":"Niet juist. Alinea 4 gebruikt 'interlands' voor wedstrijden van het nationale team."}},{"text":"Wat is de hoofdboodschap van deze tekst?","type":"Hoofdgedachte","options":["Voetbal is in Nederland alleen populair bij jongeren","Nederland heeft nooit een belangrijk toernooi gehaald","Voetbal speelt een grote, verbindende rol in de Nederlandse cultuur","Alleen clubvoetbal is populair in Nederland"],"correct":2,"highlight":"voetbal een belangrijk onderdeel van de Nederlandse cultuur","feedback":{"ok":"Precies! Voetbal verbindt mensen in Nederland.","nee":"Niet helemaal. Alinea 4 benadrukt de verbindende rol van voetbal."}}]},{"topic":"Cultuur","title":"Van Suske en Wiske tot moderne strips: de Nederlandse striptraditie","paragraphs":["Stripverhalen zijn al meer dan honderd jaar populair in Nederland. Bekende personages zoals Suske en Wiske, Douwe Dabbert en Sjors en Sjimmie groeiden uit tot klassiekers waar meerdere generaties mee zijn opgegroeid. Strips verschenen vaak eerst in kranten of tijdschriften, voordat ze werden gebundeld in aparte stripboeken. Kinderen wachtten soms een hele week op het volgende deel van hun favoriete verhaal.","Een van de bekendste Nederlandse stripfiguren is Tom Poes, bedacht door tekenaar Marten Toonder. De verhalen rond Tom Poes en zijn vriend heer Bommel zitten vol humor, maar bevatten ook slimme commentaren op de maatschappij. Marten Toonder introduceerde bovendien tientallen nieuwe Nederlandse woorden en uitdrukkingen, waarvan er veel nog steeds gebruikt worden in de dagelijkse taal.","Niet alle Nederlandse strips zijn voor kinderen bedoeld. Er bestaat ook een rijke traditie van strips voor volwassenen, met complexere verhalen en tekenstijlen. Deze strips behandelen soms serieuze onderwerpen, zoals oorlog, politiek of persoonlijke problemen. Stripmakers gebruiken tekeningen en tekst samen om verhalen te vertellen die op een unieke manier emoties en ideeën overbrengen.","Tegenwoordig verschijnen Nederlandse strips niet meer alleen op papier. Veel makers publiceren hun werk online, bijvoorbeeld als webstrip, en bereiken zo een nieuw en vaak jonger publiek. Toch blijft er ook waardering voor de klassieke personages van vroeger. Musea en tentoonstellingen wijden regelmatig aandacht aan de geschiedenis van de Nederlandse strip, als eerbetoon aan deze bijzondere kunstvorm."],"questions":[{"text":"Wie bedacht Tom Poes?","type":"Detail","options":["Marten Toonder","Willy Vandersteen","Piet Wijn","Hanco Kolk"],"correct":0,"highlight":"bedacht door tekenaar Marten Toonder","feedback":{"ok":"Goed! Marten Toonder bedacht Tom Poes.","nee":"Niet juist. Alinea 2 noemt Marten Toonder als bedenker."}},{"text":"Waar verschenen strips vaak voordat ze in stripboeken werden gebundeld?","type":"Detail","options":["Op televisie","In kranten of tijdschriften","Op posters","In schoolboeken"],"correct":1,"highlight":"verschenen vaak eerst in kranten of tijdschriften","feedback":{"ok":"Klopt! Strips verschenen eerst in kranten of tijdschriften.","nee":"Niet correct. Alinea 1 noemt kranten en tijdschriften."}},{"text":"Wat kun je afleiden over de invloed van Marten Toonder op de Nederlandse taal?","type":"Inferentie","options":["Zijn verhalen werden nooit gelezen","Hij schreef alleen in het Engels","Zijn woorden zijn allemaal weer verdwenen","Zijn woorden worden nog steeds gebruikt in het dagelijks taalgebruik"],"correct":3,"highlight":"waarvan er veel nog steeds gebruikt worden in de dagelijkse taal","feedback":{"ok":"Juist! Zijn woorden worden nog steeds gebruikt.","nee":"Niet helemaal. Alinea 2 zegt dat zijn woorden nog steeds gebruikt worden."}},{"text":"Wat is een webstrip volgens de tekst?","type":"Woordbetekenis","options":["Een strip die alleen op papier verschijnt","Een strip die online wordt gepubliceerd","Een strip zonder tekeningen","Een strip die alleen in musea te zien is"],"correct":1,"highlight":"publiceren hun werk online, bijvoorbeeld als webstrip","feedback":{"ok":"Correct! Een webstrip verschijnt online.","nee":"Niet juist. Alinea 4 legt uit dat een webstrip online wordt gepubliceerd."}},{"text":"Wat is de hoofdboodschap van deze tekst?","type":"Hoofdgedachte","options":["Nederlandse strips zijn alleen voor kinderen","Strips zijn in Nederland niet populair","Nederlandse strips vormen een rijke en veelzijdige traditie die zich blijft ontwikkelen","Alleen klassieke strips zijn de moeite waard"],"correct":2,"highlight":"Musea en tentoonstellingen wijden regelmatig aandacht aan de geschiedenis van de Nederlandse strip","feedback":{"ok":"Precies! Nederlandse strips zijn rijk en veelzijdig.","nee":"Niet helemaal. Alinea 4 laat zien hoe veelzijdig de Nederlandse striptraditie is."}}]},{"topic":"Ruimtevaart","title":"Nederlanders in de ruimte: van astronaut tot ruimteonderzoek","paragraphs":["Nederland is een klein land, maar heeft toch een aantal astronauten voortgebracht. De bekendste is Wubbo Ockels, die in 1985 als eerste Nederlander de ruimte in ging met een Amerikaanse spaceshuttle. Zijn vlucht duurde een week en bestond uit talloze wetenschappelijke experimenten. Ockels werd na zijn terugkeer een bekend gezicht in Nederland en bleef zich inzetten voor wetenschap en duurzaamheid.","Jaren later volgde André Kuipers, die zelfs twee keer naar de ruimte reisde. Tijdens zijn tweede missie verbleef hij bijna een half jaar op het internationale ruimtestation ISS. Daar voerde hij honderden experimenten uit, onder andere over hoe het menselijk lichaam reageert op gewichtloosheid. Kuipers deelde tijdens zijn missie ook regelmatig foto's en verhalen met scholen in Nederland.","Nederlandse kennis en techniek spelen ook een grotere rol in de ruimtevaart dan veel mensen denken. Nederlandse bedrijven en universiteiten ontwikkelen bijvoorbeeld instrumenten voor satellieten en telescopen, die worden gebruikt om het klimaat te bestuderen of ver weg gelegen sterren te onderzoeken. Ook de Europese ruimtevaartorganisatie ESA heeft een belangrijk kantoor in Noordwijk, aan de Nederlandse kust.","De belangstelling voor ruimtevaart in Nederland blijft groeien. Scholen besteden steeds vaker aandacht aan sterrenkunde en techniek, mede geïnspireerd door de bekende Nederlandse astronauten. Ruimtevaart laat zien dat een klein land toch een grote bijdrage kan leveren aan internationale wetenschap. Voor veel jonge Nederlanders is een carrière in de ruimtevaart niet langer een onbereikbare droom."],"questions":[{"text":"Wie was de eerste Nederlandse astronaut in de ruimte?","type":"Detail","options":["André Kuipers","Wubbo Ockels","Piet Hein","Frank de Winne"],"correct":1,"highlight":"Wubbo Ockels, die in 1985 als eerste Nederlander de ruimte in ging","feedback":{"ok":"Klopt! Wubbo Ockels was de eerste Nederlandse astronaut.","nee":"Niet juist. Alinea 1 noemt Wubbo Ockels."}},{"text":"Hoe lang verbleef André Kuipers tijdens zijn tweede missie op het ISS?","type":"Detail","options":["Een week","Een maand","Bijna een half jaar","Twee jaar"],"correct":2,"highlight":"verbleef hij bijna een half jaar op het internationale ruimtestation ISS","feedback":{"ok":"Goed! Kuipers verbleef bijna een half jaar op het ISS.","nee":"Niet correct. Alinea 2 noemt bijna een half jaar."}},{"text":"Wat kun je afleiden over de rol van Nederland in de ruimtevaart?","type":"Inferentie","options":["Nederland speelt geen enkele rol in de ruimtevaart","Nederland bouwt zelf raketten voor bemande missies","Nederland heeft alleen interesse in ruimtevaart via het onderwijs","Nederland levert ondanks zijn kleine omvang een belangrijke bijdrage aan ruimteonderzoek"],"correct":3,"highlight":"een klein land toch een grote bijdrage kan leveren aan internationale wetenschap","feedback":{"ok":"Juist! Nederland levert een belangrijke bijdrage aan ruimteonderzoek.","nee":"Niet helemaal. Alinea 4 zegt dat een klein land een grote bijdrage kan leveren."}},{"text":"Wat betekent 'gewichtloosheid' in de tekst?","type":"Woordbetekenis","options":["Een toestand waarin er geen zwaartekracht voelbaar is","Een soort ruimtevoedsel","Het gewicht van de ruimteraket","Een ziekte die astronauten kunnen krijgen"],"correct":0,"highlight":"hoe het menselijk lichaam reageert op gewichtloosheid","feedback":{"ok":"Correct! Gewichtloosheid betekent geen zwaartekracht voelen.","nee":"Niet juist. Alinea 2 gebruikt 'gewichtloosheid' voor het ontbreken van zwaartekracht."}},{"text":"Wat is de hoofdboodschap van deze tekst?","type":"Hoofdgedachte","options":["Nederland heeft nog nooit een astronaut gehad","Ruimtevaart is niet interessant voor Nederlandse scholieren","ESA heeft geen banden met Nederland","Ondanks zijn kleine omvang levert Nederland een belangrijke bijdrage aan de ruimtevaart"],"correct":3,"highlight":"Ruimtevaart laat zien dat een klein land toch een grote bijdrage kan leveren aan internationale wetenschap","feedback":{"ok":"Precies! Nederland draagt ondanks zijn omvang veel bij.","nee":"Niet helemaal. Alinea 4 benadrukt de grote bijdrage van een klein land."}}]},{"topic":"Milieu","title":"Afval scheiden: waarom het loont om te sorteren","paragraphs":["In Nederland moeten huishoudens hun afval scheiden in verschillende soorten, zoals plastic, papier, glas en gft (groente-, fruit- en tuinafval). Dit gebeurt omdat gescheiden afval veel makkelijker te hergebruiken is dan een mengsel van alles door elkaar. Gemeenten geven vaak aparte containers of zakken voor elk type afval, zodat inwoners hun afval thuis al kunnen sorteren.","Wanneer afval goed gescheiden is, kan het worden verwerkt tot nieuwe grondstoffen. Oud papier wordt bijvoorbeeld weer papier, en plastic flessen kunnen worden omgesmolten tot nieuwe plastic producten. Gft-afval wordt vaak gecomposteerd of gebruikt om biogas te maken. Als afval niet gescheiden is, moet het vaak worden verbrand, en dan gaan waardevolle grondstoffen definitief verloren.","Afval scheiden heeft dus voordelen voor het milieu, maar ook voor de portemonnee. Sommige gemeenten rekenen minder afvalstoffenheffing aan huishoudens die goed scheiden, of laten inwoners betalen per hoeveelheid restafval. Zo worden mensen gestimuleerd om bewuster om te gaan met wat ze weggooien. Bovendien kost het recyclen van grondstoffen vaak minder energie dan het maken van nieuwe materialen.","Toch blijft afval scheiden voor sommige mensen lastig of onduidelijk. Niet iedereen weet precies in welke bak welk soort afval hoort, en regels verschillen soms per gemeente. Veel gemeenten bieden daarom informatie en apps aan om inwoners te helpen bij het sorteren. Hoe beter mensen hun afval scheiden, hoe minder grondstoffen en energie verloren gaan."],"questions":[{"text":"In welke soorten moeten Nederlandse huishoudens hun afval scheiden?","type":"Detail","options":["Alleen plastic en papier","Alleen restafval","Plastic, papier, glas en gft","Alleen glas"],"correct":2,"highlight":"scheiden in verschillende soorten, zoals plastic, papier, glas en gft","feedback":{"ok":"Goed! Afval wordt gescheiden in plastic, papier, glas en gft.","nee":"Niet juist. Alinea 1 noemt plastic, papier, glas en gft."}},{"text":"Wat gebeurt er met afval dat niet gescheiden is?","type":"Detail","options":["Het wordt automatisch gerecycled","Het moet vaak worden verbrand","Het wordt gratis opgehaald","Het wordt naar het buitenland gestuurd"],"correct":1,"highlight":"moet het vaak worden verbrand","feedback":{"ok":"Klopt! Niet-gescheiden afval wordt vaak verbrand.","nee":"Niet correct. Alinea 2 zegt dat het vaak verbrand wordt."}},{"text":"Waarom rekenen sommige gemeenten minder afvalstoffenheffing aan huishoudens die goed scheiden?","type":"Inferentie","options":["Om mensen te stimuleren bewuster met afval om te gaan","Omdat scheiden verplicht is bij wet","Omdat gescheiden afval niets kost om te verwerken","Om inwoners te straffen die niet scheiden"],"correct":0,"highlight":"worden mensen gestimuleerd om bewuster om te gaan met wat ze weggooien","feedback":{"ok":"Juist! Zo worden mensen gestimuleerd om bewuster te scheiden.","nee":"Niet helemaal. Alinea 3 legt uit dat dit mensen stimuleert."}},{"text":"Wat betekent 'gft' in de tekst?","type":"Woordbetekenis","options":["Glas, flessen en textiel","Gerecycled fabrieksafval","Grof en fijn tuinafval","Groente-, fruit- en tuinafval"],"correct":3,"highlight":"gft (groente-, fruit- en tuinafval)","feedback":{"ok":"Correct! Gft staat voor groente-, fruit- en tuinafval.","nee":"Niet juist. Alinea 1 legt uit wat gft betekent."}},{"text":"Wat is de hoofdboodschap van deze tekst?","type":"Hoofdgedachte","options":["Afval scheiden heeft geen enkel nut","Alleen gemeenten zijn verantwoordelijk voor afval scheiden","Recyclen kost altijd meer energie dan nieuwe materialen maken","Afval scheiden helpt om grondstoffen te besparen en is goed voor milieu en portemonnee"],"correct":3,"highlight":"Afval scheiden heeft dus voordelen voor het milieu, maar ook voor de portemonnee","feedback":{"ok":"Precies! Scheiden bespaart grondstoffen en geld.","nee":"Niet helemaal. Alinea 3 benadrukt de voordelen voor milieu en portemonnee."}}]},{"topic":"Taal","title":"Het Nederlands ver van huis: Suriname en Afrikaans","paragraphs":["Het Nederlands wordt niet alleen gesproken in Nederland en België, maar ook ver daarbuiten. In Suriname, een land in Zuid-Amerika, is Nederlands de officiële taal. Dat komt doordat Suriname eeuwenlang een Nederlandse kolonie was. Hoewel de meeste Surinamers thuis ook andere talen spreken, zoals Sranantongo, wordt Nederlands gebruikt op school, bij de overheid en in de media.","Ook in Zuid-Afrika en Namibië hoor je nog sporen van het Nederlands terug, in de taal Afrikaans. Afrikaans ontstond uit het Nederlands dat Nederlandse kolonisten vanaf de zeventiende eeuw meenamen naar Zuid-Afrika. Door de jaren heen veranderde deze taal geleidelijk, onder invloed van andere talen in het gebied, tot een aparte taal die vandaag de dag miljoenen sprekers heeft.","Nederlands en Afrikaans lijken op sommige punten sterk op elkaar, waardoor sprekers elkaar vaak redelijk kunnen verstaan. Toch zijn er ook duidelijke verschillen ontstaan, bijvoorbeeld in grammatica en uitspraak. Afrikaans heeft bijvoorbeeld een eenvoudigere werkwoordvervoeging dan het Nederlands. Voor taalkundigen is Afrikaans daarom een interessant voorbeeld van hoe een taal zich in korte tijd sterk kan ontwikkelen.","De verspreiding van het Nederlands laat zien dat taal en geschiedenis nauw met elkaar verbonden zijn. Door handel, kolonisatie en migratie is het Nederlands op plekken terechtgekomen ver buiten Europa. Vandaag de dag blijft de taal daar, in aangepaste of oorspronkelijke vorm, een belangrijk onderdeel van de lokale cultuur en identiteit, ook al is dat niet bij iedereen bekend."],"questions":[{"text":"Wat is de officiële taal van Suriname?","type":"Detail","options":["Sranantongo","Engels","Nederlands","Spaans"],"correct":2,"highlight":"is Nederlands de officiële taal","feedback":{"ok":"Klopt! Nederlands is de officiële taal van Suriname.","nee":"Niet juist. Alinea 1 noemt Nederlands als officiële taal."}},{"text":"Sinds welke eeuw namen Nederlandse kolonisten hun taal mee naar Zuid-Afrika?","type":"Detail","options":["De vijftiende eeuw","De zestiende eeuw","De zeventiende eeuw","De negentiende eeuw"],"correct":2,"highlight":"vanaf de zeventiende eeuw meenamen naar Zuid-Afrika","feedback":{"ok":"Goed! Vanaf de zeventiende eeuw kwam het Nederlands naar Zuid-Afrika.","nee":"Niet correct. Alinea 2 noemt de zeventiende eeuw."}},{"text":"Wat kun je afleiden over de relatie tussen sprekers van het Nederlands en het Afrikaans?","type":"Inferentie","options":["Ze kunnen elkaar door de gelijkenissen vaak redelijk verstaan","Ze kunnen elkaar helemaal niet verstaan","Afrikaans en Nederlands zijn exact dezelfde taal","Sprekers van Afrikaans begrijpen geen Nederlands geschreven tekst"],"correct":0,"highlight":"sprekers elkaar vaak redelijk kunnen verstaan","feedback":{"ok":"Juist! Door de gelijkenissen kunnen sprekers elkaar vaak verstaan.","nee":"Niet helemaal. Alinea 3 zegt dat sprekers elkaar vaak redelijk kunnen verstaan."}},{"text":"Wat betekent 'werkwoordvervoeging'?","type":"Woordbetekenis","options":["Een lijst met alle werkwoorden in een taal","De uitspraak van een werkwoord","Een werkwoord dat in twee talen hetzelfde is","De manier waarop een werkwoord verandert afhankelijk van tijd en persoon"],"correct":3,"highlight":"een eenvoudigere werkwoordvervoeging dan het Nederlands","feedback":{"ok":"Correct! Werkwoordvervoeging gaat over hoe werkwoorden veranderen.","nee":"Niet juist. Alinea 3 gebruikt 'werkwoordvervoeging' voor hoe werkwoorden veranderen."}},{"text":"Wat is de hoofdboodschap van deze tekst?","type":"Hoofdgedachte","options":["Nederlands wordt tegenwoordig alleen in Nederland gesproken","Door geschiedenis en migratie is het Nederlands ook buiten Europa een blijvend onderdeel van andere culturen geworden","Afrikaans en Nederlands hebben niets met elkaar te maken","Suriname heeft nooit Nederlandse invloed gehad"],"correct":1,"highlight":"een belangrijk onderdeel van de lokale cultuur en identiteit","feedback":{"ok":"Precies! Geschiedenis en migratie verspreidden het Nederlands wereldwijd.","nee":"Niet helemaal. Alinea 4 benadrukt hoe taal en geschiedenis verbonden zijn."}}]},{"topic":"Media","title":"Persvrijheid en de Nederlandse pers","paragraphs":["Persvrijheid betekent dat journalisten vrij nieuws mogen verzamelen en publiceren, zonder censuur van de overheid of angst voor straf. In een land met persvrijheid kunnen kranten en tv-programma's kritisch zijn over de regering. Nederland staat al jaren hoog op internationale lijsten van persvrijheid. Dat betekent dat Nederlandse journalisten relatief veilig hun werk kunnen doen en dat de overheid zich weinig bemoeit met de inhoud van het nieuws.","In Nederland zijn er veel verschillende media: landelijke kranten, regionale nieuwsbladen, radiozenders en de publieke omroep. De publieke omroep wordt gedeeltelijk betaald met belastinggeld, maar werkt onafhankelijk van de politiek. Naast de publieke omroep bestaan er ook commerciële zenders die zich richten op amusement en actualiteiten. Deze diversiteit aan media zorgt ervoor dat burgers nieuws uit verschillende bronnen kunnen vergelijken, wat belangrijk is voor een goed geïnformeerde samenleving.","Toch is persvrijheid niet vanzelfsprekend, ook niet in Nederland. Journalisten die onderzoek doen naar criminaliteit of corruptie krijgen soms te maken met bedreigingen, zowel online als in het echte leven. Sommige kranten hebben ook te maken met financiële problemen, omdat mensen steeds minder betalen voor nieuws. Dit kan ertoe leiden dat er minder onderzoeksjournalistiek wordt gedaan, terwijl juist dat soort journalistiek belangrijk is om misstanden aan het licht te brengen.","Persvrijheid is een belangrijk onderdeel van een democratie. Zonder vrije pers zouden burgers minder goed weten wat er in de samenleving gebeurt en zouden machthebbers minder gecontroleerd worden. Organisaties zoals Reporters Without Borders houden ieder jaar bij hoe het gesteld is met de persvrijheid in verschillende landen. Burgers kunnen zelf ook bijdragen aan een gezonde persvrijheid door betrouwbaar nieuws te steunen en kritisch te blijven over de informatie die ze lezen."],"questions":[{"text":"Waar staat Nederland al jaren hoog op internationale lijsten van?","type":"Detail","options":["persvrijheid","onderwijskwaliteit","economische groei","gezondheidszorg"],"correct":0,"highlight":"Nederland staat al jaren hoog op internationale lijsten van persvrijheid.","feedback":{"ok":"Klopt! Nederland staat internationaal hoog op de lijst van persvrijheid.","nee":"Niet juist. Alinea 1 noemt dat Nederland hoog staat op lijsten van persvrijheid."}},{"text":"Hoe wordt de publieke omroep in Nederland gedeeltelijk betaald?","type":"Detail","options":["Door reclame-inkomsten","Door belastinggeld","Door donaties van kijkers","Door de Europese Unie"],"correct":1,"highlight":"De publieke omroep wordt gedeeltelijk betaald met belastinggeld","feedback":{"ok":"Goed! De publieke omroep wordt deels met belastinggeld betaald.","nee":"Niet correct. Alinea 2 zegt dat de publieke omroep gedeeltelijk met belastinggeld wordt betaald."}},{"text":"Wat kan een gevolg zijn van financiële problemen bij kranten?","type":"Inferentie","options":["Er komt meer onderzoeksjournalistiek","Kranten worden helemaal gratis","Er wordt minder onderzoeksjournalistiek gedaan","Journalisten krijgen meer bescherming"],"correct":2,"highlight":"Dit kan ertoe leiden dat er minder onderzoeksjournalistiek wordt gedaan","feedback":{"ok":"Precies! Financiële problemen kunnen leiden tot minder onderzoeksjournalistiek.","nee":"Niet helemaal. Alinea 3 legt uit dat financiële problemen kunnen leiden tot minder onderzoeksjournalistiek."}},{"text":"Wat betekent 'onderzoeksjournalistiek'?","type":"Woordbetekenis","options":["Nieuws dat snel wordt geschreven zonder controle","Journalistiek die alleen over sport gaat","Nieuws dat door de overheid wordt geschreven","Diepgaand journalistiek onderzoek naar misstanden"],"correct":3,"highlight":"onderzoeksjournalistiek","feedback":{"ok":"Juist! Onderzoeksjournalistiek is diepgaand onderzoek naar misstanden.","nee":"Niet juist. Alinea 3 gebruikt het woord voor diepgaand onderzoek naar misstanden."}},{"text":"Wat is de hoofdboodschap van deze tekst?","type":"Hoofdgedachte","options":["Persvrijheid is belangrijk voor democratie, maar staat soms onder druk","Nederlandse kranten hebben nooit financiële problemen","Persvrijheid bestaat alleen buiten Europa","Alleen de overheid mag nieuws maken"],"correct":0,"highlight":"Persvrijheid is een belangrijk onderdeel van een democratie.","feedback":{"ok":"Mooi! Persvrijheid is belangrijk voor de democratie, maar staat soms onder druk.","nee":"Niet helemaal. De kern is dat persvrijheid belangrijk is voor de democratie, al staat die soms onder druk."}}]},{"topic":"Onderwijs","title":"Steeds meer buitenlandse studenten in Nederland","paragraphs":["Elk jaar kiezen duizenden buitenlandse studenten voor een studie in Nederland. Ze komen vooral uit Duitsland, China, Italië en andere Europese landen. Nederlandse universiteiten bieden veel opleidingen aan in het Engels, wat het voor internationale studenten makkelijker maakt om hier te studeren. Daarnaast staat het Nederlandse onderwijs internationaal goed bekend, en dat trekt studenten aan die op zoek zijn naar een kwalitatief goede opleiding buiten hun eigen land.","Voor universiteiten heeft internationalisering ook voordelen. Buitenlandse studenten brengen andere perspectieven mee de collegezalen in, en instellingen kunnen door hen makkelijker samenwerken met buitenlandse partners. Bovendien betalen sommige buitenlandse studenten hogere collegegelden, wat extra inkomsten oplevert voor de universiteit. Universiteiten profiteren dus zowel financieel als inhoudelijk van de internationale studenten die zich inschrijven voor een opleiding in Nederland.","Toch is er ook kritiek op het grote aantal internationale studenten. Sommige mensen vinden dat er te weinig woonruimte is voor al deze studenten, waardoor de druk op de woningmarkt in studentensteden toeneemt. Ook wordt er geklaagd dat sommige opleidingen bijna volledig in het Engels worden gegeven, terwijl er te weinig plek overblijft voor Nederlandse studenten. Daarom hebben universiteiten en de overheid maatregelen genomen om het aantal internationale studenten te beperken.","De discussie over internationale studenten laat zien hoe lastig het is om de voordelen en nadelen van internationalisering tegen elkaar af te wegen. Internationale studenten dragen bij aan de economie en de kwaliteit van het onderwijs, maar zorgen ook voor extra druk op voorzieningen zoals huisvesting. De komende jaren zullen universiteiten en de overheid moeten blijven zoeken naar een goede balans tussen deze twee kanten van het verhaal."],"questions":[{"text":"Uit welke landen komen relatief veel buitenlandse studenten naar Nederland?","type":"Detail","options":["Rusland, Canada en Japan","Australië, Brazilië en Egypte","Zweden, Noorwegen en Finland","Duitsland, China en Italië"],"correct":3,"highlight":"Ze komen vooral uit Duitsland, China, Italië en andere Europese landen.","feedback":{"ok":"Klopt! Veel studenten komen uit Duitsland, China en Italië.","nee":"Niet juist. Alinea 1 noemt Duitsland, China en Italië als herkomstlanden."}},{"text":"Wat is een financieel voordeel van internationale studenten voor universiteiten?","type":"Detail","options":["Ze betalen soms hogere collegegelden","Ze werken gratis voor de universiteit","Ze krijgen minder subsidie","Ze hoeven geen belasting te betalen"],"correct":0,"highlight":"sommige buitenlandse studenten hogere collegegelden","feedback":{"ok":"Juist! Sommige buitenlandse studenten betalen hogere collegegelden.","nee":"Niet correct. Alinea 2 zegt dat sommige buitenlandse studenten hogere collegegelden betalen."}},{"text":"Waarom hebben universiteiten en de overheid maatregelen genomen tegen het aantal internationale studenten?","type":"Inferentie","options":["Omdat er te veel Nederlandse docenten zijn","Omdat internationale studenten slechte cijfers halen","Omdat de druk op de woningmarkt en het Engelstalig onderwijs een probleem werden","Omdat er te weinig belangstelling is voor studeren in Nederland"],"correct":2,"highlight":"de druk op de woningmarkt in studentensteden toeneemt","feedback":{"ok":"Precies! De druk op de woningmarkt en het aanbod aan Engelstalig onderwijs speelden mee.","nee":"Niet helemaal. Alinea 3 noemt de druk op de woningmarkt als reden voor maatregelen."}},{"text":"Wat betekent 'internationalisering' zoals gebruikt in de tekst?","type":"Woordbetekenis","options":["Het sluiten van een universiteit","Het proces waarbij een organisatie meer internationale contacten en leden krijgt","Het verlagen van collegegeld voor iedereen","Het aanbieden van alleen Nederlandstalig onderwijs"],"correct":1,"highlight":"voordelen en nadelen van internationalisering","feedback":{"ok":"Goed! Internationalisering betekent meer internationale contacten en leden.","nee":"Niet juist. Alinea 4 gebruikt het woord voor het proces waarbij iets internationaler wordt."}},{"text":"Wat is de kern van de tekst?","type":"Hoofdgedachte","options":["Internationale studenten zijn alleen maar nadelig","Internationale studenten brengen voordelen én uitdagingen met zich mee","Nederlandse universiteiten willen geen buitenlandse studenten meer","Alleen Chinese studenten kiezen voor Nederland"],"correct":1,"highlight":"Internationale studenten dragen bij aan de economie en de kwaliteit van het onderwijs, maar zorgen ook voor extra druk op voorzieningen zoals huisvesting.","feedback":{"ok":"Mooi! Internationale studenten brengen zowel voordelen als uitdagingen met zich mee.","nee":"Niet helemaal. Alinea 4 laat zien dat er zowel voordelen als uitdagingen zijn."}}]},{"topic":"Duurzaamheid","title":"Kringloopwinkels: tweedehands met een tweede leven","paragraphs":["Een kringloopwinkel is een winkel waar mensen tweedehands spullen kunnen kopen en verkopen. Denk aan kleding, meubels, boeken en speelgoed. Mensen brengen spullen die ze niet meer gebruiken naar de kringloopwinkel, zodat andere mensen er weer plezier van kunnen hebben. Op deze manier krijgen spullen een tweede leven in plaats van dat ze worden weggegooid. In bijna elke Nederlandse stad is wel een kringloopwinkel te vinden.","Kringloopwinkels zijn de laatste jaren populairder geworden, vooral onder jongeren. Steeds meer mensen maken zich zorgen over het milieu en willen minder nieuwe spullen kopen. Tweedehands kleding kopen is namelijk veel duurzamer dan nieuwe kleding kopen, omdat er voor tweedehands kleding geen nieuwe grondstoffen nodig zijn. Daarnaast vinden veel mensen het leuk om unieke spullen te vinden die je niet in een gewone winkel kunt kopen.","Kringloopwinkels hebben ook een sociale functie. Veel kringloopwinkels worden gerund door vrijwilligers of door mensen die met een uitkering werkervaring willen opdoen. Zo helpt de kringloopwinkel niet alleen het milieu, maar ook mensen die weer aan het werk willen. Bovendien zijn de prijzen in een kringloopwinkel meestal veel lager dan in een gewone winkel, waardoor ook mensen met een klein budget makkelijker aan spullen kunnen komen.","De groei van kringloopwinkels past bij een grotere trend: mensen denken steeds vaker na over de gevolgen van hun consumptiegedrag. In plaats van spullen weg te gooien, kiezen steeds meer mensen ervoor om ze te doneren of tweedehands te kopen. Kringloopwinkels laten zien dat duurzaamheid en besparen prima samen kunnen gaan, en dat oude spullen vaak nog heel bruikbaar zijn voor iemand anders."],"questions":[{"text":"Wat voor spullen kun je bij een kringloopwinkel kopen?","type":"Detail","options":["Alleen elektronica","Alleen auto-onderdelen","Kleding, meubels, boeken en speelgoed","Alleen nieuwe kleding"],"correct":2,"highlight":"kleding, meubels, boeken en speelgoed","feedback":{"ok":"Klopt! Je kunt onder andere kleding, meubels, boeken en speelgoed kopen.","nee":"Niet juist. Alinea 1 noemt kleding, meubels, boeken en speelgoed als voorbeelden."}},{"text":"Waarom is tweedehands kleding kopen duurzamer dan nieuwe kleding kopen?","type":"Detail","options":["Omdat het altijd goedkoper is","Omdat het van betere kwaliteit is","Omdat winkels het aanmoedigen","Omdat er geen nieuwe grondstoffen voor nodig zijn"],"correct":3,"highlight":"er voor tweedehands kleding geen nieuwe grondstoffen nodig zijn","feedback":{"ok":"Precies! Voor tweedehands kleding zijn geen nieuwe grondstoffen nodig.","nee":"Niet correct. Alinea 2 legt uit dat er geen nieuwe grondstoffen nodig zijn."}},{"text":"Wat suggereert de tekst over wie er in kringloopwinkels werken?","type":"Inferentie","options":["Mensen die met een uitkering werkervaring willen opdoen","Alleen betaalde managers","Alleen studenten in deeltijd","Alleen de eigenaar van de winkel"],"correct":0,"highlight":"mensen die met een uitkering werkervaring willen opdoen","feedback":{"ok":"Goed! Veel medewerkers zijn mensen die met een uitkering werkervaring willen opdoen.","nee":"Niet helemaal. Alinea 3 noemt vrijwilligers en mensen met een uitkering als medewerkers."}},{"text":"Wat betekent 'consumptiegedrag'?","type":"Woordbetekenis","options":["De manier waarop mensen spullen kopen en gebruiken","Het weggooien van oud eten","Het produceren van nieuwe kleding","Het beheren van een winkel"],"correct":0,"highlight":"de gevolgen van hun consumptiegedrag","feedback":{"ok":"Juist! Consumptiegedrag is de manier waarop mensen spullen kopen en gebruiken.","nee":"Niet juist. Alinea 4 gebruikt het woord voor hoe mensen spullen kopen en gebruiken."}},{"text":"Wat is de belangrijkste boodschap van de tekst?","type":"Hoofdgedachte","options":["Kringloopwinkels zijn alleen voor arme mensen","Kringloopwinkels gaan binnenkort verdwijnen","Kringloopwinkels combineren duurzaamheid, besparen en sociale hulp","Kringloopwinkels verkopen alleen nieuwe spullen"],"correct":2,"highlight":"duurzaamheid en besparen prima samen kunnen gaan","feedback":{"ok":"Mooi! Kringloopwinkels combineren duurzaamheid, besparen en sociale hulp.","nee":"Niet helemaal. Alinea 4 laat zien dat duurzaamheid en besparen samengaan."}}]},{"topic":"Natuur","title":"Volkstuinen: een eigen plekje groen","paragraphs":["Een volkstuin is een stuk grond dat mensen kunnen huren om er groenten, fruit of bloemen te kweken. Volkstuinen liggen meestal aan de rand van een stad, bij elkaar op een groot terrein met tientallen andere tuintjes. Vooral mensen die in een flat of appartement wonen zonder eigen tuin, huren een volkstuin om toch buiten bezig te kunnen zijn met planten.","De eerste volkstuinen in Nederland ontstonden meer dan honderd jaar geleden. Ze waren bedoeld voor arbeiders die weinig geld hadden en op deze manier zelf hun eigen groenten konden verbouwen. Tegenwoordig is de reden om een volkstuin te huren vaak anders: mensen willen graag ontspannen, tijd doorbrengen in de natuur of gezonder eten met groenten uit eigen tuin. De wachtlijsten voor een volkstuin zijn in veel steden dan ook lang.","Werken in een volkstuin kost tijd en aandacht. Je moet regelmatig onkruid wieden, water geven en de grond bewerken. Toch vinden veel tuinders dit juist ontspannend, omdat het een goede afwisseling is met een drukke baan of een leven in de stad. Bovendien ontmoeten volkstuinders elkaar op het complex en ontstaan er vaak vriendschappen tussen mensen die anders elkaar nooit hadden leren kennen.","Volkstuinen zijn niet alleen goed voor de mensen die er tuinieren, maar ook voor de stad zelf. Ze zorgen voor extra groen tussen de gebouwen, wat goed is voor insecten en vogels. Ook helpt al dat groen om steden koeler te houden tijdens warme zomers. Daarom proberen veel gemeenten om volkstuinen te behouden, ook al is er in steden steeds meer vraag naar bouwgrond voor nieuwe woningen."],"questions":[{"text":"Wie huurt vooral een volkstuin?","type":"Detail","options":["Mensen die al een grote tuin hebben","Alleen boeren","Alleen gepensioneerden","Mensen die in een flat of appartement wonen zonder tuin"],"correct":3,"highlight":"mensen die in een flat of appartement wonen zonder eigen tuin","feedback":{"ok":"Klopt! Vooral mensen zonder eigen tuin huren een volkstuin.","nee":"Niet juist. Alinea 1 noemt mensen die in een flat of appartement wonen zonder tuin."}},{"text":"Waarvoor waren de eerste volkstuinen in Nederland bedoeld?","type":"Detail","options":["Voor arbeiders om zelf groenten te verbouwen","Voor toeristen om te wandelen","Voor bedrijven om kantoren te bouwen","Voor scholen om buiten les te geven"],"correct":0,"highlight":"bedoeld voor arbeiders die weinig geld hadden en op deze manier zelf hun eigen groenten konden verbouwen","feedback":{"ok":"Goed! De eerste volkstuinen waren voor arbeiders om zelf groenten te verbouwen.","nee":"Niet correct. Alinea 2 zegt dat de eerste volkstuinen bedoeld waren voor arbeiders."}},{"text":"Waarom zijn de wachtlijsten voor volkstuinen in veel steden lang?","type":"Inferentie","options":["Omdat volkstuinen duur zijn om te huren","Omdat gemeenten volkstuinen verbieden","Omdat er steeds meer belangstelling is voor ontspanning en natuur","Omdat volkstuinen alleen 's zomers open zijn"],"correct":2,"highlight":"mensen willen graag ontspannen, tijd doorbrengen in de natuur","feedback":{"ok":"Precies! Meer mensen willen ontspannen en tijd doorbrengen in de natuur.","nee":"Niet helemaal. Alinea 2 noemt ontspanning en natuur als redenen voor de populariteit."}},{"text":"Wat betekent 'onkruid wieden'?","type":"Woordbetekenis","options":["Groenten oogsten","Ongewenste planten verwijderen","Water geven aan planten","Grond omspitten voor de winter"],"correct":1,"highlight":"onkruid wieden","feedback":{"ok":"Juist! Onkruid wieden betekent ongewenste planten verwijderen.","nee":"Niet juist. Alinea 3 noemt onkruid wieden als onderdeel van het tuinwerk."}},{"text":"Wat is de hoofdboodschap van de tekst?","type":"Hoofdgedachte","options":["Volkstuinen zijn goed voor zowel tuinders als de stad","Volkstuinen zijn alleen nuttig voor arbeiders van vroeger","Gemeenten willen alle volkstuinen sluiten","Volkstuinen zijn nutteloos voor het milieu"],"correct":0,"highlight":"Volkstuinen zijn niet alleen goed voor de mensen die er tuinieren, maar ook voor de stad zelf.","feedback":{"ok":"Mooi! Volkstuinen zijn goed voor zowel de tuinders als de stad.","nee":"Niet helemaal. Alinea 4 laat zien dat volkstuinen goed zijn voor mensen én de stad."}}]},{"topic":"Vervoer","title":"De nachttrein: langzaam terug van weggeweest","paragraphs":["Een nachttrein is een trein die 's avonds vertrekt en pas de volgende ochtend op de eindbestemming aankomt. Reizigers slapen tijdens de reis in een slaapcoupé of een zitplaats. Vroeger waren nachttreinen een populaire manier om door Europa te reizen, maar vanaf de jaren negentig verdwenen steeds meer verbindingen. Goedkope vliegtickets en snelle dagtreinen zorgden ervoor dat minder mensen voor de nachttrein kozen.","De laatste jaren is er weer meer belangstelling voor de nachttrein. Steeds meer reizigers willen minder vliegen vanwege de gevolgen voor het klimaat, en zoeken naar alternatieven om lange afstanden te overbruggen. De nachttrein is dan een handige optie: je reist terwijl je slaapt en bespaart zo een overnachting in een hotel. Bovendien vinden veel mensen een treinreis ontspannender dan een vlucht met wachttijden op het vliegveld.","Verschillende Europese spoorwegmaatschappijen hebben de afgelopen jaren nieuwe nachttreinverbindingen geopend, bijvoorbeeld tussen Nederland en steden als Wenen, Berlijn en Zürich. Deze treinen zijn vaak snel volgeboekt, wat laat zien dat de vraag naar nachttreinen groeit. Toch is het niet eenvoudig om nieuwe verbindingen op te zetten, omdat er speciale treinstellen nodig zijn en spoorwegmaatschappijen uit verschillende landen goed moeten samenwerken.","Experts denken dat de nachttrein de komende jaren verder kan groeien, vooral als treinreizen goedkoper en sneller worden. Toch zal de nachttrein het vliegtuig waarschijnlijk niet helemaal vervangen, omdat vliegen voor lange afstanden vaak nog sneller blijft. Voor reizen van ongeveer duizend kilometer kan de nachttrein echter een aantrekkelijk alternatief zijn, zeker voor mensen die op een duurzamere manier willen reizen."],"questions":[{"text":"Wanneer begonnen veel nachttreinverbindingen te verdwijnen?","type":"Detail","options":["Vanaf de jaren zeventig","Vanaf 2010","Vanaf de jaren negentig","Vanaf de jaren vijftig"],"correct":2,"highlight":"vanaf de jaren negentig verdwenen steeds meer verbindingen","feedback":{"ok":"Klopt! Vanaf de jaren negentig verdwenen veel nachttreinverbindingen.","nee":"Niet juist. Alinea 1 noemt de jaren negentig als het moment waarop verbindingen verdwenen."}},{"text":"Waarom kiezen reizigers tegenwoordig weer vaker voor de nachttrein?","type":"Detail","options":["Omdat vliegen duurder is geworden dan de trein","Omdat nachttreinen sneller zijn dan vliegtuigen","Omdat er geen vliegvelden meer zijn","Omdat ze minder willen vliegen vanwege het klimaat"],"correct":3,"highlight":"Steeds meer reizigers willen minder vliegen vanwege de gevolgen voor het klimaat","feedback":{"ok":"Goed! Veel reizigers willen minder vliegen vanwege het klimaat.","nee":"Niet correct. Alinea 2 noemt het klimaat als reden om minder te vliegen."}},{"text":"Waarom is het niet eenvoudig om nieuwe nachttreinverbindingen op te zetten?","type":"Inferentie","options":["Omdat treinstellen en samenwerking tussen landen nodig zijn","Omdat er te weinig reizigers geïnteresseerd zijn","Omdat nachttreinen verboden zijn in de meeste landen","Omdat er geen sporen tussen landen liggen"],"correct":0,"highlight":"er speciale treinstellen nodig zijn en spoorwegmaatschappijen uit verschillende landen goed moeten samenwerken","feedback":{"ok":"Precies! Er zijn speciale treinstellen en samenwerking tussen landen nodig.","nee":"Niet helemaal. Alinea 3 legt uit dat treinstellen en internationale samenwerking nodig zijn."}},{"text":"Wat is een 'slaapcoupé'?","type":"Woordbetekenis","options":["Een restaurantwagon in de trein","Het bagagerek boven de zitplaatsen","Een ruimte in de trein waar je kunt slapen","Een aparte trein alleen voor bagage"],"correct":2,"highlight":"slapen tijdens de reis in een slaapcoupé","feedback":{"ok":"Juist! Een slaapcoupé is een ruimte in de trein om te slapen.","nee":"Niet juist. Alinea 1 noemt de slaapcoupé als plek om te slapen."}},{"text":"Wat is de kern van de tekst?","type":"Hoofdgedachte","options":["De nachttrein vervangt binnenkort alle vliegtuigen","De nachttrein groeit weer als duurzaam alternatief, maar vervangt het vliegtuig niet volledig","De nachttrein is helemaal verdwenen uit Europa","Niemand wil meer met de nachttrein reizen"],"correct":1,"highlight":"de nachttrein het vliegtuig waarschijnlijk niet helemaal vervangen","feedback":{"ok":"Mooi! De nachttrein groeit als duurzaam alternatief, maar vervangt het vliegtuig niet volledig.","nee":"Niet helemaal. Alinea 4 zegt dat de nachttrein groeit, maar het vliegtuig niet helemaal vervangt."}}]},{"topic":"Bibliotheken","title":"Openbare bibliotheken in het digitale tijdperk","paragraphs":["Vroeger gingen mensen vooral naar de bibliotheek om boeken te lenen. Tegenwoordig kun je in een openbare bibliotheek veel meer doen: er zijn computers om te gebruiken, cursussen om digitale vaardigheden te leren en ruimtes waar mensen rustig kunnen studeren of werken. Doordat steeds meer informatie digitaal beschikbaar is, hebben bibliotheken hun functie in de loop van de tijd flink aangepast.","Ook het aanbod van boeken is veranderd. Naast papieren boeken kunnen mensen bij veel bibliotheken ook e-books en luisterboeken lenen via een app. Dit is handig voor mensen die onderweg willen lezen of die liever naar een boek luisteren dan het te lezen. Toch blijft het papieren boek populair, vooral omdat lezers geen scherm hoeven te gebruiken en niet afgeleid worden door meldingen.","Bibliotheken spelen ook een belangrijke sociale rol. Voor mensen die moeite hebben met lezen of schrijven, of die de digitale wereld lastig vinden, bieden bibliotheken gratis hulp en cursussen aan. Ouderen kunnen er bijvoorbeeld leren omgaan met een smartphone of internetbankieren. Daarnaast is de bibliotheek voor veel mensen een plek waar ze zonder te betalen naartoe kunnen, wat belangrijk is in een tijd waarin steeds meer voorzieningen geld kosten.","Ondanks deze veranderingen staat de toekomst van de bibliotheek niet vast. Gemeenten moeten kiezen hoeveel geld ze besteden aan bibliotheken, en in sommige plaatsen zijn vestigingen gesloten vanwege bezuinigingen. Toch laten onderzoeken zien dat veel mensen de bibliotheek nog steeds waardevol vinden, juist omdat het een van de weinige plekken is waar iedereen welkom is, ongeacht hoeveel geld iemand heeft. Investeren blijft daarom belangrijk voor veel gemeenten."],"questions":[{"text":"Wat kun je tegenwoordig doen in een openbare bibliotheek, naast boeken lenen?","type":"Detail","options":["Alleen fitnessen","Auto's repareren","Kleding kopen","Computers gebruiken en cursussen volgen"],"correct":3,"highlight":"er zijn computers om te gebruiken, cursussen om digitale vaardigheden te leren","feedback":{"ok":"Klopt! Je kunt er onder andere computers gebruiken en cursussen volgen.","nee":"Niet juist. Alinea 1 noemt computers en cursussen als extra mogelijkheden."}},{"text":"Wat kunnen ouderen bijvoorbeeld leren in de bibliotheek?","type":"Detail","options":["Omgaan met een smartphone of internetbankieren","Autorijden","Koken","Een taal leren binnen één dag"],"correct":0,"highlight":"leren omgaan met een smartphone of internetbankieren","feedback":{"ok":"Goed! Ouderen kunnen leren omgaan met een smartphone of internetbankieren.","nee":"Niet correct. Alinea 3 noemt smartphone- en internetbankiervaardigheden."}},{"text":"Waarom is de bibliotheek belangrijk voor mensen met weinig geld?","type":"Inferentie","options":["Omdat de bibliotheek boeken verkoopt met korting","Omdat de bibliotheek geld uitdeelt aan bezoekers","Omdat de bibliotheek een gratis toegankelijke plek is voor iedereen","Omdat de bibliotheek alleen voor arme mensen bedoeld is"],"correct":2,"highlight":"een plek waar ze zonder te betalen naartoe kunnen","feedback":{"ok":"Precies! De bibliotheek is een gratis toegankelijke plek voor iedereen.","nee":"Niet helemaal. Alinea 3 zegt dat de bibliotheek een plek is waar je zonder te betalen naartoe kunt."}},{"text":"Wat betekent 'bezuinigingen'?","type":"Woordbetekenis","options":["Het verhogen van lonen","Het verminderen van uitgaven","Het bouwen van nieuwe gebouwen","Het aannemen van meer personeel"],"correct":1,"highlight":"vestigingen gesloten vanwege bezuinigingen","feedback":{"ok":"Juist! Bezuinigingen betekent het verminderen van uitgaven.","nee":"Niet juist. Alinea 4 noemt bezuinigingen als reden voor het sluiten van vestigingen."}},{"text":"Wat is de hoofdboodschap van de tekst?","type":"Hoofdgedachte","options":["Bibliotheken zijn niet meer nodig door internet","Bibliotheken bestaan alleen nog voor kinderen","Iedereen moet voortaan alleen e-books lezen","Bibliotheken hebben zich aangepast aan de digitale tijd en blijven waardevol"],"correct":3,"highlight":"veel mensen de bibliotheek nog steeds waardevol vinden","feedback":{"ok":"Mooi! Bibliotheken hebben zich aangepast en blijven waardevol.","nee":"Niet helemaal. Alinea 4 laat zien dat bibliotheken zich hebben aangepast en waardevol blijven."}}]},{"topic":"Geschiedenis","title":"Bevrijdingsdag: vrijheid vieren op 5 mei","paragraphs":["Op 5 mei viert Nederland Bevrijdingsdag. Op deze dag herdenken Nederlanders dat het land aan het einde van de Tweede Wereldoorlog werd bevrijd van de Duitse bezetting. Nederland was van 1940 tot 1945 bezet, en in die periode hadden mensen geen vrijheid van meningsuiting en werden groepen mensen, zoals Joodse Nederlanders, vervolgd. Sinds 1990 is 5 mei een officiële nationale feestdag.","De dag voor Bevrijdingsdag, op 4 mei, is er juist een moment van stilte. Dan herdenkt Nederland alle mensen die zijn omgekomen in oorlogen sinds het begin van de Tweede Wereldoorlog. Om acht uur 's avonds is er twee minuten stilte in het hele land. Dit contrast tussen herdenken op 4 mei en vieren op 5 mei laat zien hoe belangrijk beide momenten voor Nederlanders zijn.","Op 5 mei zelf worden er in het hele land bevrijdingsfestivals georganiseerd, met muziek, eten en toespraken over vrijheid. Veel festivals zijn gratis toegankelijk, zodat iedereen mee kan doen. Scholen besteden in de dagen voor 5 mei vaak aandacht aan de oorlog en de bevrijding, bijvoorbeeld door verhalen van ooggetuigen te bespreken. Zo leren jongere generaties waarom vrijheid niet vanzelfsprekend is.","Bevrijdingsdag gaat niet alleen over het verleden. Op de festivals en tijdens toespraken wordt vaak ook stilgestaan bij vrijheid in de wereld van vandaag, bijvoorbeeld over landen waar mensen nog steeds geen persvrijheid of andere vrijheden hebben. Door de oorlog te herdenken én vrijheid te vieren, wil Nederland ervoor zorgen dat toekomstige generaties zich bewust blijven van hoe belangrijk vrijheid is."],"questions":[{"text":"Van wanneer tot wanneer was Nederland bezet tijdens de Tweede Wereldoorlog?","type":"Detail","options":["1935 tot 1940","1945 tot 1950","1940 tot 1945","1939 tot 1944"],"correct":2,"highlight":"Nederland was van 1940 tot 1945 bezet","feedback":{"ok":"Klopt! Nederland was van 1940 tot 1945 bezet.","nee":"Niet juist. Alinea 1 noemt de periode 1940 tot 1945."}},{"text":"Hoe laat is de stilte op 4 mei?","type":"Detail","options":["Om zes uur 's avonds","Om twaalf uur 's middags","Om tien uur 's avonds","Om acht uur 's avonds"],"correct":3,"highlight":"Om acht uur 's avonds is er twee minuten stilte","feedback":{"ok":"Goed! Om acht uur 's avonds is er twee minuten stilte.","nee":"Niet correct. Alinea 2 noemt acht uur 's avonds als tijdstip van de stilte."}},{"text":"Waarom zijn veel bevrijdingsfestivals gratis toegankelijk?","type":"Inferentie","options":["Omdat de overheid festivals wil ontmoedigen","Zodat iedereen kan meedoen, ongeacht geld","Omdat er te weinig bezoekers zijn","Omdat festivals worden gesponsord door bedrijven"],"correct":1,"highlight":"Veel festivals zijn gratis toegankelijk, zodat iedereen mee kan doen.","feedback":{"ok":"Precies! Zo kan iedereen meedoen, ongeacht hoeveel geld iemand heeft.","nee":"Niet helemaal. Alinea 3 zegt dat festivals gratis zijn zodat iedereen mee kan doen."}},{"text":"Wat betekent 'ooggetuigen' in de tekst?","type":"Woordbetekenis","options":["Mensen die iets zelf hebben meegemaakt of gezien","Mensen die de oorlog hebben bestudeerd in boeken","Officiële historici van de overheid","Mensen die films maken over de oorlog"],"correct":0,"highlight":"verhalen van ooggetuigen te bespreken","feedback":{"ok":"Juist! Ooggetuigen zijn mensen die iets zelf hebben meegemaakt of gezien.","nee":"Niet juist. Alinea 3 noemt ooggetuigen als mensen die de oorlog zelf hebben meegemaakt."}},{"text":"Wat is de hoofdboodschap van de tekst?","type":"Hoofdgedachte","options":["Bevrijdingsdag is alleen een feest zonder betekenis","Bevrijdingsdag wordt niet meer gevierd in Nederland","Bevrijdingsdag herdenkt de oorlog en viert het belang van vrijheid","Bevrijdingsdag gaat alleen over voetbal"],"correct":2,"highlight":"Door de oorlog te herdenken én vrijheid te vieren, wil Nederland ervoor zorgen dat toekomstige generaties zich bewust blijven van hoe belangrijk vrijheid is.","feedback":{"ok":"Mooi! Bevrijdingsdag herdenkt de oorlog en viert tegelijk het belang van vrijheid.","nee":"Niet helemaal. Alinea 4 laat zien dat de dag zowel herdenken als vrijheid vieren combineert."}}]}];
